SELECT 'moj-all-verified-judgments-review-002-chunk-005' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"7cd24718-9020-50ba-aa70-23a736039897","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع عقار -بيع قطعة أرض بعقد -إفراغ قطعة أرض أخرى مبخطط آخر -الداللة ومقابلها -املطالبة بفسخ العقد وإعادة ثمن األرض وأجرة الداللة -عدم صحة البيع لالختاف بن املعقود عليه والواقع -احلكم بفسخ العقد وإعادة الثمن وأجرة الداللة ورفض","document_number":"34186372","case_number":"3436313","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/13","year":"1434","subject":"بيع عقار -بيع قطعة أرض بعقد -إفراغ قطعة أرض أخرى مبخطط آخر -الداللة ومقابلها -املطالبة بفسخ العقد وإعادة ثمن األرض وأجرة الداللة -عدم صحة البيع لالختاف بن املعقود عليه والواقع -احلكم بفسخ العقد وإعادة الثمن وأجرة الداللة ورفض","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/13 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34186372 :‬‬\n                          ‫َر ْق ُم الدعوى‪3436313 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34277873‬تاريخه‪1434/7/24 :‬هـ‬\n\n\n      ‫بيع عقار ‪ -‬بيع قطعة أرض بعقد ‪ -‬إفراغ قطعة أرض أخرى مبخطط‬\n      ‫آخــر ‪ -‬الداللــة ومقابلهــا ‪ -‬املطالبــة بفســخ العقــد وإعــادة ثمــن األرض‬\n      ‫وأجــرة الداللــة ‪ -‬عــدم صحــة البيــع لالختــاف بــن املعقــود عليــه‬\n      ‫والواقــع ‪ -‬احلكــم بفســخ العقــد وإعــادة الثمــن وأجــرة الداللــة ورفــض‬\n                                                                  ‫مــا عــدا ذلــك ‪.‬‬\n\n\n\n\n                        ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n      ‫قــام املدعــي بشــراء قطعــة أرض مقابــل ثمــن معــن‪ ،‬كمــا قــام بتســليم‬\n      ‫مبلــغ مــن املــال ملــن د ّلــه علــى هــذه القطعــة‪ ،‬وقد وافــق على القيــام بإفراغ‬\n      ‫قطعــة أرض أخــرى مبخطــط آخــر بنفــس مســاحة القطعــة األولــى‪،‬‬\n      ‫وعنــد البنــاء وبعــد شــهر مــن اإلفــراغ تبــن أن األرض املفرغــة غيــر التــي‬\n      ‫وقــع عليهــا العقــد األمــر الــذي يســتوجب احلكــم بفســخ العقــد وإلــزام‬\n      ‫املدعــى عليــه بإعــادة املبلــغ الــذي تســلمه قيمــة األرض وكذلــك أربــاح‬\n                                                       ‫هــذا املبلــغ هكــذا ادعــى ‪.‬‬\n      ‫رفــض مــوكل املدعــى عليــه‪ ،‬رد ثمــن األرض‪ ،‬أقــر الــدالل (الوســيط)‬\n      ‫بداللتــه وقبضــه ثمــن ذلــك واســتعداده لــرد املبلــغ حــن ثبــوت اإلفــراغ‪،‬‬\n\n‫‪209‬‬\n\f‫مــن كل مــا تقــدم وقيــام املدعــى عليــه وكالــة باملصادقــة علــى مــا قــرره‬\n‫املدعــي‪ ،‬وجــود شــيك بالديــون وســند للقبــض‪ ،‬وقــوع البيــع علــى مــا‬\n‫تراضــى عليــه الطرفــان مــن العــن والثمــن‪ ،‬عــدم رضــاء املدعــي بــاألرض‬\n‫املفرغــة‪ ،‬عــدم ملكيــة املدعــى عليــه لــأرض املفرغــة التــي وقــع عليهــا‬\n‫البيــع ومــن ثــم عــدم صحــة البيــع‪ ،‬وألن امللــك ال يعنــي تصحيــح العقــد‬\n‫أو إفســاده‪ ،‬وأن مــال املســلم ال يحــل إال بطيــب نفــس منــه‪ ،‬حكمــت‬\n‫احملكمــة ‪ -1‬إلــزام املدعــى عليــه بــرد مبلــغ األرض ‪ -2‬رد املدعــى‬\n‫عليهمــا مبلــغ الداللــة ‪ -3‬رد دعــوى املدعــي باملطالبــة بأربــاح املبلــغ الــذي‬\n‫ســلمه‪ .‬ومبــا ســبق حكمــت احملكمــة وأفهــم القاضــي املدعــى عليــه‬\n‫وكالــة أن ملوكلــه ‪ ...............‬ميــن املدعــي أنــه لــم يــرض بــاألرض محــل‬\n‫اإلفــراغ ‪ -‬قنــع املدعــي باحلكــم ولــم يقنــع املدعــى عليــه ‪ -‬صــدق احلكــم‬\n                                                     ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 3436313‬وتاريــخ‬\n‫‪ 1434/01/20‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34176550‬وتاريــخ‬\n‫‪ 1434/01/20‬ه ـ حضــر منصــور ‪ ..........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ...........‬وحضــر حلضــوره ‪ .........‬ســعودي بالســجل‬\n‫املدنــي رقــم ‪ ..........‬و ‪ .......‬ســعودي بالســجل املدنــي رقــم ‪ .........‬و ‪...........‬‬\n‫ســعودي بالســجل املدنــي رقــم ‪ ..........‬بصفتــه وكيــا عــن ‪...........‬‬\n‫ســعودي بالســجل املدنــي رقــم ‪ ................‬مبوجــب الوكالــة الصــادرة‬\n\n                                                                                              ‫‪210‬‬\n\f      ‫مــن كتابــة العــدل الثانيــة مبكــة برقــم ‪ 34339717‬يف ‪1434/3/18‬ه ـ‬\n      ‫والتــي تخولــه حــق املرافعــة واملدافعــة واإلقــرار واإلنــكار والصلــح‬\n      ‫واجلــرح والتعديــل إلــخ وادعــى األول قائــا إننــي اشــتريت مــن ‪............‬‬\n      ‫قطعــة أرض بــأم الكتــاد خلــف االســكان مبكــة ورقــم القطعــة ‪....‬‬\n      ‫مســاحتها ‪750‬م‪ 2‬بثمــن قــدره مليــون وأربعمائــة ألــف ريــال كمــا ســلمت‬\n      ‫أربعــن ألــف ريــال داللــة ملــن دلنــي علــى األرض وهــم ‪..........‬و‪ ............‬ثــم‬\n      ‫أنــه أفــرغ لــي أرضــا أخــرى مبخطــط الهــدى خلــف مخطــط أم الكتــاد‬\n      ‫أرضــا رقــم القطعــة ‪ ...‬بنفــس املســاحة املذكــورة للقطعــة األولــى علــى‬\n      ‫أنهــا هــي وغلطــة منــي وافقــت علــى هــذا االفــراغ ووقعــت عليــه فلمــا‬\n      ‫أردت البنــاء بعــد شــهر تقريبــا مــن االفــراغ تبــن أن األرض املفرغــة‬\n      ‫غيــر التــي وقــع عليهــا العقــد بينــي وبــن املدعــى عليــه البائــع لــذا أطلــب‬\n      ‫احلكــم بفســخ العقــد لوقوعــه علــى غيــر األرض املتفــق عليهــا وإلــزام‬\n      ‫املدعــى عليــه بإعــادة املبلــغ الــذي ســلمته وقــدره مليــون وأربعمائــة ألــف‬\n      ‫ريــال واحلكــم علــى مــن أخــذ الداللــة وقدرهــا أربعــون ألــف ريــال وهــم‬\n      ‫‪...........‬و‪ ............‬مــع احلكــم بأربــاح املبلــغ الــذي اســتلمه مــن غيــر وجــه‬\n      ‫حــق وأســاله اجلــواب هــذه دعــواي وبعرضهــا علــى املدعــى عليــه قــال مــا‬\n      ‫ذكــره املدعــي أن موكلــي باعــه قطعــة األرض رقــم ‪ ...‬مــن مخطــط أم‬\n      ‫الكتاد مبكة صحيح وصحيح أن األرض املفرغة برقم ‪ ...‬من مخطط‬\n      ‫الهــدى وهــو خلــف مخطــط أم الكتــاد لكــن موكلــي قــد عــرض علــى‬\n      ‫املدعــي صــورة صــك األرض واطلــع عليهــا ووافــق علــى الشــراء وصحيــح‬\n      ‫أن ثمــن األرض مليــون وأربعمائــة ألــف ريــال كمــا أن املعتــاد أن كاتــب‬\n      ‫العــدل يســأله هــل وقفــت علــى األرض هــل اطلعــت عليهــا لــذا فهــو علــى‬\n      ‫علــم واطــاع بــاألرض املبيعــه وعليــه فــا يوافــق موكلــي علــى رد ثمــن‬\n\n\n‫‪211‬‬\n\f‫األرض املذكــورة هكــذا أجــاب كمــا حضــر ‪...............‬وقــرر بقولــه‬\n‫أننــي أنــا الــذي دللــت املدعــي علــى األرض رقــم ‪ 919‬بــأم الكتــاد ال‬\n‫مبخطــط الهــدى ووقفتــه عليهــا وقــد توافــق املخططــان يف املســاحة‬\n‫والشــوارع ورقــم القطعــة ثــم أننــي علمــت بعــد ذلــك أن الــذي أفــرغ لــه‬\n‫هــو أرض مخطــط الهــدى وقــد اســتلمت منــه أجــرة الداللــة عشــرين‬\n‫ألــف ريــال كمــا اســتلم ‪ .............‬مثلهــا وال مانــع لــدي مــن إعــادة الداللــة‬\n‫التــي اســتلمت هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه ‪..............‬‬\n‫قــال إننــي أملــك شــركة ‪ .............‬للســيارات وقــد تعامــل معنــا ‪.......‬‬\n‫واســتلم منــا قرضــا مــن خمســة أشــخاص ممــن يتعامــل مــع الشــركة‬\n‫ورهننــا أرضــا وســلمنا صكهــا وأفرغهــا لنــا علــى صفــة ضمــان للتمويــل‬\n‫والقــرض ثــم اتصــل بنــا بعــد ذلــك وطلــب منــا بيعهــا فعرضناهــا وطلبــت‬\n‫مبليــون وثالثمائــة ألــف ريــال ثــم عرضتهــا علــى ‪ ............‬أن يبحــث عــن‬\n‫مشــتر آخــر فأتــى بهــذا احلاضــر وطلبهــا مبليــون وأربعمائــة ألــف ريــال‬\n‫فبعانــا أيــاه ســلمنا مليونــا وســلم للمالــك األصلــي أربعمائــة ألــف ريــال‬\n‫كمــا ســلمني أنــا و ‪ ...............‬أربعــن ألــف ريــال تناصفناهــا بيننــا وال‬\n‫أدري عمــا يذكــره أن البيــع وقــع علــى أرض أم الكتــاد واإلفــراغ علــى‬\n‫أرض الهــدى بــل تعاملــي كان مــع الــدالل ‪...............‬والــذي أعلمــه أن‬\n‫املدعــي اطلــع علــى األرض وصكهــا وهــو مــن أهــل اخلبــرة بالعقــار‬\n‫والتعامــل فيــه لــذا فــا حــق لــه يف إعــادة األرض لكــن أن حكــم علــي‬\n‫بإعــادة مبلــغ الداللــة فــا مانــع لــدي هكــذا أجــاب وبعــرض ذلــك علــى‬\n‫املدعــي قــال إننــي لــم أطلــع علــى صــورة الصــك وليــس بهــا علــم ولــم يقــل‬\n‫لــي كاتــب العــدل هــل وقفــت علــى األرض أوال بــل قــال لــه الوكيــل‬\n‫ياشــيخ األرض بــأم الكتــاد األرض بــأم الكتــاد فقــال لــي كاتــب‬\n\n\n                                                                                           ‫‪212‬‬\n\f            ‫العــدل هــل هــو كمــا يقــول فقلــت نعــم بــأم الكتــاد هكــذا قــال‬\n      ‫ثــم ســالت املدعــى عليــه وكالــة هــل لديــه بينــه علــى مــا يذكــره أن‬\n      ‫املدعــي علــم ال حقــا أن األرض بالهــدى فقــال ليــس لــدي بينــه ســوى‬\n      ‫صــك العقــار فأبــرز املدعــي صــك العقــار فوجدتــه برقــم ‪1/229/371‬‬\n      ‫يف ‪1415/8/24‬ه ـ صــادرا مــن كاتــب عــدل مكــة بــأن مــن اجلــاري يف‬\n      ‫ملــك ‪ .............‬القطعــة رقــم ‪ 919‬الواقعــة باملخطــط رقــم ‪ 12/29/1‬يف‬\n      ‫الهــدى احملــدوده شــماال بالقطعــة رقــم ‪ 916‬وجنوبــا القطعــة رقــم ‪920‬‬\n      ‫وشــرقا القطعــة رقــم ‪ 918‬وغربــا شــارع ‪25‬م مســاحتها ‪75‬م ثــم همــش‬\n      ‫عليهــا بانتقالهــا إلــى ملــك ‪ ...........‬مبائــة ألــف ريــال ثــم أبــرز الصــك‬\n      ‫رقــم ‪ 720109000436‬يف ‪1433/11/27‬ه ـ الصــادر مــن كاتــب عــدل‬\n      ‫مكــة بــأن األرض املذكــورة بيعــت للمدعــي مبليــون وأربعمائــة ألــف‬\n      ‫ريــال ( ‪ ) 1400.000‬وبعرضــه علــى املدعــي قــال الصحيــح مــا ذكــرت‬\n      ‫أوال وليــس لــدي علــم بذلــك وأن صــك العقــار فهــو كمــا ذكــرت لــم‬\n      ‫اعلــم عنــه حتــى أفــرغ ومضــى شــهرا وأكثــر وعلمــت ذلــك بعــد أن أردت‬\n      ‫البنــاء ويــدل علــى ذلــك الشــيك العربــون الــذي ســلمته وســند القبــض ثــم‬\n      ‫أبــرز الشــيك رقــم ‪ 306‬يف ‪1433/11/10‬ه ـ واملســحوب مــن حســابي‬\n      ‫‪ ............‬علــى مصــرف ‪ ......‬فــرع أم القــرى عربــون قطعــة األرض برقــم‬\n      ‫‪ 919‬بــأم الكتــاد كمــا أبــرز كربــون ســند القبــض رقــم ‪ 244‬علــى‬\n      ‫مطبوعــات ‪ ..............‬أنــه اســتلم مائــة ألــف ريــال بالشــيك املذكــور‬\n      ‫بعاليــه عربــون أرض أم الكتــاد وبعرضــه علــى املدعــى عليــه قــال لــم‬\n      ‫يســتلم موكلــي الشــيك والســند مــن مكتــب ‪ ..............‬للداللــة وبعرضــه‬\n      ‫علــى احلاضــر ‪ .............‬فقــال إننــي الــذي اســتلمت الشــيك املذكــور‬\n      ‫وســلمت للمدعــي ســند بالقبــض وعرضــت الشــيك علــى ‪ .............‬ووافــق‬\n\n\n‫‪213‬‬\n\f‫عليــه هكــذا قــال ويف جلســة أخــرى حضــر الطرفــان وحضــر وكيــل‬\n‫املدعــى عليــه ‪..............‬وهــو‪ ...........‬وكيــا عــن‪ .................‬بالوكالــة‬\n‫رقــم ‪ 32787‬يف‪1432/11/17‬ه ـ الصــادرة مــن كتابــة عــدل مكــة‬\n‫الثانيــة وتخولــه املرافعــة واملدافعــة واإلقــرار واإلنــكار والصلــح والتنازل‬\n‫إلــخ وبعــد النظــر يف الدعــوى واإلجابــة ومــا قــرره املدعــي أنــه اشــترى‬\n‫القطعــة رقــم ‪ 919‬مبخطــط أم الكتــاد وأن األرض املفرغــة لــه بالرقــم‬\n‫نفســه مبخطــط الهــدى وتأسيســا علــى تصديــق املدعــى عليــه وكالــة‬\n‫علــى ذلــك ومــا قــرره احلاضــر ‪ ...............‬أن وقوفــه مــع املدعــي كان علــى‬\n‫أرض أم الكتــاد ال أرض الهــدى ونظــرا ملــا ورد يف شــيك العربــون وســند‬\n‫القبــض وفيــه أن األرض بــأم الكتــاد وتأسيســا علــى مــا تقــرر شــرعا‬\n‫أن البيــع إمنــا يقــع علــى مــا تراضــى عليــه الطرفــان مــن العــن والثمــن‬\n‫وغيــر ذلــك وألن املدعــي لــم يــرض بــاألرض املفرغــة لــه حســب دعــواه‬\n‫وألن املدعــى عليــه ال ميلــك أرض أم الكتــاد والتــي وقــع عليهــا البيــع بــن‬\n‫الطرفــن فبيعــه لهــا غيــر صحيــح وال معتبــر شــرعا فأمــا االفــراغ فأنــه‬\n‫توثيــق للبيــع وامللــك وال يعنــي تصحيــح العقــد أو افســاده وألن مــال املســلم‬\n‫ال يحــل إال بطيــب نفــس منــه ولــم يــرض املدعــي بتســليم مالــه عوضــا‬\n‫عــن أرض حــي الهــدى فأمــا مــا ذكــره املدعــى عليــه أن املدعــي رضــي‬\n‫بــاألرض حــن اإلفــراغ فقــد نفــاه املدعــي ولــم يقــم عليــه املدعــى عليــه‬\n‫بينــه فأمــا احتجــاج املدعــي باإلفــراغ نفســه علــى رضــى املدعــى عليــه‬\n‫فليــس بوجيــه ألن مــا ذكــره املدعــي مــن وقــوع اللبــس كمــا فصلــه‬\n‫يف إجابتــه عــن ذلــك ممــا هــو ســائغ وممــا يقــع عــاده لكــن ملــا يكــن‬\n‫للمدعــى عليــه بينــة علــى رضــى املدعــي بــاألرض املفرغــة بعــد اإلفــراغ‬\n‫فــإن لــه ميينــه علــى نفــي ذلــك وبعرضــه علــى املدعــى عليــه وكالــة قــال ال‬\n\n\n                                                                                         ‫‪214‬‬\n\f      ‫أرغــب يف ميــن املدعــي علــى نفــي مــا ذكــر هكــذا قــرر وأمــا احلاضــران‬\n      ‫املدعــى عليهمــا بالداللــة ‪..........‬و‪...........‬فقــد أقــرا باســتالمهما أجــرة‬\n      ‫الداللــة وملــا كانــت الداللــة بهــذه املثابــة غيــر صحيحــة ألنهمــا داله‬\n      ‫علــى غيــر األرض التــي ميلكهــا املدعــى عليــه وعليــه فــا يســتحقان تلــك‬\n                                      ‫األجــرة ويلزمهمــا شــرعا ردهــا إلــى املدعــي‬\n      ‫فأمــا مــا طلبــه املدعــي مــن احلكــم لــه باألربــاح عــن ثمــن األرض للمــدة‬\n      ‫التــي مــن حــن التســليم إلــى اآلن فهــو طلــب ال وجــه لــه ألن املدعــى عليــه‬\n      ‫اســتلم املــال علــى أنــه ضامــن لــه فهــو إن هلــك املــال ضامــن لهالكــه ولــه‬\n      ‫زيادتــه لــو زاد وقــد تقــرر شــرعا أن الغنــم بالغــرم فــإذا كان املدعــي لــو‬\n      ‫تلــف املــال أو ضــاع أو نحــو ذلــك لــم يضمنــه فــا يحــق لــه طلــب أرباحــه‬\n      ‫وأيضــا فــإن األمــر الواقــع بــن الطرفــن يظهــر منــه الغلــط و اخلطــأ وال‬\n      ‫يظهــر منــه اخلــداع واملكــر لــذا فــا يتوجــه ضمــان املدعــي ألربــاح ثمــن‬\n      ‫األرض لذلــك كلــه فقــد قــررت مــا يلــي‪ -1 :‬علــى املدعــي عليــه أن‬\n      ‫يعيــد إلــى املدعــي مليونــا وأربعمائــة ألــف ريــال ‪ -2‬علــى املدعــى عليهمــا‬\n      ‫‪............‬و‪ ...........‬أن يعيــد كل منهمــا إلــى املدعــي عشــرين ألــف ريــال‬\n      ‫‪ -3‬رددت دعــوى املدعــي باملطالبــة بأربــاح املبلــغ الــذي ســلمه ومبــا ســبق‬\n      ‫حكمــت وأفهمــت املدعــى عليــه وكالــة أن ملوكلــة ‪ ........‬اليمــن علــى‬\n      ‫املدعــي أنــه لــم يــرض بــأرض الهــدى وبعرضــه علــى املدعــى عليــه وكالــة‬\n      ‫لــم يقنــع بــه عــن موكليــه‪.............‬و‪ ...........‬وبعرضــه علــى احلاضــر‬\n      ‫‪ .............‬قنــع بــه وبعرضــه علــى املدعــي قنــع بــه فأفهمــت املدعــى عليــه‬\n      ‫وكالــة بتعليمــات االســتئناف ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/09‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/07/05‬ه ـ‬\n\n\n‫‪215‬‬\n\f‫افتتحــت اجللســة الســاعة ‪ 1.35‬وفيهــا فقــد عــادت املعاملــة مــن محكمة‬\n‫االســتئناف بخطابهــم رقــم ‪ 34176550‬يف ‪1434/6/18‬ه ـ ارفــق بهــا‬\n‫القــرار رقــم ‪ 34239132‬يف ‪1434/6/12‬ه ـ ونــص احلاجــة منــه وبدراســة‬\n‫الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة إعادتهــا‬\n‫لفضيلــة حاكمهــا حيــث لــم جنــد فضيلتــه افهــم املدعــي بــان عليــه‬\n‫إعــادة إفــراغ تلــك القطعــة املباعــة جلهــة املدعــى عليــه املالــك األول عنــد‬\n‫اســتالم ثمنهــا فعلــى فضيلتــه إكمــال مــا يلــزم اه ـ ‪ .‬عليــه فقــد حضــر‬\n‫املدعــي وقــرر بقولــه بعــد افهامــه بذلــك اننــي مســتعد بإعــادة إفــراغ‬\n‫األرض إلــى املدعــى عليــه ‪ .................‬حــال تســليمي املبلــغ احملكــوم‬\n‫بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                         ‫وســلم ‪ .‬حــرر يف ‪ 1434/07/05‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بخطابهــم رقــم ‪ 34176550‬يف ‪1434/8/1‬ه ـ ارفــق بهــا القــرار رقــم‬\n‫‪ 34277873‬يف ‪1434/7/24‬ه ـ املــدون علــى ظهــر الصــك املتضمــن‬\n‫املوافقــة علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                 ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/09‬ه ـ‬\n‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n‫نحـن رئيس وأعضاء الدائـرة احلقوقيـة السادسة يف محكمة االستئناف‬\n‫مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هذا احلكم الصادر من فضيلة‬\n‫الشــيخ‪ ................./‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‪،‬‬\n‫واملســجل بع ــدد ‪ 34186372‬وتاريــخ ‪1434/4/13‬هـ‪،‬املتضمــن دعــوى‬\n‫منصــور ‪ ...........‬ضــد ‪ ............‬احملكــوم في ــه مبــا دون باطــن الصــك‪،‬‬\n‫وبدراس ــة احلكــم وص ــورة ضبط ــه و الئحتــه االعتراضيــة تق ــررت‬\n\n\n                                                                                       ‫‪216‬‬\n\f      ‫املوافق ــة عل ــى احلكــم بعــد اإلجــراء األخيــر جواب ـ ًا علــى قــرار الدائــرة‬\n      ‫رقــم ‪ 34239132‬وتاريــخ ‪1434/6/12‬هــ‪،‬واهلل املوفــق‪ .‬وصل ــى اهلل‬\n                                      ‫عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪217‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":209,"source_page_end":217,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"569389900f2b05e015eaede4dccc6851a400e086800b6e0fb663c2a94e58418a","normalized_text_hash":"af18538b6263b38ccd38f541cbd6f06637a42e404a4dd1a094513fca93a7454a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p209-34186372"},{"id":"f2a8db77-fb1e-5086-b390-399d855abf21","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -تعويض -إيجار منتهي بالتمليك -دعوى تعويض عن ضرر -مطالبة بالتعويض عن فسخ عقد إيجار سيارة منتهي بالتمليك -استعانة برأي اخلبراء -رهن املبيع للبائع ال مينع من بقاءه بيد املشتري -منافع املغصوب يضمنها الغاصب -مقاصة قضائية .","document_number":"3438433","case_number":"3281602","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/16","year":"1434","subject":"بيع -تعويض -إيجار منتهي بالتمليك -دعوى تعويض عن ضرر -مطالبة بالتعويض عن فسخ عقد إيجار سيارة منتهي بالتمليك -استعانة برأي اخلبراء -رهن املبيع للبائع ال مينع من بقاءه بيد املشتري -منافع املغصوب يضمنها الغاصب -مقاصة قضائية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/02/16 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3438433 :‬‬\n                    ‫َر ْق ُم الدعوى‪3281602 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34364150‬تاريخه‪1434/11/20 :‬هـ‬\n\n\n‫بيــع ‪ -‬تعويــض ‪ -‬إيجــار منتهــي بالتمليــك ‪ -‬دعــوى تعويــض عــن ضــرر‬\n‫‪ -‬مطالبــة بالتعويــض عــن فســخ عقــد إيجــار ســيارة منتهــي بالتمليــك‬\n‫‪ -‬اســتعانة بــرأي اخلبــراء ‪ -‬رهــن املبيــع للبائــع ال مينــع مــن بقــاءه بيــد‬\n     ‫املشــتري ‪ -‬منافــع املغصــوب يضمنهــا الغاصــب ‪ -‬مقاصــة قضائيــة ‪.‬‬\n\n\n\n‫‪ -1‬البيــع مــع رهــن املبيــع للبائــع ال مينــع مــن بقاء العني يف يد املشــتري‬\n                                                        ‫وعــدم قبض الرهن ‪.‬‬\n‫‪ -2‬منافــع املغصــوب مضمونــة والغاصــب يضمــن أجــرة املغصــوب إلــى‬\n        ‫حــن رده أو تلفــه‪ .‬شــرح املنتهــى ‪403/2‬و ‪ 421‬والكشــاف ‪187/4‬‬\n‫‪ -3‬قــول الشــيخ محمــد بــن إبراهيــم يف الفتــاوى(‪ ....« :)342-341/11‬ال‬\n  ‫يتحمــل مــا ينفقــه املصــاب املتســبب علــى املجنــي عليــه مــدة مرضــه» ‪.‬‬\n\n\n\n\n‫ادعى املدعي بأنه تعاقد مع الشركة املدعى عليها على شراء السيارة‬\n‫املوصوفــة يف دعــواه بالتأجيــر املنتهــي بالتمليــك وبالقيمــة املذكــورة‬\n‫مقســطة علــى عــدد األشــهر املذكــور ثــم وقــع عليهــا حــادث مــروري‬\n‫نتــج عنــه تلفهــا فســلمها للشــركة إلجــراء مــا يوجبــه العقــد إال أنهــا‬\n‫باعتهــا دون علمــه مبــا يقــل عــن ثلــث قيمتهــا الفعليــة ســوقي ًا فأضــرت بــه‬\n\n                                                                                       ‫‪218‬‬\n\f      ‫بذلــك‪ ،‬لــذا طلــب إلزامهــا بتعويضــه بســيارة مماثلــة وحتميلهــا أضــرار‬\n      ‫بيــع الســيارة دون قيمتهــا وأجــرة الســيارة التــي حتملهــا بســبب الشــركة‬\n      ‫طيلــة مــدة القضيــة وتســببها يف عجــزه عــن عــاج ابنــه حتــى تــويف‪ -‬أقــر‬\n      ‫وكيــل املدعــى عليهــا مبــا جــاء يف الدعــوى ودفــع بــأن موكلتــه التزمــت‬\n      ‫ببنــود العقــد املبــرم بينهمــا‪ ،‬كمــا أن املدعــي فــرط يف تعريــض العــن‬\n      ‫للمخاطــر بــأن خالــف شــروط التأمــن فســلم الســيارة ملــن عمــره أقــل مــن‬\n      ‫(‪ )20‬ســنه برغبتــه واختيــاره واملفــرط أولــى باخلســارة ولذلــك فموكلتــه‬\n      ‫غيــر مســتعدة بتعويضــه مبــا طلــب ‪ -‬قــررت احملكمــة تكليــف جلنــة مــن‬\n      ‫اخلبــراء للتحقيــق يف القضيــة مــن جميــع جوانبهــا وإصــدار تقريــر يبــن‬\n      ‫فيــه حتديــد مســئولية الشــركة املدعــى عليهــا مــن عدمــه بهــا فتوصلــت‬\n      ‫إلــى حتميــل الشــركة املدعــى عليهــا مســئولية إصــاح ســيارة املدعــي أو‬\n      ‫تعويضــه عــن قيمتهــا وأن الشــركة املدعــى عليهــا ال تتحمــل مــا يتعلــق‬\n      ‫مبــا ذكــره مــن تســببهم يف وفــاة ابنــه وأن باقــي طلباتــه راجعــة للنظــر‬\n      ‫القضائــي ‪ -‬حقيقــة العقــد بــن الطرفــن بيــع برهــن والثمــن مؤجــل‬\n      ‫يســدد علــى أقســاط لــذا فيجــري عليــه أحكامــه ‪ -‬الشــركة تصرفــت‬\n      ‫يف الســيارة وباعتهــا ممــا تســبب يف تفويــت التعويــض املســتحق للمدعــي‬\n      ‫فتكــون ضامنــة للســيارة ألنهــا يف حكــم املغصــوب ‪ -‬مطالبــة املدعــي‬\n      ‫بأضــرار بيــع الســيارة وأجــرة الســيارة التــي حتملهــا بســبب الشــركة‬\n      ‫طيلــة مــدة القضيــة وتســببهم يف عجــزه عــن عــاج ابنــه حتــى تــويف غيــر‬\n      ‫متوجهــة ألن حقــه يف رفــع الضــرر وقــد مت رفعــه بإعطائــه مــا يســتحق ‪-‬‬\n      ‫قضــت احملكمــة بإلــزام الشــركة املدعــى عليهــا بتســليم املدعــي مبلغـ ًا‬\n      ‫يعــادل قيمــة الســيارة بعــد احلــادث وتســليمه قيمــة التعويــض املتوقــع عــن‬\n      ‫التلفيــات بســبب احلــادث بعــد أن خصمــت األقســاط املتبقيــة للشــركة‬\n\n\n‫‪219‬‬\n\f‫وصــرف النظــر عــن باقــي مــا يطالــب بــه املدعــي وأفهمــت املدعــي بــأن لــه‬\n‫مطالبــة الشــركة بأجــرة الســيارة مــدة بقائهــا لديهــا‪ -‬عــارض املدعــي‬\n‫ووكيــل املدعــى عليهــا علــى احلكــم ‪ -‬قــررت محكمــة االســتئناف‬\n                                                        ‫املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بحائــل برقــم ‪ 3281602‬وتاريــخ ‪ 1432/03/17‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 32250587‬وتاريــخ ‪ 1432/3/16‬ه ـ ففــي يــوم األحــد‬\n‫املوافق‪ 1432/07/10‬هـ افتتحت اجللســة الســاعة ‪ 09 : 09‬وفيها حضر‬\n‫‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬وادعــى علــى‬\n‫احلاضــر معــه ‪ .....‬ســجل مدنــي رقــم ‪ .....‬الوكيــل عــن ‪ .....‬و‪ .....‬بصفتهــم‬\n‫مــدراء شــركة ‪ .....‬للســيارات احملــدودة مبوجــب الوكالــة الصــادرة مــن‬\n‫ا يف دعــواه‬ ‫كتابــة عــدل عرقــه برقــم ‪ 329721‬يف ‪1432/1/19‬ه ـ قائـ ً‬\n‫عليــه اشــتريت مــن الشــركة ســيارة اوبتــرا صنــع ‪2007‬م رقــم اصــل‬\n‫‪ 2647‬بالعقــد رقــم ‪1589‬عــام ‪1430‬ه ـ بالتأجيــر املنتهــي بالتمليــك‬\n‫قيمتــه (‪ )55150‬ريــال مقســطة علــى (‪ )48‬قســطا تبــدا مــن ‪2008/7/1‬‬\n‫وتنتهــي يف ‪2012/6/1‬م وكنــت منتظم ـ ًا بأقســاطهم حتــى حصــل‬\n‫عليهــا حــادث مــروري نتــج عنــه تلــف الســيارة ســلمتها لهــم إلجــراء مــا‬\n‫يوجبــه العقــد بيننــا محقـ ًا للطرفــن فباعوهــا دون علمــي بأقــل مــدة علــى‬\n‫التشــليح مبــا يقــل عــن ثلــث قيمتهــا الفعليــة ســوقي ًا وزوروا علــي ورقــة‬\n‫بالعلــم والقبــول منــي والتعهــد بدفــع باقــي متأخــرات العقــد فاضــروا بــي‬\n\n                                                                                     ‫‪220‬‬\n\f      ‫ضــررا محدقــا متعمــدا منهــم لكــون الشــركة املدعــى عليهــا أضــرت‬\n      ‫بــي ضــررا محدقــا ولــم تعمــل الواجــب النظامــي بشــروط العقــد بيننــا‬\n      ‫وانتهــزت فرصــة الكارثــة علــى الســيارة فباعوهــا بثمــن بخــس زيــادة يف‬\n      ‫ضــرري دون علمــي وزورا علــي املوافقــة والعلــم اطلــب نظــر دعــواي‬\n      ‫بالوجــه الشــرعي بإلزامهــم مبنطــوق العقــد بتعويضــي بســيارة مماثلــه‬\n      ‫وحتميلهــم أضــراري ببيــع الســيارة دون قيمتهــا واجــرة الســيارات التــي‬\n      ‫حتملتهــا بســببهم طيلــة القضيــة وتســببهم يف عجــزي عــن عــاج ابنــي‬\n      ‫حتــى تــويف وبرفقــه مذكــرة لتحريــر الدعــوى مفصلــة وبســؤال املدعــى‬\n      ‫عليــه وكالــة أجــاب قائــا اطلــب مهلــة للجــواب للرجــوع إلــى الشــركة‬\n      ‫وافادتكــم باجللســة القادمــة ورفعــت اجللســة ويف يــوم األحــد افتتحــت‬\n      ‫اجللســة وفيهــا حضــر املدعــي كمــا حضــر ‪ .....‬ســعودي الســجل املدنــي‬\n      ‫رقــم ‪ .....‬الوكيــل عــن شــركة ‪ .....‬للســيارات احملــدودة مبوجــب‬\n      ‫الوكالــة الصــادرة مــن كتابــة عــدل عرقــه برقــم ‪ 329721‬يف‬\n      ‫‪1432/1/19‬ه ـ وقــرر املدعــى عليــه وكالــة ان الشــركة تطلــب مهلــة‬\n      ‫إضافيــة للجــواب حيــث طلبــت أوراق املعاملــة اخلاصــة بالقضيــة لالطــاع‬\n      ‫عليهــا ونطلــب مهلــة إضافيــة فاهمتــه بــان املوعــد القــادم آخــر موعــد‬\n      ‫وعلــى الشــركة أن تعــد اجلــواب وإال عديتهــا ناكله عــن اجلواب واجرينا‬\n      ‫الــازم الشــرعي والنظامــي ففهــم املدعــى عليــه وكالــة ذلــك ثــم رفعــت‬\n      ‫اجللســة ويف يــوم األحــد املوافــق ‪1432/9/21‬ه ـ افتتحــت اجللســة يف‬\n      ‫الســاعة ‪ 11 : 30‬وحضــر الطرفــان وقــدم املدعــى عليــه وكالــه رد ًا‬\n      ‫مكتوب ـ ًا ملخصــه ان املدعــى عليــه قــد اســتأجر ثــاث ســيارات بعقــد‬\n      ‫واحــد وليــس ســيارة واحــده ومنهــا الســيارة محــل الدعــوى كمــا قــرر‬\n      ‫املدعــى عليــه وكالــه ان الشــركة ملتزمــة مبــا جــاء يف العقــد وبنــوده‬\n\n\n‫‪221‬‬\n\f‫وان الشــركة غيــر مســئوله عــن مــا جــاء يف دعــوى املدعــي ويطلــب‬\n‫املدعــى عليــه وكالــه احلكــم بــرد الدعــوى وبعــرض ذلــك علــى املدعــي‬\n‫قــال أطلــب مهلــة للجــواب ورفعــت اجللســة ويف يــوم االثنــن املوافــق‬\n‫‪1432/10/27‬هـ افتتحت اجللســة يف الســاعة العاشــرة وحضر الطرفان‬\n‫وقــدم املدعــي رد ًا مخزن ـ ًا يف ذاكــرة ونصهــا ( بســم اهلل الرحمــن‬\n‫الرحيــم التاريــخ احلمــد هلل وحــده وبعــد مذكــرة الــرد يف الدعــوى املقامة‬\n‫مــن ‪ ...‬ضــد شــركة ‪ ...‬للســيارات ردا علــى مذكــرة الوكيــل الشــرعي‬\n‫لشــركة ‪ ...‬والتــي جــاءت مذكرتــه بدفــاع تهــرب بــه عــن احلقيقــة‬\n‫الواضحــة ولــم ينــف ادعاءاتــي باألدلــة القاطعــة مــع أنــي اثبــت خطــأ‬\n‫الشــركة وتهربهــم عــن تعويضــي مبســتندات لــم يتطــرق إليهــا الشــك أو‬\n‫الطعــن فيهــا واســتكماال لدعــواي ضــد الشــركة أرد علــى مذكــرة‬\n‫وكيــل الشــركة مبــا يلــي‪ -:‬أوال‪ :‬ذكــر وكيل الشــركة أني اشــتريت‬\n‫ثــاث ســيارات مــن نفــس النــوع وال اعلــم مــا عالقــة ذلــك بدعــواي حيــث‬\n‫أنــي لــم أنكــر هــذه الســيارات ولكن دعــواي على احد هذه الســيارات‪.‬‬\n‫ثانيــا‪ :‬ذكــر وكيــل الشــركة أنــي ذكــرت يف مذكــرة ادعائــي بــان‬\n‫الشــركة لــم تلتــزم بالعقــد وهــذه حقيقــة ال يســتطيع نفيهــا أمــام وجــود‬\n‫البينــة القاطعــة لــدي حالــة إنــكاره وإال أيــن ســيارتي أو تعويضهــا أو‬\n‫تعويضــي عــن مضرتــي املترتبــة علــى إتالفهــا وإضاعــة وقتــي يف قضايــا‬\n‫ومحاكــم علــى الرغــم مــن أنــي لــم اخــل بــأي بنــد مــن بنــود عقدهــم معــي‬\n‫فيمــا يخــص هــاك الســيارة فلمــاذا لــم احصــل علــى حقــي حتــى اآلن مــن‬\n‫تعويــض وإال مــا معنــى أن شــركة التأمــن لــم تقبــل الســيارة مــع العلــم‬\n‫انــه مذكــور بعقــد التأجيــر يف (البنــد عاشــرا) أن الســيارة املؤجــرة‬\n‫مؤمــن عليهــا مــن قبــل املؤجــر مبوجــب بوليصــة تأمــن طــوال مــدة هــذا‬\n\n\n                                                                                     ‫‪222‬‬\n\f      ‫العقــد ضــد (احلــوادث املروريــة) واقتضــاء ملــا قضــت بــه املــادة (‪ )100‬مــن‬\n      ‫نظــام املرافعــات الشــرعية اســأل وكيــل الشــركة إذا كان دفاعــه‬\n      ‫بعــدم شــمول الســيارة للتامــن بســبب صغــر ســن قائــد الســيارة فلمــاذا‬\n      ‫لــم ابلــغ بهــذا الشــرط الذيــن يعلمونــه باعتبارهــم هــم جهــة التعاقــد مــع‬\n      ‫شــركة التامــن وأنــا ال اعلمــه عندمــا طلبــت عمــل هــذا التفويــض‬\n      ‫للقائــد وهــم يعلمــون أن شــروط التأمــن ال تنطبــق عليــه وبالتالــي أكــون‬\n      ‫علــى علــم بهــذا الشــرط إمــا أن يصــدر تفويــض لــه تأمــن شــامل وهــو‬\n      ‫مخالــف لشــروط التأمــن ثــم أحتمــل أنــا هــذه املخالفــة فهــذا مخالــف‬\n      ‫للشــرع والنظــام ثالثــا‪ :‬أقــر وكيــل الشــركة يف مذكرتــه مبــا نصــه‪:‬‬\n      ‫(بأنــي أحضــرت جميــع األوراق املطلوبــة للشــركة لرفعهــا إلــى شــركة‬\n      ‫التامــن مــن تقريــر باحلــادث وتســعيرات مصدقــة مــن إدارة مــرور حائــل‬\n      ‫وهــذا يــدل علــى أن املذكــور متابــع ومتواصــل مــع الشــركة عــاوة انــه‬\n      ‫يقــوم ســداد األجــرة الشــهرية املســتحقة عليــه نهايــة كل شــهر للســيارة‬\n      ‫األخــرى) وهــذا إقــرار مــن ممثــل املدعــى عليهــا يشــكر عليــه فانــا لــم‬\n      ‫اخــل بــأي التــزام وهــذا دوري لكــي أحصــل علــى حقــي مــن شــركة‬\n      ‫التأمــن كمــا هــو متبــع يف نظــام شــركات التأمــن أما أن تباع الســيارة‬\n      ‫بــدون علمــي وبأقــل مــن ثلــث ثمنهــا فهــذا فيــه إضاعــة حلقــي فبعــد‬\n      ‫أســبوعني قمــت مبراجعــة الشــركة فذكــرت أن التأمــن ال يشــمل‬\n      ‫الســيارة وأنــا عقــدي مــع الشــركة املدعــى عليهــا أن الســيارة يشــملها‬\n      ‫التامــن أمــا أن التامــن رفــض الســيارة فليــس لــي عالقــة بهــذا فحقــي‬\n      ‫معــروف كمــا ذكــرت ســابقا بنظــام شــركات التأمــن عنــد حــدوث‬\n      ‫حادثــة للســيارة أن تتكفــل شــركة التأمــن بإصالحهــا أو إعطــاء‬\n      ‫صاحــب الســيارة ســيارة بديلــة وهــذا هــو املعــروف يف عقــود التأمــن‬\n\n\n‫‪223‬‬\n\f‫كمــا نصــت القاعــدة (املعــروف عرفــا كاملشــروط شــرطا) مــع وجــود‬\n‫الشــرط فيــه أمــا املبــرر التــي ذكرتــه الشــركة املدعــى عليهــا مــن‬\n‫رفــض شــركة التأمــن تعويــض الســيارة هــو صغــر ســن قائــد الســيارة‬\n‫فهــذا املبــرر ليــس لــه أســاس مــن الصحــة حيــث أن القائــد لديــه رخصــة‬\n‫قيــادة وتفويــض مــن الشــركة املدعــى عليهــا‪ .‬فهــم مــن فوضــوه بقيــادة‬\n‫الســيارة حينمــا كانــوا مســتفيدين وعنــد املطالبــة جعلــوا ذلــك محــا‬\n‫لطعنهــم بــه وادعائهــم باملخالفــة وهــم مصــدر املخالفــة إن اعتبــرت‬\n‫مخالفــة ومــع افتــراض ذلــك فبــأي قانــون تعطــي الشــركة احلــق لنفســها‬\n‫يف بيــع الســيارة دون علــم مســتأجرها‪ .‬حيــث أن الشــركة أخــذت منــي‬\n‫مبلــغ (‪ )500‬ريــال لدخــول الســيارة الورشــة إلصالحهــا وحتــى علمــت‬\n‫بالبيــع لــم اعلــم أيــن الســيارة وملــاذا اخــذوا منــي هــذا املبلــغ إذا كان يف‬\n‫نيتهــم بيعهــا‪ .‬رابعــا‪ :‬أمــا بالنســبة لورقــة التعهــد واإلقــرار الــذي يدفــع بــه‬\n‫وكيــل الشــركة بــأن مثــل هــذه الورقــة ترســل للعميــل ويؤخــذ توقيــع‬\n‫مــن اســتلمها هــذا الدفــاع كلــه لــدد خصومــة ومغالطــة وتناقضــات وال‬\n‫يعقــل مــا ذكــر بخصوصهــا فهــو دفــع غيــر مــاق للدعــوى واضــح منــه‬\n‫التهــرب مــن احلــق وبالرغــم مــن الصفــة التجاريــة للورقــة وأهميتها كيف‬\n‫يؤخــذ إقــرار أو تعهــد مــن شــخص علــى إجــراء مهــم مثــل ذلــك دون‬\n‫صاحــب الصفــة فيهــا فهــذا خطــأ فــادح مــن الشــركة املدعــى عليهــا‬\n‫وهــذا الدفــع منهــم بعــد أن طعنــت بتزويــر توقيعــي عليهــا لــدى اجلهــة‬\n‫املختصــة فأطالــب بإحضــار املُوقــع علــى الورقــة واملوظــف الــذي تولــى‬\n‫اإلجــراء ‪.‬واألمــر الثانــي ذكــر وكيــل الشــركة يف مذكرتــه بالبنــد‬\n‫ثالثــا أنــي كنــت أســدد األجــرة الســنوية ثــم يأتــي يف نفس هــذه املذكرة‬\n‫بالفقــرة الرابعــة منهــا ويذكــر أن التعهــد يرســل إلــى العميــل يف حالــة‬\n\n\n                                                                                           ‫‪224‬‬\n\f      ‫تأخــره عنــد الســداد فلمــاذا هــذا التناقــض الــذي يوضــح التهــرب مــن‬\n      ‫احلــق والدفــع بأســباب واهيــة ال ترقــى إلــى ســبب إلضاعــة حقــي‪ .‬وأنبــه‬\n      ‫أحضــرت بعــد أن كســبت القضيــة يف‬         ‫فضيلــة القاضــي أن هــذه الورقــة ُ‬\n      ‫فــرع وزارة التجــارة بحائــل يف اجللســة األخيــرة احضرهــا الوكيــل‬\n      ‫الشــرعي الســابق لــدى الشــركة املدعــى عليهــا (‪ ).....‬وعنــد ســؤالي لــه‬\n      ‫مــن أيــن أحضرتهــا قــال مــن امللــف فقلــت لــه ملــاذا كل أوراق القضيــة‬\n      ‫يوجــد عليهــا صــورة فتحــات اخلرامــة أمــا ورقــة التعهــد واإلقــرار ال يوجــد‬\n      ‫عليهــا آثــار اخلرامــة فقــال يجــوز آلــه التصويــر اخفــت آثــار الفتحــات وهــي‬\n      ‫إجابــة مراوغــة غيــر منطقيــة !!! وقــد أراد وكيــل الشــركة يف دفاعــه‬\n      ‫أن يخفــي احلقيقــة بدفــاع ُيبعــد عــن موضــوع القضيــة فذكــر أن هــذا‬\n      ‫التعهــد واإلقــرار ال يقيــد الشــركة حتــى تقــوم بتزويــره وهــذا صحيــح‬\n      ‫وال يحتــاج إلــى ذكــر ألن هــذه الورقــة تقيدنــي وتضيــع حقــي أنــا وإال لــم‬\n      ‫تقــم الشــركة بتزويرهــا ألن لــو هــذا التوقيــع صحيــح ملــا اســتطعت‬\n      ‫مطالبــة الشــركة بــأي شــيء مــن حقوقــي التــي أطالــب بهــا حاليــا يف‬\n      ‫دعــواي‪ .‬كمــا ذكــر وكيــل الشــركة املدعــى عليهــا بــان تاريــخ ورقــة‬\n      ‫التعهــد بتاريــخ ‪1430/4/16‬ه ـ وتاريــخ احلــادث بتاريــخ ‪1430/4/22‬ه ـ‬\n      ‫وهــذا دليــل قاطــع علــى أن املوضــوع مدبــر فلمــاذا يؤخــذ تعهــدي قبــل‬\n      ‫احلــادث بأربعــة أيــام فقــط فهــل هــم علــى علــم باحلــادث انــه ســيحدث‬\n      ‫وبالتالــي قامــوا بأخــذ تعهــدي قبلــه بأربعــة أيــام كتأمني حلقهــم وإضاعة‬\n      ‫حقــي ولــو متعنتــم فضيلتكــم هــذا اإلقــرار لوجــدمت فيــه احلقيقــة وكيــف‬\n      ‫دبــروا وخططــوا إلضاعــة حقــي‪ .‬هــذا باإلضافــة انــه مــزور‪ .‬وأضيــف‬\n      ‫لفضيلتكــم دليــل آخــر علــى نيتهــم وتهربهــم مــن إعطائــي حقــي أن‬\n      ‫فواتيــر التشــليح كلهــا مــزورة ومكتوبــة بخــط واحــد وغيــر كاملــة‬\n\n\n‫‪225‬‬\n\f‫البيانــات باإلضافــة أن احــد أصحــاب ورش التشــليح ذكــر بأنــه ال علــم‬\n‫لــه بالفاتــورة وغيــر صحيحــة‪ .‬هــل يعقــل أن يتــم خــال أربعــة وعشــرين‬\n‫ســاعة ‪-1‬إجــراء خطــاب موجــه مــن مديــر التحصيــل إلــى مديــر الفــرع‬\n‫باالستفســار وانتظــار التوجيــه بخصــوص ســيارة لــم يشــملها التأمــن‪-2.‬‬\n‫عمــل تســعيرة مــن ثــاث ورش تشــليح‪ -3 .‬بيــع الســيارة عــن طريــق‬\n‫الشــركة ‪ .‬هــل هــذه هــي إجــراءات الشــركة يف مثــل هــذه املواقــف أم‬\n‫هــي إجــراءات إلضاعــة حــق املواطنــن بــدون وجــه حــق‪ .‬أمــا فيمــا يتعلــق‬\n‫بالتفويــض فقــد ذكــر وكيــل الشــركة املدعــى عليهــا بــان إعطائــي‬\n‫الســيارة لشــخص آخــر بأنــه تفريــط وتعــدي وكأنــه جتاهــل بــان إدارة‬\n‫املــرور منحتــه رخصــة قيــادة وكذلــك جتاهــل أيضـ ًا بــأن التفويــض منــح‬\n‫مــن قبــل الشــركة وليــس مــن قبلــي للســماح لــه بقيــادة الســيارة وموضــح‬\n‫بالســيارة أن عليهــا تامــن شــامل‪ .‬فلمــاذا لــم تتأكــد الشــركة بــان قائــد‬\n‫الســيارة لــم تشــمله شــروط التامــن وبالتالــي عــدم إعطائــه التفويــض او‬\n‫تنبيــه صاحــب الســيارة بــان الشــخص املفــوض لــه ال يشــمله التامــن‬\n‫وهــذا مــن واجــب عملهــا ‪ .‬اســتخلص مــن هــذا كلــه بــان الشــركة لــم‬\n‫تبالــي ألنهــا ضامنــة حلقهــا حقـ ًا او باطـاً‪ .‬والتفويــض يعمــل منــه كثيــر‬\n‫لغيــر صاحــب العقــد (املســتأجر) يجعلــوه مــن الباطــن‪ .‬خامسـاً‪ :‬مــا دامت‬\n‫التســعيرات املعتمــدة هــي التســعيرات الصــادرة مــن املعــارض كمــا‬\n‫تدعــي الشــركة فلمــاذا تقــوم بتزويــر فواتيــر التشــليح علمــا بــأن‬\n‫التســعيرات اخلاصــة باملعــارض هــي خاصــة بشــركات التأمــن حلســاب‬\n‫قيمــة الســيارة بعــد احلــادث مــن قبــل شــركات التأمــن وهــذا املتبــع يف‬\n‫نظــام املــرور أمــا عنــد بيــع الســيارة التــي ال يشــملها التأمــن فيتــم‬\n‫تســعيرها مــن قبــل ورش التشــليح علمـ ًا بــان قيمــة الســيارة تكــون أعلــى‬\n\n\n                                                                                   ‫‪226‬‬\n\f      ‫مــن قيــم املعــارض ألن التشــليح يســتفيد مــن كل قطعــة بالســيارة أمــا‬\n      ‫املعــرض فيقيــم الســيارة ككل‪ .‬سادســا‪ :‬أمــا بالنســبة للدعــوى اخلاصــة‬\n      ‫بابنــي فانــا ال أتكلــم مــن فــراغ والتقاريــر واملواعيــد املتداخلــة بــن‬\n      ‫مواعيــد اجلهــات املختصــة اخلاصــة بالقضيــة ومواعيــد مراجعــات ابنــي‬\n      ‫باملستشــفيات تثبــت ذلــك ومطالبــة الشــركة باملبالــغ املاليــة التــي ال حــق‬\n      ‫لهــم فيهــا أثــرت علــي نفســيا وماديــا ولــم اســتطع أن أتفــرغ البنــي ومتابعة‬\n      ‫حالتــه الصحيــة حتــى جــاء قضــاء اهلل وقــدره وتوفــى ابنــي بســبب جتاهــل‬\n      ‫الشــركة لــي ومبطالبتــي‪ .‬وقــد انفــردوا بالســبب يف ضــرري ووفــاة ابنــي‬\n      ‫بســبب مباشــر افتعلــوه بهــدف االنتفــاع غيــر املشــروع متجرديــن مــن أي‬\n      ‫وازع‪ .‬خالصــة الــرد‪ :‬اســتخلص لفضيلتكــم مــن هــذا الــرد ان الشــركة‬\n                                               ‫هي املسئولة عن ضياع حقي لسببني‪:‬‬\n      ‫األول‪ -:‬لكــون الشــركة تعمــدت التفويــض لســائق ال يشــمله التامــن‬\n      ‫بــدون علمــي بــان ســنه ال ينطبــق عليهــا نظــام رخصــة القيــادة وال يشــمله‬\n      ‫التامــن وهــم اطلعــوا علــى وثائقــه برخصــة قيــادة مؤقتــة وعمــره اقــل مــن‬\n      ‫املشــروط بنظــام التامــن واخفــوا عنــي ذلــك‪ .‬ثانيــا‪ -:‬الشــركة زورت‬\n      ‫توقيعــي علــى ورقــة تعهــد تديننــي وحتملنــي مســؤولية خســارة وخطــأ لــم‬\n      ‫ارتكبــه ‪ .‬الطلــب‪ :‬اطلــب صــرف النظــر عــن دفــاع ممثــل اجلهــة املدعــى‬\n      ‫عليهــا واحلكــم لــي بدعــواي كمــا فصلتــه بحقــل الطلــب مــن صحيفــة‬\n      ‫الدعــوى ‪ .‬املقــدم ع‪.).....‬أ‪.‬ه ـ وبعــرض ذلــك علــى املدعــى عليــه وكالــة‬\n      ‫قــال اطلــب مهلــة للــرد ثــم رفعــت اجللســة ويف يــوم االربعــاء‬\n      ‫املوافق‪1432/1/28‬ه ـ افتتحــت اجللســة الســاعة (‪ )9:51‬وفيهــا حضــر‬\n      ‫الطرفــان وقــدم املدعــى عليــه وكالــة الئحــة رده ونصهــا‪ -1‬ذكــر‬\n      ‫املدعــى انــه ال يعلــم بعالقــة الســيارة محــل الدعــوي بالســيارات الثــاث‬\n\n\n‫‪227‬‬\n\f‫املؤجــرة عليــه يف الدعــوى املقدمــة منــه بتاريــخ ‪1432/6/6‬ه ـ حيــث‬\n‫أشــار املدعــي يف البنــد ثانيــا أن هــاك الســيارة قــد تســبب لــه بخســائر‬\n‫ماديــة جــراء اســتجارة ســيارة خــال مــدة مطالبتــه للشــركة وكذلــك‬\n‫عجــزه عــن الســفر إلــى األردن لعــاج ابنــه لعــدم وجــود ســيارة بديلــة ‪ ،‬إذ ًا‬\n‫أيــن الســيارة الثالثــة املتبقيــة لديــه ‪ ،‬وملــاذا لــم يســتخدمها ملــا ذكــر‬\n‫أعــاه جتنبــا ملــا ذكــر مــن األســباب ‪ ،‬مبــا أن عقــد التأجيــر عقــد لثالث‬\n‫ســيارات ‪ -2 .‬ذكــر املدعــي أن الشــركة لــم تلتــزم ببنــود العقــد وإال‬\n‫أيــن ســيارته أو تعويضهــا كمــا ذكــر ‪ ،‬نذكــر املدعــى انــه مســتأجر‬\n‫ســيارات مملوكــة للشــركة وليســت ملــكا لــه ‪ ،‬ذكــر أن الســيارة‬\n‫مؤمــن عليهــا بنــاء علــى مــا جــاء بالبنــد العاشــر ضــد احلــوادث املروريــة‬\n‫هــذا صحيــح حيــث أن جميــع الســيارات التابعــة للشــركة مؤمــن عليهــا‬\n‫حســب تعليمــات التامــن وشــروطها املوضحــة بالعقــد وأفــاد انــه لــم يبلــغ‬\n‫عنهــا بينمــا هــو موقــع علــى العقــد مــن ضمنهــا شــروط التامــن والبنــد‬\n‫احلــادي عشــر( بنــود ال يشــملها التامــن)‪ ،‬ومبــا أن املذكــور خالــف‬\n‫شــروط التامــن بالعقــد بتســليم الســيارة ملــن هــو اقــل مــن (‪ )20‬ســنه‬\n‫برغبتــه واختيــاره فهــذا يــدل علــى أنــه عــرض العــن للمخاطــر ومفــرط‬\n‫واملفــرط أولــى باخلســارة حســب كالم أهــل العلــم ومنهــم الشــيخ صالــح‬\n‫الفــوزان يف كتــاب امللخــص الفقهــي بــاب اإلجــارة ‪،‬علمــا أن العميــل‬\n‫لديــه الدرايــة الكاملــة بعقــود التأجيــر حيــث أنــه كفيــل ملكتــب‬\n‫مباشــر لتأجيــر الســيارات عــاوة أنــه تقــدم ألكثــر مــن مــرة بطلــب منــح‬\n‫أشــخاص تفاويــض بقيــادة ســيارة داخليــا وخارجيــا كمــا هــو مرفــق‪،‬‬\n‫وحتــى لــو أن شــركة التامــن جتــاوزت هــذا الســبب لنظــرت إلــى الســبب‬\n‫األخــر وهــو نســبة اخلطــأ (‪ )%100‬علــى الســائق فهــذا يعــد إهمــال متعمــد‬\n\n\n                                                                                       ‫‪228‬‬\n\f      ‫وإضــرار مبمتلــكات الغيــر املؤمتــن عليهــا ‪ .‬أمــا مــا ذكــر بشــان اخــذ‬\n      ‫الشــركة (‪ )500‬ريــال لدخــول الســيارة فهــذه رســوم لعمــل التقديــرات‬\n      ‫الالزمــة كمــا هــو موضــح نســخته بالتقريــر الــذي قدمــه املدعــي وهــو‬\n      ‫علــى علــم بذلــك حيــث اســتحصلت منــه مثــل هــذه الرســوم للســيارة‬\n      ‫األخــرى التــي حصــل عليهــا احلــادث قبــل هــذه الســيارة محــل الدعــوي‬\n      ‫‪ -3‬بالنســبة لورقــة التعهــد املؤرخــة بتاريــخ ‪1430/4/16‬ه ـ ومــا ذكــر‬\n      ‫املدعــي بشــأنها ‪ ،‬نرغــب أن نوضــح لفضيلتكــم وكمــا ذكرنــا ســابقا‬\n      ‫بــان العميــل مســتأجر (‪ )3‬بعقــد واحــد حصــل حــادث علــى إحداهــا‬\n      ‫بتاريــخ ‪1430/4/10‬ه ـ وبلغــت الشــركة مبوافقــة التأمــن علــى قبولهــا‬\n      ‫بتاريــخ ‪1430/6/12‬ه ـ ‪،‬وحصــل حــادث أخــر علــى ســيارة اخــرى محــل‬\n      ‫الدعــوي بتاريــخ ‪1430/4/22‬ه ـ ورفضــت مــن شــركة التأمــن بتاريــخ‬\n      ‫‪1430/6/22‬ه ـ ‪ ،‬وجــاء بنــص الورقــة (مســتأجر ثــاث ســيارات بعقــد‬\n      ‫رقــم (‪ )1589‬وانــه متأخــر قســطني وان يلتــزم بســداد (‪ )5400‬وإال‬\n      ‫ســحب الســيارة وبيعهــا وشــكايتي بــأي مبالــغ ) ‪ ،‬لــذا يجــب توضيــح‬\n      ‫التالــي ‪ :‬تاريــخ التعهــد متداخــل بــن تاريــخ احلادثــن ‪ ،‬ونــص التعهــد‬\n      ‫يشــمل كل الســيارات بالعقــد وان املبلــغ املطلــوب هــو قيمــة أجرة ســابقة‬\n      ‫مســتحقة علــى العميــل بواقــع أجــرة شــهرين لــكل ســيارة مــن الســيارات‬\n      ‫الثــاث قبــل احلــوادث وليــس كمــا ذكــر بــان الشــركة علــى علــم‬\n      ‫بالغيــب ‪ ،‬ولــم يحــدد التعهــد ســيارة بعينهــا وان عبــارة ســحب الســيارة‬\n      ‫مقصــود التنبيــه بســحب ســيارة أو كل الســيارات املؤجــرة ‪ ،‬اذ ًا ملــاذا‬\n      ‫العميــل حــدد الســيارة محــل الدعــوي ولــم يشــير إلــى الســيارة التــي‬\n      ‫حصــل عليهــا حــادث قبلهــا أو التــي بحوزتــه اآلن‪ -4 .‬مــا ذكــر املدعــي‬\n      ‫عــن تزويــر التســعيرات اخلاصــة بالتشــاليح ‪ ،‬نفيدكــم أن العميــل ليــس‬\n\n\n‫‪229‬‬\n\f‫لــه شــان باإلجــراءات الداخليــة التــي تخــص الشــركة وان الــذي بــن‬\n‫الشــركة والعميــل هــي التســعيرات الرســمية املوجهــة إلدارة املــرور‬\n‫املعتمــدة واملصدقــة مــن قبلهــم والتــي يتــم التعامــل مبوجبهــا بحكــم‬\n‫صفتهــا القانونيــة ‪ -5 .‬أمــا ذكــر بالفقــرة سادســا مــن عــدم تفرغــه البنــه‬\n‫ومتابعــة حالتــه الصحيــة ووفــاة ابنه بســبب جتاهل الشــركة لــه وملطالبه‬\n‫فهــذا موضــوع يخصــه شــخصيا وليــس للشــركة عالقــة مبــا ذكــر مــن‬\n‫أســباب أو كانــت ســبب فيــه ألنــه هــو مــن قــام بتقــدمي ورفــع الدعــاوى‬\n‫واملراجعــات وليــس الشــركة‪ -6 .‬أمــا مــا ذكــر أن الشــركة تعمــدت‬\n‫التفويــض لســائق ال يشــمله التأمــن ‪ ،‬ذكرنــا ســابقا أن التفويــض عمــل‬\n‫مــن اجــل إكمــال األوراق إلدخــال احلــادث لشــركة التامــن مســاعدة‬\n‫للعميــل ‪ ،‬والعميــل اســتغل مثــل هــذه الورقــة حتــى يديــن الشــركة‪،‬‬\n‫ونتســأل مــن ســلم الشــخص الســيارة الــذي عمــل احلــادث بهــا وقــام بتبليــغ‬\n‫الشــركة باحلــادث ووقــع بذلــك ومــا صلــت القرابــة بينهــم‪ ،‬وهــل‬\n‫الشــركة تســليم ســيارة لشــخص غيــر املســتأجر‪ ،‬ال كنــه بعــد رفــض‬\n‫الســيارة مــن شــركة التامــن يحــاول حتميــل الشــركة خطئــه‪ ،‬وأمــا مــا‬\n‫ذكــر بشــان تزويــر توقيعــه وان الورقــة تدينــه وحتملــه مســؤولية اخلســارة‬\n‫واخلطــاء ‪ ،‬ســبق وأوضحنــا بــان مثــل ورقــة التعهــد هــذه ترســل ألي عميــل‬\n‫لــدى الشــركة وهــى إنــذار وتنبيــه بــان لديــه أجــرة شــهران مســتحقة لــم‬\n‫تدفــع للســيارات الثــاث (‪3(*)1800 =2*900‬ســيارات )= ‪ 5400‬ريــال‬\n‫وإال ســوف تســحب الســيارة أو الســيارات ‪.‬بنــاء ملــا تقــدم توضيحــه‬\n‫لفضيلتكــم نأمــل البــت يف يــراه فضيلتكــم ورد دعــوى املدعــي عليــه‬\n‫وإلزامــه بحقــوق الشــركة ‪، ،‬وفقكــم اهلل وســدد خطاكــم والســام‬\n‫عليكــم وبعــرض ذلــك علــى املدعــي قــال أطلــب مهلــة للــرد واجبتــه‬\n\n\n                                                                                    ‫‪230‬‬\n\f      ‫لطلبــه ورفعــت اجللســة ويف يــوم االثنــن املوافــق ‪1433/1/10‬ه ـ افتتحــت‬\n      ‫اجللســة يف الســاعة ‪ 11 : 00‬وحضــر الطرفــان وبســؤال املدعــي عــن رده‬\n      ‫قــال لقــد أطلعــت علــى مذكــرة الدفــع املقدمــة مــن الشــركة املدعــى‬\n      ‫عليهــا ولــم اجــد فيهــا مــا يوجــب الــرد وقــرر الطرفــان أنهمــا ليــس لديهمــا‬\n      ‫مــا يرغبــان إضافتــه ثــم لتأمــل مــا مت ضبطــه ودراســته رفعــت اجللســة ويف‬\n      ‫يــوم الثالثــاء املوافــق ‪1433/4/13‬ه ـ افتتحــت اجللســة يف الســاعة ‪: 35‬‬\n      ‫‪ 10‬وفيهــا حضــر الطرفــان وطلبــت مــن املدعــى عليــه وكالــة أصــل‬\n      ‫العقــد بــن الطرفــن بهــذه القضيــة فاســتعد بإحضــاره وطلــب مهلــة‬\n      ‫فأجبتــه لطلبــه ويف يــوم الســبت املوافــق ‪1433/4/17‬ه ـ افتتحت اجللســة‬\n      ‫يف الســاعة ‪ 9 : 30‬وحضــر الطرفــان وقــدم املدعــى عليــه وكالــة العقــد‬\n      ‫بــن الطرفــن ونصــه ( بســم اهلل الرحمــن الرحيــم عقــد تأجيــر ســيارة‬\n      ‫احلمــد هلل وحــده وصلــى اهلل وســلم علــى رســول اهلل وعلــى آلــه وأصحابــه‬\n      ‫ومــن وااله وبعــد بعــون اهلل وتوفيقــه مت ابــرام هــذا العقــد بتاريــخ‬\n      ‫‪1429/7/11‬ه ـ املوافــق ‪2008/7/14‬م مبدينــة حائــل بــن كل مــن ‪-1‬‬\n      ‫املؤجــر شــركة ‪ .....‬للســيارات وهــي شــركه ســعودية ذات مســئولية‬\n      ‫محــدودة مبوجــب الســجل التجــاري رقــم ‪ ....‬ومركزهــا الرئيســي‬\n      ‫بالريــاض وعنوانهــا ص ب ‪ ....‬الريــاض ‪ ....‬وميثلهــا يف التوقيــع علــى هــذا‬\n      ‫العقــد ع‪ .....‬طــرف أول ‪ -2‬املســتأجر ‪ ....‬اجلنســية ســعودي املهنــة معلــم‬\n      ‫العنــوان حائــل ‪ ....‬رمــز البريــدي هاتــف املنزل ‪ .....‬هاتــف العمل‪ ...‬واجلوال‬\n      ‫‪ ...‬طــرف ثــان متهيــد حيــث أن الطــرف األول املؤجــر يتملــك الســيارة‬\n      ‫احملــدد نوعهــا ومواصفاتهــا أدنــاه نــوع الســيارة ‪ ....‬عــدد ‪ 3‬املوديــل‬\n      ‫‪2007‬م رقــم الهيــكل ‪ ....‬ذهبــي ‪ ....7‬ابيــض ‪ ....‬عنابــي ‪ ....7‬وحيــث أن‬\n      ‫الطــرف الثانــي «املســتأجر» قــد أبــدى رغبتــه يف اســتئجار الســيارة املبني‬\n\n\n‫‪231‬‬\n\f‫مواصفاتهــا أعالهــا والوفــاء بكامــل الشــروط وااللتزامــات الــواردة‬\n‫بهــذا العقــد ‪ .‬لــذا فقــد اتفــق الطرفــان وهمــا بكامــل أهليتهمــا املعتبــرة‬\n‫ـرعا علــى أن يقــوم املؤجــر بتأجيــر الســيارة احملــدد نوعهــا وكامــل‬      ‫شـ ً‬\n‫وفقــا للشــروط التاليــة‪ :‬أوالً‪ :‬يعتبــر‬\n                                        ‫مواصفاتهــا أعــاه علــى املســتأجر ً‬\n‫ثانيــا ‪ :‬مــدة‬\n           ‫ـزءا ال يتجــزأ مــن هــذا العقــد‪ً .‬‬  ‫التمهيــد املذكــور أعــاه جـ ً‬\n‫العقــد‪ :‬اتفــق الطرفــان علــى أن مــدة هــذا العقــد هــي ‪ 48‬شــهرا تبــدأ مــن‬\n‫‪2008/7/1‬م وينتهــي يف ‪2012/6/1‬م ثال ًثــا ‪ :‬يقــر املســتأجر بأنــه قــد‬\n‫عايــن الســيارة محــل هــذا العقــد معاينــة نافيــة للجهالــة واســتلمها مــن‬\n‫املؤجــر بحالــة جيــدة وقبلهــا بحالتهــا الراهنــة خاليــة مــن أي عيب وصاحلة‬\n‫للغــرض املســتأجرة مــن أجلــه ‪ .‬كمــا يقــر أنــه قــد مت تزويدهــا بــكل‬\n‫اإلضافــات املتفــق عليهــا وأنهــا قــد أصبحــت حتــت مســئوليته اخلاصــة من‬\n‫رابعــا ‪ :‬ملكيــة الســيارة‪ :‬يقــر املســتأجر مبعرفتــه أن‬ ‫تاريــخ هــذا العقــد ً‬\n‫العقــد هــو عقــد إيجــار ملــدة طويلــة وأن الســيارة ملــك للمؤجــر طــوال مــدة‬\n‫هــذا العقــد وليــس للمســتأجر حــق يف ملكيتهــا وال يحــق لــه بيعهــا أو‬\n‫هبتهــا إلــى أي طــرف ثالــث أو التصــرف فيهــا بــأي تصــرف ناقــل‬\n‫للملكيــة ‪ .‬كمــا أنهــا ال تعتبــر مــن أمالكــه التــي تــؤول إلــى الورثــة ‪.‬‬\n‫ولضمان ســداد األجرة يوافق املســتأجر على أن تبقى اســتمارة الســيارة‬\n‫لــدى املؤجــر وباســمه وكذلــك يكــون لــدى املؤجــر نســخة مــن املفاتيــح‬\n‫االحتياطيــة للســيارة لســحبها يف أي وقــت عنــد مخالفــة املســتأجر‬\n‫خامســا ‪ :‬قيمــة العقــد ‪5-1‬‬‫ً‬       ‫اللتزاماتــه اجلوهريــة احملــددة بهــذا العقــد‬\n‫يكــون مبلــغ إيجــار الســيارة طيلــة املــدة اجلــاري عليهــا التأجيــر مبلــغ‬\n‫‪ 165450‬ريــال ســعودي موزعــة علــى إيجــارات شــهرية وفــق مــا هــو مبــن‬\n‫يف هــذا العقــد‪ .‬وحيــث أن العقــد هــو عقــد تأجيــر ســيارة طويــل املــدى‬\n\n\n                                                                                       ‫‪232‬‬\n\f      ‫وقــد روعيــت فيــه تخفيــض قيمة األجرة عن األســعار الســائدة يف الســوق‬\n      ‫لطــول مدتــه ونظـ ًـرا ألن الســيارة يختلــف ســعرها مــن وقــت آلخــر حســب‬\n      ‫خصوصــا بعــد اســتعمالها مــن قبــل املســتأجر بحيــث يكــون‬     ‫ً‬          ‫حالتهــا‬\n      ‫مرتفعــا يف البدايــة وينخفــض بعــد اســتعمالها ‪ .‬وحيــث أن‬        ‫ً‬       ‫ســعرها‬\n      ‫املســتأجر ال يرغــب يف أن يدفــع قيمــة إيجــار مختلفــة مــن شــهر إلــى آخــر‬\n      ‫فقــد طلــب مــن املؤجــر توزيــع القيمــة اإليجاريــة الفعليــة علــى أقســاط‬\n      ‫شــهرية متســاوية بحيــث تتناســب مــع دخلــه الشــهري ‪ .‬لذا اتفــق الطرفان‬\n      ‫علــى ســداد القيمــة الفعليــة علــى النحــو التالــي‪ :‬توقيــع املســتأجر وتوقيــع‬\n      ‫الكفيــل الغــارم ‪ -‬دفعــة مقدمــة مــن مجموع القيمــة اإليجارية بالكامل‬\n      ‫مقدارهــا ‪ 12450‬ريــال يقــوم املســتأجر بدفعهــا عنــد التوقيــع علــى هــذا‬\n      ‫ـهرا تدفــع يف‬\n                   ‫العقــد‪ - .‬دفعــة إيجــار شــهري تبلــغ‪ 2700‬ريــال ملــدة ‪ 48‬شـ ً‬\n      ‫ـارا مــن ‪2008/7/1‬م ‪ -‬دفعــة‬     ‫اليــوم الثالثــن يف بدايــة كل شــهر اعتبـ ً‬\n      ‫أخيــرة مــن مــدة عقــد اإليجــار مقدارهــا ‪ 23400‬ريــال تســدد بتاريــخ‬\n      ‫اســتحقاق القســط األخيــر مــن هــذا العقــد‪ .‬وقــد قــام املســتأجر بالتوقيــع‬\n      ‫علــى ســندات ألمــر واجبــة الدفــع بعــدد الدفعــات الشــهرية املذكــورة‬\n      ‫والدفعــة األخيــرة‪ 2-5.‬يقــر املســتأجر ويوافــق علــى أن دفعــات القيمــة‬\n      ‫اإليجاريــة املبينــة أعــاه ال متثــل األجــرة الفعليــة يف حــاالت املــدد القصيرة‬\n      ‫حيــث روعــي فيهــا التخفيــض كمــا ذكــر أعــاه لطــول مــدة العقــد ‪.‬‬\n      ‫لذلــك فإنــه مــن املتفــق عليــه بــن الطرفــن أنــه إذا رغــب املســتأجر يف‬\n      ‫إنهــاء هــذا العقــد قبــل انتهــاء مدتــه وإعــادة الســيارة إلــى املؤجــر‪ ،‬أو يف‬\n      ‫حالــة رغبتــه يف اســتبدالها قبــل نهايــة العقــد أو عنــد نهايتــه‪ ،‬أو يف حالــة‬\n      ‫تعــرض الســيارة حلــادث ينتــج عنــه الهــاك أو التلــف الكلــي للســيارة‬\n      ‫(وفــق تقاريــر شــركة التأمــن) أو يف حالــة تعــرض الســيارة للســرقة‬\n\n\n‫‪233‬‬\n\f‫(بــدون إهمــال مــن املســتأجر ) فــإن املســتأجر يوافــق علــى احتســاب‬\n‫القيمــة اإليجاريــة الفعليــة الشــهرية وفــق اجلــدول االســتهالكي املرفــق‬\n‫ـزءا ال يتجــزأ منــه )‪.‬‬‫بهــذا العقــد (ملحــق رقــم) «‪ »1‬والــذي يعتبــر جـ ً‬\n‫سادســا ‪ :‬املســافات الزائــدة‪ :‬مــن املتفــق عليــه بــن الطرفــن أن املســافة‬‫ً‬\n‫املجانيــة التــي تقطعهــا الســيارة خــال مــدة هذا العقــد ‪ 2.500‬كيلومتر‬\n‫شــهرياً‪ .‬فــإذا رغــب املســتأجر يف إنهــاء العقــد وإعــادة الســيارة إلــى‬\n‫املؤجــر فــإن املؤجــر ســيقوم مبحاســبته عــن املســافة الزائــدة بواقــع ‪50‬‬\n‫ـابعا ‪ :‬الوعــد بالبيــع‪ :‬إذا التــزم‬\n                                   ‫هللــة عــن كل كيلــو متــر إضــايف‪ .‬سـ ً‬\n‫املســتأجر بســداد كامــل دفعــات األجــرة الشــهرية املتفــق عليهــا يف هــذا‬\n‫العقــد ورغــب يف متلــك الســيارة فــإن املؤجــر يلتــزم ببيــع الســيارة محــل‬\n‫هــذا العقــد للمســتأجر ونقــل ملكيتهــا لــه مقابــل األجــرة التــي دفعــت‬\n‫والدفعــة األخيــرة مــن العقــد ‪ .‬ويف هــذه احلالــة يتــم إنهــاء عقــد اإليجــار‬\n‫هــذا وحتريــر عقــد بيــع بــن الطرفــن ‪ .‬وبعــد إمتــام عقــد البيــع ودفــع‬\n‫القيمــة يقــوم املؤجــر بنقــل ملكيــة الســيارة للمشــتري علــى أن يدفــع‬\n‫املشــتري تكاليــف نقــل ملكيــة الســيارة باســمه لــدى اجلهــات املختصــة‬\n‫ثام ًنــا‪ :‬التزامــات املســتأجر‪ :‬يلتــزم املســتأجر طيلــة مــدة هــذا العقــد مبــا‬\n‫يلــي‪ -1 :‬أن يقــوم بدفــع مبلــغ اإليجــار الشــهري املتفــق عليهــا يف هــذا‬\n‫العقــد دون اعتبــار للحالــة الفنيــة للســيارة أو فتــرة تواجدهــا يف مراكــز‬\n‫اخلدمــة إن وجــدت هنــاك‪ ،‬فــإذا تأخــر املســتأجر عــن دفــع األجــرة ملــدة‬\n‫ـهرا وعشــرة‬‫شــهرين متتاليــن بالنســبة للعقــود التــي أطــول مــن ‪ 12‬شـ ً‬\n‫أيــام للعقــود األقــل مــن ذلــك‪ ،‬فــإن املســتأجر يعتبــر وكأنــه قــد أنهــى‬\n‫العقــد مــن قبلــه و يحــق للمؤجــر اســتنا ًدا إلــى ذلــك اإلنهــاء التعميــم علــى‬\n‫الســيارة لــدى اجلهــات املختصــة الســترجاعها دون أدنــى مســؤولية علــى‬\n\n\n                                                                                         ‫‪234‬‬\n\f      ‫املؤجــر عــن أي نتائــج مترتبــة علــى ذلــك التعميــم ‪.‬وعندهــا يحــق للمؤجــر‬\n      ‫مطالبــة املســتأجر بدفــع مبلــغ األجــرة املتأخــرة عــن الفتــرة الســابقة‬\n      ‫لتاريــخ ســحب الســيارة‪ ،‬وكذلــك دفــع نســبة اســتهالك الســيارة حيــث‬\n      ‫يتــم حســاب األجــرة عندهــا وفــق اجل ــدول االســتهالكي املرفــق بهــذا‬\n      ‫العقد مل ــحق رقم «‪ ،»1‬باإلض ــافة إلى مص ــاريف الس ــحب (‪ 250‬ريال‪/‬‬\n      ‫ســيارة) واي مصاريــف اخــري إن وجــدت‪ .‬ويتعهــد املســتأجر بــان ال‬\n      ‫يحتفــظ املســتأجر بــاي نقــود او اغــراض ثمينــة وأن ال يطالــب املؤجــر‬\n      ‫بــاي التزامــات كانــت داخــل الســيارة‪ -2 .‬أن يقــوم باســتخدام الســيارة‬\n      ‫بنفســه للغــرض املؤجــرة مــن أجلــه وهــو االســتخدام الشــخصي فقــط‪،‬‬\n      ‫وأن ال يســمح ملــن ال يحمــل رخصــة قيــادة ســارية املفعــول بقيادتهــا‪ .‬كمــا‬\n      ‫يلتــزم بــأن ال يعــرض الســيارة ألي خطــر بشــكل متعمــد أو يســتخدمها‬\n      ‫للتجــارب أو التدريــب أو الســباق أو األجــرة أو نقــل البضائــع‪ .‬ويجــوز لــه‬\n      ‫تفويــض غيــره بقيــادة الســيارة املســتأجرة بشــرط اســتخدام منــوذج‬\n      ‫التفويــض املعــد مــن شــركة ‪ .....‬للســيارات واملوافــق عليــه مــن قبــل‬\n      ‫جنائيــا‬\n         ‫ً‬      ‫الشــركة‪ -3 .‬أن يكــون مســؤوال عــن الســيارة محــل اإليجــار‬\n      ‫ومروريـ ًا وأن ال يقــوم بإعــادة تأجيرهــا أو إعارتهــا ألي طــرف ثالــث دون‬\n      ‫خطيــا علــى ذلــك ‪ .‬كمــا يتحمــل ا ملســتأجر كافــة‬     ‫ً‬      ‫موافقــة املؤجــر‬\n      ‫األضــرار والغرامــات املســجلة علــى الســيارة عــن أيــة مخالفــات مروريــة‬\n      ‫ألنظمــة املــرور املعمــول بهــا يف اململكــة أو يف الــدول التــي يســمح لــه مــن‬\n      ‫املؤجــر بقيــادة الســيارة فيهــا‪ -4 .‬أن يقــوم مبتابعــة الصيانــة الدوريــة‬\n      ‫للســيارة وفــق برنامــج الصيانــة لــدى الشــركة واملوضــح بكتيــب‬\n      ‫اإلرشــادات مــن الشــركة الصانعــة املرفــق بالســيارة ويقــوم علــى حســابه‬\n      ‫اخلــاص بتحمــل جميــع مصاريــف الســيارة مــن بنزيــن وتغييــر الزيــوت‬\n\n\n‫‪235‬‬\n\f‫والتشــحيم ومالحظــة مســتوى املــاء وهــواء اإلطــارات بانتظــام ‪ .‬ويف حالــة‬\n‫قيامــة بالصيانــة خــارج املــدن التــي بهــا فــروع للمؤجــر يلتــزم بــأن تكــون‬\n‫الصيانــة لــدى إحــدى و كالء جنــرال موتــورز املتواجديــن يف تلــك‬\n‫املنطقــة دون حتديــد مــا إذا كانــت اإلصالحــات مشــمولة بالضمــان‬\n‫الفنــي ‪ .‬ويف حالــة القيــام بإصالحــات غيــر مشــمولة بالضمــان الفنــي‬\n‫فــإن ذلــك يكــون علــى حســاب املســتأجر‪ -5 .‬أن يشــعر املؤجــر بــأي‬\n‫تغييــر يطــرأ علــى عنــوان ســكنه أو عملــه املــدون يف هــذا العقــد‪)6 .‬‬\n‫يلتــزم املســتأجر مبراجعــة املؤجــر قبــل نهايــة مدة‪/‬صالحيــة االســتمارة‬\n‫لفحــص الســيارة يف الفحــص الــدوري وجتديــد االســتمارة‪ .‬وتعتبــر‬\n‫نفقــات الفحــص والتجديــد علــى حســاب املســتأجر باعتبــاره هــو‬\n‫املســتخدم للســيارة واملســتفيد مــن تلــك اخلدمــات ‪ .‬وإذا تأخــر املســتأجر‬\n‫يف هــذا االلتــزام فإنــه يتحمــل كذلــك أيــة غرامــات تأخيــر قــد تفــرض‬\n‫مــن اجلهــات املختصــة‪ .‬توقيــع املســتأجر توقيــع الكفيــل الغــارم أن يعيــد‬\n‫الســيارة إلــى املؤجــر يف نهايــة العقــد ســليمة وبحالــة جيــدة بعــد إصــاح‬\n‫كل مــا يطــرأ عليهــا مــن أضــرار وحــوادث إذا كان ذلــك نتيجــة إهمــال‬\n‫أو تعمــد أو تقصيــر ‪ .‬فــإذا انتهــت مــدة هــذا العقــد ولــم يرغــب املســتأجر‬\n‫يف اســتعمال خيــار الشــراء ونقــل ملكيــة الســيارة باســمه‪ ،‬ولــم يعــد‬\n‫الســيارة فإنــه يلتــزم بتعويــض املؤجــر عــن كل يــوم يتأخــر فيــه بعــد‬\n‫تاريــخ انتهــاء العقــد مببلــغ ‪ 100‬ريــال عــن كل يــوم تأخيــر‪ .‬ويجــب أن‬\n‫تكــون الســيارة عنــد اإلعــادة شــاملة علــى كل التغييــرات واإلضافــات‬\n‫امللحقــة بالســيارة املذكــورة بهــذا العقــد إن وجــدت‪ ،‬وإذا ظهــرت أيــة‬\n‫طبقــا لســعرها لــدى املؤجــر ‪.‬‬\n                              ‫نواقــص فعلــى املســتأجر ســداد قيمتهــا ً‬\n‫وتعتبــر أيــة إضافــات زائــدة وضعهــا املســتأجر يف الســيارة مــن حــق‬\n\n\n                                                                                      ‫‪236‬‬\n\f      ‫املؤجــر دون عــوض‪ .‬تاسـ ًـعا ‪ :‬موقــع اإليجــار ‪ 9-1 :‬يحــق للمســتأجر‬\n      ‫مبوجــب هــذا العقــد اســتخدام الســيارة داخــل حــدود اململكــة العربيــة‬\n      ‫تفويضــا محــد ًدا لذلــك‪ .‬علــى أن يكــون‬\n                                             ‫ً‬         ‫الســعودية ويقــوم املؤجــر مبنحــة‬\n      ‫للمؤجــر حــق تقديــر مــدة التفويــض وظــروف منحــه‪ -2 .‬إذا رغــب‬\n      ‫املســتأجر يف قيــادة الســيارة خــارج حــدود اململكــة لزيــارة دول اخلليــج‬\n      ‫العربــي أو بعــض الــدول األخــرى فــإن عليــه تقــدمي طلــب بذلــك قبــل وقــت‬\n      ‫كاف للمؤجــر‪ .‬وللمؤجــر احلــق بحجــب هــذا التفويــض ألي ســبب وفــق‬\n      ‫تقديــره اخلــاص‪ .‬وإذا مت منــح التفويــض للمســتأجر فــإن عليــه احتــرام‬\n      ‫أنظمــة املــرور يف البلــدان التــي يســافر إليــه‪ .‬ويتحمــل املســتأجر كل مــا‬\n      ‫يلحــق الســيارة مــن رســوم أخــرى أو غرامــات يف الدولــة التــي يســافر‬\n      ‫إليهــا ووفــق أنظمتــه ا‪ .‬ويف حالــة حــدوث أي حــادث يدخــل ضمــن التأمني‬\n      ‫فــإن أي تعويــض يســتحق للســيارة مــن جــراء ذلــك احلــادث فهــو للمؤجــر‬\n      ‫عاشـ ًـرا ‪ :‬التأمــن علــى الســيارة‪ :‬إن الســيارة املؤجــرة مؤمــن عليهــا مــن‬\n      ‫قبــل املؤجــر مبوجــب بوليصــة تأمــن طوال مدة هذا العقــد ضد(احلوادث‬\n      ‫املروريــة واحلريــق والســرقة (الغيــر متعمــدة مــن املســتأجر ومــن غيــر‬\n      ‫إهمــال منــه أو مخالفــة لألنظمــة)‪ .‬وعلــى املســتأجر تطبيــق تعليمــات‬\n      ‫التأمــن التاليــة يف حالــة حــدوث حــادث للســيارة‪( )1 :‬إلحضــار تقريــر‬\n      ‫مفصــل عــن احلــادث وورقة‪/‬تقريــر املوافقــة علــى اإلصــاح مــن املــرور‬\n      ‫خــال فتــرة ال تتجــاوز خمســة أيــام مــن تاريــخ وقــوع احلــادث ‪ .‬وإذا جتــاوز‬\n      ‫املســتأجر هــذه املــدة فإنــه يتحمــل لوحــده مصاريــف اإلصــاح بالكامــل‬\n      ‫دون الرجــوع علــى املؤجــر‪)2 .‬عــدم التنــازل للغيــر يف تقريــر املــرور عــن أي‬\n      ‫حقــوق مقــررة للســيارة محــل هــذا العقــد ‪ .‬ويف حالــة تنــازل املســتأجر عــن‬\n      ‫أي حــق للســيارة فإنــه يتحمــل لوحــده كامــل املســؤولية الناجتــة عــن‬\n\n\n‫‪237‬‬\n\f‫احلــادث وعلــى نفقتــه اخلاصــة‪)3 .‬تزويــد الشــركة بصــورة ســارية املفعــول‬\n‫مــن رخصــة القيــادة‪)4 .‬يتعهــد املســتأجر بعــدم إصــاح مــن تلقــاء نفســه‬\n‫بــل يعهــد بهــا إلــى املؤجــر‪)5 .‬ســداد مبلــغ ألف وخمســمائة ريــال (‪)1.500‬‬\n‫متوســط رســم أي حــادث يتــم إصالحــه بواســطة املؤجــر‪ .‬باإلضافــة إلــى‬\n‫االلتــزام بــأي شــروط أخــرى تتطلبهــا شــركة التأمــن‪ .‬حــادي عشــر ‪:‬‬\n‫بنــود ال يشــملها التأمــن اتفــق الطرفــان علــى أن املســتأجر يتحمــل جميــع‬\n‫املصاريــف والتلفيــات التــي ال يشــملها التأمــن ‪ .‬ويعتبــر تقريــر املــرور هــو‬\n‫الوثيقــة الوحيــدة التــي حتــدد مســؤوليات احلــادث‪ .‬واألمــور التــي ال‬\n‫يشــملها التأمــن هــي‪ )1 :‬ال يشــمل التأمــن املقــدم مــن املؤجــر التأمــن‬\n‫الشــامل علــى ســائق وركاب الســيارة املؤجــرة ويتحمــل املســتأجر أيــة‬\n‫مســؤولية تتعلــق بهــذا املوضــوع‪ .‬وتكــون حــدود مســؤولية التأمــن يف‬\n‫هــذه الناحيــة فقــط مصاريــف طبيــة بواقــع خمســة آالف (‪ )5.000‬ريــال‬\n‫للشــخص الواحــد املصــاب يف الســيارة بحــد أقصــى عشــرون ألــف‬\n‫(‪ )20.000‬ريــال للحــادث الواحــد‪ .‬باإلضافــة إلــى مصاريــف ســحب‬\n‫الســيارة بحــد أقصــى مبلــغ خمســمائة ريــال (‪ )500‬مــن داخــل اململكــة‬\n‫ومبلــغ ألــف وخمســمائة (‪ )1.500‬ريــال مــن خــارج اململكــة‪)2 .‬كذلــك‬\n‫ال يشــمل التأمــن ســرقة أي قطعــة أو جتهيــزات إضافيــة للســيارة مثــل‬\n‫الراديــو‪ ،‬املســجل‪ ،‬البطاريــة‪ ،‬أجهــزة النقــال‪ ،‬الفيديــو ‪ ،. . .‬أو ســرقة‬\n‫أو فقــدان النقــود واألمتعــة الشــخصية للمســتأجر‪)3 .‬كذلــك ال يشــمل‬\n‫التأمــن مصاريــف ســحب الســيارة املصدومــة إلــى مركــز اخلدمــة‪)4 .‬‬\n‫أيض ـ ًا ال يشــمل التأمــن األضــرار الناجتــة عــن العوامــل التــي ال ميكــن‬\n‫الســيطرة عليهــا مثــل الــزالزل واألمطــار واحلــروب وأعمــال الشــغب‬\n‫والكــوارث الطبيعيــة‪ )5 .‬ال يشــمل التأمــن احلــوادث واألضــرار‬\n\n\n                                                                                      ‫‪238‬‬\n\f      ‫والتلفيــات الناجتــة عــن القيــادة يف حالــة الســكر واإلهمــال املتعمــد‪)6 .‬‬\n      ‫ال يشــمل التأمــن الرخصــة غيــر الســارية املفعــول أو التراخيــص املروريــة‬\n      ‫بالنســبة ملــن هــم أقــل مــن ‪ 18‬ســنة ‪ ،‬وكذلــك ملــن هــم أكثــر مــن خمســة‬\n      ‫وســتون ســنة‪ .‬ال يشــمل التأمــن ســرقة الســيارة بواســطة املســتأجر مــن‬\n      ‫شــركة تأجيــر الســيارات‪ .‬توقيــع املســتأجر توقيــع الكفيــل ثانــي‬\n      ‫عشــر‪ :‬الصيانــة‪ :‬مــن املتفــق عليــه أن الضمــان الفنــي للســيارات املؤجــرة‬\n      ‫مــن الشــركة تكــون علــى النحــو التالــي‪( :‬علمــا بــان الضمــان ال يشــمل‬\n      ‫أي إضافــات أو تعديــات يقــوم بهــا املســتأجر علــى املركبــة محــل‬\n      ‫اإليجــار)‪ .‬ســيارات جــي ام ســي وشــيفرولية بأنواعهــا ‪ 60000‬كيلــو‬\n      ‫متــر أو ‪ 3‬ســنوات ايهمــا اســبق باالنتهــاء ســيارات الكاديــاك بأنواعهــا‬\n      ‫‪ 100000‬أو ‪ 3‬ســنوات ايهمــا اســبق باالنتهــاء بالنســبة للســيارات‬\n      ‫املســتعملة)األفضلية ( فــإن الضمــان يختلــف مــن ســيارة ألخــرى ويكــون‬\n      ‫حســب االتفــاق اخلطــي بــن الطرفــن كمــا اتفــق الطرفــان علــى أن‬\n      ‫املؤجــر ال يتحمــل أجــور الصيانــة واإلصــاح الناجتــة عــن االســتعمال‬\n      ‫العــادي للســيار ة مــن قبــل املســتأجر‪ ،‬كمــا ال يحــق للمســتأجر مطالبــة‬\n      ‫املؤجــر بتأمــن ســيارة بديلة أثناء إجــراء أعمال الصيانة أو اإلصالحات‪.‬‬\n      ‫ثالــث عشــر ‪ :‬انتهــاء العقــد‪ ،‬ينتهــي عقــد اإليجــار بــأي حــال مــن احلــاالت‬\n                 ‫التالية‪ .1 .:‬عند انتهاء مدته وإعادة تسليم السيارة إلى املؤجر‪.‬‬\n      ‫‪ .2‬إذا اســتخدم املســتأجر خيــار الشــراء املمنــوح لــه مبوجــب املــادة‬\n      ‫«ســابعاً» مــن هــذا العقــد ومتلــك الســيارة‪ .3 .‬كذلــك ينتهــي العقــد إذا‬\n      ‫تعرضــت الســيارة حلــادث نتــج عنــه اعتبــار الســيارة يف حالــة هــاك وتلــف‬\n      ‫كلــي‪ ،‬أو ســرقت بــدون إهمــال أو تقصيــر مــن املســتأجر‪ ،‬ووافقــت‬\n      ‫شــركة التأمــن يف هاتــن احلالتــن علــى تعويــض املؤجــر عــن الســيارة‬\n\n\n‫‪239‬‬\n\f‫املذكــورة‪ ،‬ويف هــذه احلالــة يتــم حســاب قيمــة الســيارة وفــق اجلــدول‬\n‫االســتهالكي املبــن يف هــذا العقــد أعــاه واســتقطاع مبلــغ التعويــض‬\n‫الــوارد مــن شــركة التأمــن وإلــزام املســتأجر بفــرق القيمــة‪ .4 .‬ينتهــي‬\n‫العقــد بوفــاة املســتأجر وعلــى ورثتــه إعــادة الســيارة وســداد باقــي‬\n‫مســتحقات األجــرة‪ .‬علــى أنــه يجــوز لورثــة املســتأجر احللول محــل مورثهم‬\n‫واالســتمرار يف العقــد إذا طلبــوا ذلــك خــال شــهر واحــد مــن تاريــخ‬\n‫الوفــاة كتابــة ووافــق املؤجــر علــى ذلــك‪ .‬ويف هــذه احلالــة يجــب أن يتــم‬\n‫إجــراء التعديــل املطلــوب علــى العقــد كتابــة واســتكمال النمــاذج‬\n‫واألوراق الالزمــة‪ .‬رابــع عشــر‪ :‬حــل املنازعــات يقــر كل مــن الطرفــن أنه‬\n‫قــد اطلــع علــى هــذا العقــد وفهــم مــا يحتويــه وأنــه يقبــل بــكل شــروطه‬\n‫وأحكامــه ‪ .‬ويف حالــة حــدوث أي خــاف بــن الطرفــن يتعــذر حلــه‬\n‫بينهمــا بالطــرق الوديــة فــإن اخلــاف يحــال إلــى اجلهــات القضائيــة‬\n‫املختصــة باململكــة العربيــة الســعودية‪ .‬خامــس عشــر‪ :‬التحويــل ال يحــق‬\n‫للمســتأجر حتويــل هــذا العقــد إلــى الغيــر‪ .‬ســادس عشــر‪ :‬اإلخطــارات‬\n‫‪:‬تتــم اإلخطــارات املوجهــة بــن الطرفــن باليــد أو بالبريــد املســجل علــى‬\n‫العنــوان املبــن لــكل طــرف أمــام اســمه يف هــذه العقــد‪ .‬ســابع عشــر‪:‬‬\n‫التعديــل‪ :‬ال يجــوز تعديــل هــذا العقــد أو تغييــره أو الزيادة فيه إال مبوجب‬\n‫تعديــل مكتــوب متفــق عليــه بــن الطرفــن‪ .‬ثامــن عشــر ‪ :‬نســخ العقــد‪:‬‬\n‫يتــم حتريــر هــذا العقــد مــن نســختني باللغــة العربيــة بيــد كل طــرف‬\n‫نســخة منــه للعمــل مبوجبهــا‪ .‬املؤجــر شــركة ‪ .....‬للســيارات توقيعــه‬\n‫املســتأجر اســمه توقيعــه ) أ ‪ .‬ه ـ وقــد تصــادق عليــه الطرفــان ولكــون‬\n‫املدعــي مــن ضمــن طلباتــه يدعــي أن الشــركة تســببت يف عجــزه عــن‬\n‫عــاج ابنــه حتــى تــويف لــذا قــررت الكتابة لســمو أميــر املنطقة بتكليف‬\n\n\n                                                                                   ‫‪240‬‬\n\f      ‫جلنــة مــن مســتوى عــالٍ مــن اخلبــرة مكونــه من املــرور وفــرع وزارة التجارة‬\n      ‫والدفــاع املدنــي والشــرطة ورئيــس هيئــة النظــر وذلــك للتحقيــق يف‬\n      ‫القضيــة مــن جميــع جوانبهــا وإصــدار تقريــر يبــن فيــه حتديــد مســئولية‬\n      ‫الشــركة املدعــى عليهــا مــن عدمــه يف املســئولية املدعــى بهــا وحتــى‬\n      ‫ورود اجلــواب رفعــت اجللســة ويف يــوم األحــد املوافــق ‪1433/10/22‬ه ـ‬\n      ‫افتتحــت اجللســة يف الســاعة ‪ 9 : 30‬وفيهــا حضــر الطرفــان وكنــت قــد‬\n      ‫تلقيــت املعاملــة مــن صاحــب الســمو امللكــي أميــر منطقــة حائــل برقــم‬\n      ‫‪ 14369‬يف ‪1433/7/30‬ه ـ مرفقـ ًا بهــا تقريــر اللجنــة التــي قامت باملهمة‬\n      ‫وفــق خطابنــا رقــم ‪ 32554360‬يف ‪1433/4/18‬ه ـ الــوارد رفــق خطــاب‬\n      ‫مديــر شــرطة منطقــة حائــل رقــم ‪ 3022‬يف ‪1433/7/1‬ه ـ ونصــه ( تقرير‬\n      ‫للجنــة بتاريــخ ‪1433/6/23-22‬ه ـ بنــاء علــى برقيــة صاحــب الســمو‬\n      ‫امللكــي أميــر منطقــة حائــل حفظــه اهلل رقــم ‪ 9220‬واملؤرخــة يف‬\n      ‫‪1433/5/17‬ه ـ واملوجــه أساســها لســعادة مديــر شــرطة منطقــة حائــل‬\n      ‫املبنيــة علــى خطــاب رئيــس احملكمــة العامــة بحائــل رقــم ‪3255436‬‬\n      ‫واملــؤرخ يف ‪1433/4/18‬ه ـ املتعلقــة بدعــوى ‪ ...‬ســجل مدنــي رقــم ‪ ...‬ضــد‬\n      ‫شــركة ‪ .....‬بحائــل حيــث أن فضيلــة القاضــي ‪ ...‬أشــار بــأن املدعــي‬\n      ‫يدعــي علــى شــركة ‪ ...‬بأنــه اشــترى ســيارة بالتأجيــر املنتهــي بالتمليــك‬\n      ‫قيمتهــا خمســة وخمســون ألــف ومائــة وخمســون ريــال مقســطه علــى‬\n      ‫عــدد ‪ 48‬قســط ًا تبــدأ مــن ‪2008/7/1‬م وتنتهــي يف ‪2012/6/1‬م وكان‬\n      ‫منتظمـ ًا باألقســاط حتــى حصــل عليــه حــادث مــروري نتــج عنــه تلفيــات‬\n      ‫بالســيارة ثــم ســلمها للشــركة إلجــراء مــا يوجبــه العقــد بينهمــا فباعتهــا‬\n      ‫الشــركة دون علمــه مبــا يقــل عــن ثلــث قيمتهــا وزورا عليــه ورقــة بالعلــم‬\n      ‫والقبــول بالبيــع والتعهــد بدفــع باقــي متأخــرات العقــد فأضــروا بــه‬\n\n\n‫‪241‬‬\n\f‫ضــرار ًا متعمــد ًا منهــم ويطلــب املدعــي الــزام الشــركة تطبيــق العقــد‬\n‫وتعويضــه عــن الســيارة وتســببهم يف عجــزه عــن عــاج ابنــه حتــى تــويف‬\n‫وحيــث يــرى فضيلــة ناظــر القضيــة تكليــف جلنــة علــى مســتوى عــال مــن‬\n‫اخلبــرة والدرايــة مكونــه مــن إدارة املــرور والشــرطة والدفــاع املدنــي‬\n‫ووزارة التجــارة وهيئــة اخلبــراء باحملكمــة للتحقيــق بهــذه القضيــة مــن‬\n‫جميــع جوانبهــا وإصــدار تقريــر بــن فيــه حتديــد مســئولية الشــركة‬\n‫املدعــى عليهــا مــن عدمــه يف املســئولية املدعــي بهــا بعــد دراســة القضيــة‬\n‫دراســة متأنيــة تبــرا بهــا الذمــة حيــث أيــد ســموه ذلــك وإكمــال الــازم‬\n‫مبوجبــه فقــد اجتمعــت اللجنــة املشــكلة يف يــوم الســبت واألحــد املوافــق‬\n‫‪1433/6/23-22‬ه ـ وحيــث مت دراســة القضيــة مــن جميــع جوانبهــا‬\n‫وســماع اقــوال كل مــن املدعــي واملواطــن ‪ ...‬ســجل مدنــي رقــم ‪...‬‬\n‫والوكيــل الشــرعي لشــركة ‪ ...‬املواطــن ‪ ...‬ســجل مدنــي رقــم ‪ ...‬ومــن‬\n‫خــال الدارســة واملناقشــة او ًال تبــن ان عقــد التأمــن موقــع مــا بــن‬\n‫شــركة ‪ ....‬وشــركة ‪ ...‬حيــث قامــت شــركة ‪ ...‬بقبــول التفويــض املقدم‬\n‫مــن قبــل املدعــي لصالــح املواطــن ‪ ...‬بقيــادة الســيارة مــن نــوع اوبتــرا رقــم‬\n‫اللوحــة ‪ ...‬داخــل اململكــة حتــت مســئوليته الكاملــة حســب شــروط‬\n‫العقــد معــه ومبــا يتمشــى مــع النظــام علم ـ ًا بــأن الســيارة مومــن عليهــا‬\n‫رغــم أن ســنه أقــل مــن الســن احملــدد بالعقــد املبــرم بــن شــركة ‪....‬‬\n‫وشــركة التأمــن وبعــد وقــوع احلــادث اتضــح رفــض شــركة التأمــن‬\n‫لقبــول األوراق وبذلــك شــركة ‪ .....‬تتحمــل مســئولية إصــاح ســيارة‬\n‫املدعــي او تعويضــه عــن قيمتهــا قبــل وقــوع احلــادث بســبب قبولهــا‬\n‫التفويــض بــدون أخــذ موافقــة مســبقة مــن شــركة التأمــن ملــن تقــل‬\n‫اعمارهــم عــن واحــد وعشــرون ســنه حســب العقــد املبــرم بخصــوص‬\n\n\n                                                                                         ‫‪242‬‬\n\f      ‫ذلــك وذلــك لألدلــة التاليــة ‪ -1‬مــا جــاء بأقــوال املدعــي ‪ -2‬ما جــاء بصورة‬\n      ‫التفويــض مــن الشــركة للمواطــن ‪ .....‬واملوضــح باللفــة رقــم ‪ 79‬املتضمــن‬\n      ‫التفويــض بقيــادة الســيارة أوبتــرا رقــم اللوحــة ‪ -4 . .....‬رفــض شــركة‬\n      ‫التأمــن لــأوراق اخلاصــة باحلــادث كــون املفــوض يقــل عمــره عــن ثمانيــة‬\n      ‫عشــر عامـ ًا ومخالــف لالتفــاق املبــرم بــن شــركة ‪ ....‬وشــركة التأمــن‬\n      ‫‪ -5‬مــا ورد بأقــوال الوكيــل الشــرعي لشــركة ‪ ....‬املتضمــن التفويــض‬\n      ‫مت قبولــه بعــد تاريــخ احلــادث ثانيـ ًا تــرى اللجنــة بخصــوص مــا يطالــب بــه‬\n      ‫املدعــي بشــأن وفــاة أبنــه لشــركة ‪ ....‬فــإن الشــركة ال تتحمــل ذلــك‬\n      ‫لكونــه أبــرم عقــد لعــدد ثــاث ســيارات مــن الشــركة تلــف منهــا اثنــان‬\n      ‫واألخــرى يقــوم باســتخدامها ثالث ـ ًا تــرى اللجنــة مبــا يتعلــق مبطالباتــه‬\n      ‫بالتعويــض مالي ـ ًا مــن جــراء مراجعاتــه بخصــوص الدعــوى ومــا حلــق بــه‬\n      ‫مــن اضــرار حســب ادعائــه فــإن اللجنــة تــرى نظــر ذلــك مــن قبــل فضيلــة‬\n      ‫ناظــر القضيــة هــذا مــا مت التوصــل أليــه مــن قبــل اعضــاء اللجنــة وبــاهلل‬\n      ‫التوفيــق منــدوب فــرع وزارة التجــارة ‪ ...‬توقيعــه منــدوب شــرطة منطقــة‬\n      ‫حائــل ‪ ...‬توقيعــه منــدوب منطقــة حائــل مقــدم ‪ ...‬توقيعــه منــدوب هيئــة‬\n      ‫اخلبــراء باحملكمــة العامــة ‪ ....‬توقيعــه منــدوب الدفــاع املدنــي مبنطقــة‬\n      ‫حائــل رائــد ‪ ...‬توقيعــه أ ‪.‬ه ـ وبعــرض تقريــر اللجنــة علــى الطرفــن قــررا‬\n      ‫رغبتهمــا يف تقــدمي ردود ًا علــى التقريــر وطلبــا موعــد جلســة ال يقــل عــن‬\n      ‫شــهر فأجبتهمــا لطلبهمــا ورفعــت اجللســة ويف يــوم االثنــن املوافــق‬\n      ‫‪1433/11/22‬ه ـ افتتحــت اجللســة يف الســاعة ‪ 9 : 46‬وفيهــا حضــر‬\n      ‫الطرفــان وقــدم املدعــي رد ًا هــذا نصــه (ال يوجــد لــدي رد لفضيلتكــم‬\n      ‫فالقضيــة واضحــه باألدلــة التــي أمامكــم ولكــن ارغب مــن فضيلتكم‬\n      ‫ســؤال الوكيــل الشــرعي ‪ .....‬هــل كان يعمــل يف فــرع شــركة ‪.....‬‬\n\n\n‫‪243‬‬\n\f‫بحائــل بتاريــخ ‪1430/4/30‬ه ـ علمـ ًا بأنــه كان ال يعمل بالفرع وســؤالي‬\n‫تأكيــد ًا ملعلومــة هــي باألســاس مؤكــده وهــي إيجــاد مخــرج للشــركة‬\n‫للخــروج بأقــل التكاليــف فكيــف يقــول الوكيــل الشــرعي بــأن‬\n‫التفويــض حــرر وقــت حــدوث احلــادث وهــو غيــر موجــود بالشــركة‬\n‫أساس ـ ًا والــذي حــرر التفويــض مشــرف التحصيــل الســابق ‪ ....‬والــذي‬\n‫كان أســاس املشــكلة وســفر خــروج نهائــي مباشــرة بعــد رفــع القضيــة‬\n‫للجهــات املختصــة وهــذا فقــط توضيــح لفضيلتكــم مبــا تقــوم بــه‬\n‫الشــركة مــن محــاوالت لتعطيــل القضيــة وعــدم إعطــاء احلــق ملــن‬\n‫يســتحقه ) أ ‪.‬ه ـ وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال ليــس لــي‬\n‫رد عليــه كمــا قــدم املدعــى عليــه وكالــة رد ًا هــذا نصــه ( ردا علــى مــا‬\n‫جــاء بقــرار اللجنــة التــي شــكلت وتلــي علينــا مــن فضيلتكــم والــذي‬\n‫رأت اللجنــة إلــزام الشــركة بنــاء علــى بنــود التأمــن ونــص تفويــض‬\n‫القيــادة دون النظــر يف تاريــخ وقــوع احلــادث وتاريــخ التفويــض حيــث أن‬\n‫التفويض بقيادة الســيارة للشــهر الذي وقع فيه احلادث شــهر ‪1430/4‬هـ‬\n‫بالتحديــد لــم يقدمــه املدعــي احلــادث وقــع بتاريــخ ‪1430/4/22‬ه ـ‬\n‫والتفويــض محــل الدعــوى منــح اعتبــارا مــن ‪1430/5/1‬ه ـ ملــدة شــهر‬\n‫واحــد فقــط بعــد احلــادث بثمانيــة ايــام تفاويــض القيــادة تختــم وتوقــع‬\n‫شــهريا حســب أنظمــة وسياســة الشــركة بعــد ســداد األجــرة للســيارات‬\n‫املســتأجرة ويتــم التأكــد مــن الســدد حســب إيصــال الســداد الســيارة مت‬\n‫اســتالم أوراق احلــادث للشــركة لتقديــر تكاليــف احلــادث بتاريــخ‬\n‫‪1430/6/16‬ه ـ عــن طريــق مكتــب ‪ ...‬لتأجيــر الســيارات حســب صــور‬\n‫أوراق الصيانــة بالشــركة املرفقــة ولــم تدخــل باســم املســتأجر نفســه‬\n‫مــع أن جميــع األوراق املطلوبــة مــن تســعيرات للحــادث بعــد املعــارض قــد‬\n\n\n                                                                                   ‫‪244‬‬\n\f      ‫مت إنهــاء اجراءاتهــا بتاريــخ ‪1430/4/25‬ه ـ ونرفــق لفضيلتكــم صــورة‬\n      ‫مــن ورقــة تعهــد موقعــة مــن العميــل عنــد توقيــع العقــد تنــص أن للشــركة‬\n      ‫احلــق يف ســحب الســيارة إذا تأخــر العميــل أســبوع واحــد تفويــض مطلــق‬\n      ‫وشــامل وغيــر قابــل لإللغــاء ومــع العلــم أن العميــل كان متأخــر بالســداد‬\n      ‫بتاريــخ الورقــة التــي يــدى بهــا التزويــر ألكثــر مــن شــهرين مــن تاريــخ‬\n      ‫‪1430/1/18‬ه ـ إلــى ‪1430/4/16‬ه ـ علــى مــا تقــدم نطلــب مــن‬\n      ‫فضيلتكــم إلزامــه بإحضــار ورقــة التفويــض التــي تســبق هــذه الورقــة‬\n      ‫لألشــهر مــا قبــل ‪1430/5/1‬ه ـ للتأكــد مــن كان املفــوض بقيــادة‬\n      ‫الســيارة وقــت احلــادث حتديــد ًا والســام عليكــم ) أ ‪ .‬ه ـ كمــا ارفــق مــع‬\n      ‫الــرد صــورة ســند علــى مطبوعــات شــركة ‪ .....‬رقــم بــدون وتاريــخ بــدون‬\n      ‫ونصــه ( توكيــل بعــدم التوقــف عــن الســداد أو أطلــب تأجيــل أو إعفائــي‬\n      ‫مــن تســديد أي قســط ألي ســبب كان علم ـ ًا بــأن رواتبــي الشــهرية‬\n      ‫تصــرف يف نهايــة كل شــهر هجــري والتــزم بســداد أ ول قســط بتاريــخ‬\n      ‫‪2008/7/1‬م مــن شــهر ‪ 7‬مــن عــام ‪2008‬م ومبوجــب هــذا التعهــد أفــوض‬\n      ‫شــركة ‪ .....‬للســيارات تفويــض مطلــق وشــامل غيــر قابــل لإللغــاء يف‬\n      ‫ســحب الســيارة منــي يف حالــة تأخــري ملــدة أســبوع عــن ســداد أي قســط‬\n      ‫يف أي وقــت ويف أي مــكان دون إشــعار أو إنــذار ســابق لــي كمــا التــزم‬\n      ‫بعــدم وضــع أيــة أشــياء أو ممتلــكات داخــل الســيارة مــن قبلــي أو مــن‬\n      ‫قبــل اآلخريــن ملعرفتــي التامــة واملســبقة بــأن شــركة ‪ .....‬ســوف تقــوم‬\n      ‫باســترجاع الســيارة يف حالــة تأخــري عــن ســداد أي قســط ) أ ‪ .‬ه ـ‬\n      ‫وبعــرض ذلــك علــى املدعــي قــال إن ردي علــى هــذا الدفــع هــو أن اإلقــرار‬\n      ‫املنســوب لــي بتوكيــل ‪ .....‬املرصــود مــزور علــي وأنكــر صحتــه كمــا‬\n      ‫أنكــر صحــة توقيعــي عليــه هكــذا قــرر ثــم قــرر الطرفــان أن ليــس ألي‬\n\n\n‫‪245‬‬\n\f‫منهمــا رد اضــايف لــذا فقــد قــررت رفــع اجللســة لتأمــل مــا أســتجد مــن‬\n‫ضبــط ودفــوع ورفعــت اجللســة ويف يــوم االربعاء املوافــق ‪1433/12/29‬هـ‬\n‫افتتحــت اجللســة يف الســاعة ‪ 9 : 17‬وفيهــا حضــر الطرفــان وجــرى ســؤال‬\n‫طــريف القضيــة عــن تاريــخ اســتالم الســيارة مبوجــب محضــر التســليم‬\n‫واملبالــغ التــي وصلــت مــن قيمــة الســيارة واملبالــغ املتبقيــة وتاريــخ حصــول‬\n‫احلــادث واملبلــغ املســتحق فيمــا لــو مت تســديد قيمــة الســيارة يف تاريــخ‬\n‫حصــول احلــادث وتقديــر الســيارة قبــل احلــادث وبعدهــا واملبلــغ املســتحق‬\n‫مــن التأمــن فيمــا لــو كانــت شــروط التأمــن منطبقــة فطلــب الطرفــان‬\n‫مهلــة للــرد عليهــا ورفعــت اجللســة ويف يــوم االثنــن املوافــق ‪1434/2/4‬ه ـ‬\n‫افتتحــت اجللســة يف الســاعة ‪ 11 : 56‬وحضــر الطرفــان وقــرر املدعــى‬\n‫عليــه وكالــة أن تاريــخ اســتالم املدعــي للســيارة يف ‪1429/7/11‬ه ـ وأن‬\n‫قيمــة أيجــار الســيارة اجمــا ًال مبلغ ـ ًا قــدره خمســة وخمســون الف ـ ًا ومئــة‬\n‫وخمســون ريــا ًال وقــد ســدد املدعــى عليــه منهــا مبلغـ ًا قــدره عشــرة االف‬\n‫واربعمائــة وخمســون ريــا ًال وبقــي يف ذمتــه مبلغ ـ ًا قــدره اربعــة واربعــون‬\n‫الف ـ ًا وســبعمائة ريــال كمــا أن تاريــخ احلــادث كان يف ‪1430/4/22‬ه ـ‬\n‫كمــا أن الســيارة لــو كانــت ســليمة يف وقــت احلــادث وأراد املدعــي‬\n‫تســليم املبلــغ املتبقــي فإنــه مبوجــب نظــام الشــركة مبــا يســمى تصفيــة‬\n‫تعجيــل الدفــع يكــون املتبقــي يف ذمــة املدعــي مبلغـ ًا قــدره اربعــة وثالثون‬\n‫الف ـ ًا وثالثمائــة وتســعة عشــر ريــا ًال كمــا أن املبلــغ املفتــرض للتعويــض‬\n‫عــن احلــادث فيمــا لــو مت قبــول احلــادث مــن قبــل شــركة التأمــن مقارنــة‬\n‫بســيارة ســبقتها بأحــد عشــر يوم ـ ًا فقــط وبنفــس املواصفــات التابعــة‬\n‫للمدعــي مبلغ ـ ًا قــدره اثنــان وثالثــون ألف ـ ًا وأربعمائــة وواحــد وخمســون‬\n‫ريــا ًال كمــا أن الســيارة مت بيعهــا مــن قبــل الشــركة وقيمــة الســيارة قبــل‬\n\n\n                                                                                       ‫‪246‬‬\n\f      ‫احلــادث وبعــده مــن ثالثــة معــارض عــن طريــق املــرور معــرض ‪...‬قبــل‬\n      ‫احلــادث مبلغــا قــدره ثالثــون الــف ريــال ومعــرض ‪ ....‬مبلغ ـ ًا قــدره ثمانيــة‬\n      ‫وعشــرون الــف ريــال ومعــرض ‪ ....‬مبلغــا قــدره ســبعة وعشــرون الــف ريــال‬\n      ‫وبعــد احلــادث قــدرة املعــارض الثالثــة الســيارة مبلغ ـ ًا قــدره عشــرة االف‬\n      ‫ريــال وبعــرض ذلــك علــى املدعــي ‪ .....‬علــى جميــع مــا قــرره املدعــى عليــه‬\n      ‫وكالــة جملــة وتفصيــا ثــم حــدد موعــدا للنطــق باحلكــم يــوم األحــد‬\n      ‫املوافــق ‪1434/02/10‬ه ـ الســاعة ‪ 08 : 30‬ورفعــت اجللســة ويف يــوم‬\n      ‫االحــد املوافــق ‪1434/2/10‬ه ـ افتتحــت اجللســة يف الســاعة ‪9 : 00‬‬\n      ‫وحضــر الطرفــان وقــرر املدعــي أن الســيارة عندمــا كانــت باســتالمه‬\n      ‫فــإن احلــادث قــد حصــل مــع طــرف آخــر وقــرر املــرور أن نســبة اخلطــأ‬\n      ‫عليــه أي علــى املدعــي بنســبة ‪ %100‬وأنــه قنــع بهذه النســبة كما تصادق‬\n      ‫الطرفــان أن الســيارة مت اســتالمها مــن قبــل الشــركة بعــد احلــادث يف‬\n      ‫‪1430/6/16‬ه ـ ومت بيعهــا يف ‪1430/7/1‬ه ـ وكنــت قــد تأملت القضية‬\n      ‫ودرســتها وحيــث أن املدعــي يطالــب شــركة ‪ .....‬بتعويضــه بســيارة‬\n      ‫مماثلــة وحتميلهــم أضــرار بيــع الســيارة دون قيمتهــا وأجــرة الســيارة التــي‬\n      ‫حتملهــا بســببهم طيلــة القضيــة وتســببهم يف عجــزه عــن عــاج ابنــه حتــى‬\n      ‫تــويف وأن وكيــل الشــركة املدعــى عليهــا قــدم رده املكتــوب مضمونــه‬\n      ‫أن الشــركة ملتزمــة مبــا جــاء يف العقــد وأن الشــركة غيــر مســئولة‬\n      ‫عمــا جــاء يف دعــوى املدعــي وحيــث مت تكليــف جلنــة حســب مــا هــو‬\n      ‫ا وتوصلــت اللجنــة إلــى حتميــل شــركة ‪.....‬‬      ‫مــدون يف ضبطــه تفصي ـ ً‬\n      ‫مســئولية إصــاح ســيارة املدعــي أو تعويضــه عــن قيمتهــا حيــث قبلــت‬\n      ‫الشــركة التعويــض أمــام شــركة التأمــن كمــا خلصــت اللجنــة إلــى‬\n      ‫أن الشــركة املدعــى عليهــا ال تتحمــل مــا يتعلــق مبــا ذكــره مــن تســببهم‬\n\n\n‫‪247‬‬\n\f‫يف وفــاة أبنــه وأن باقــي طلبــه حقوقــه من األضرار راجــع للنظر القضائي‬\n‫وقــد ظهــر لــي مــا يلــي أو ًال فــإن العقــد بــن الطرفــن إيجــار مــع وعــد‬\n‫بالبيــع وهــو املســمى باإليجــار املنتهــي بالتمليــك ومبــا أن حقيقــة هــذا‬\n‫العقــد شــرع ًا فيمــا ظهــر لــي بيــع برهــن والثمــن مؤجــل يســدد علــى‬\n‫أقســاط لــذا فــإن الــذي يجــري عليــه أحــكام البيــع برهــن مــن ذلــك حــق‬\n‫املدعــى عليــه يف متلــك الســيارة وحــق املدعــي يف توثيــق الديــن بالعــن‬\n‫وحقــه يف الثمــن علــى املدعــي ألن العبــرة يف العقــود باملقاصــد واملعانــي‬\n‫ال باأللفــاظ كمــا أن يف تكييــف هــذا التعامــل اإليجــار املنتهــي‬\n‫بالتمليــك بأنــه بيــع يف رهــن ضمــان حلقــوق املتعاملــن مــن التالعــب فــا‬\n‫يغــرر بشــخص بالدخــول يف عقــد تأجيــر مــع وعــد بيــع ثــم يحــرم منــه‬\n‫وقــد ســدد الثمــن أو أكثــره بحجــة أنــه إيجــار ال بيــع وســد الذرائــع‬\n‫املؤديــة للفســاد وأكل احلقــوق مقصــد معتبــر يف الشــرع وال مينــع مــن‬\n‫كــون ذلــك بيــع برهــن بقــاء العــن يف يــد املشــتري وعــدم قبــض الرهــن‬\n‫وهــو قــول مالــك وروايــة عــن أحمــد وهــو املذهــب عنــد أبــن عقيــل وغيــره‬\n‫قــال القاضــي هــذا قــول أصحابنــا وقــال الفخــر بــن تيميــة هــذا أشــهر‬\n‫الروايتــن وأفتــى بــه الشــيخ عبدالرحمــن البابطــن يف العقــار ونحــوه‬\n‫وأفتــى بــه الشــيخ حســن بــن حســن وأختــاره الشــيخ أبــن ســعدي يف الــدرر‬\n‫الســنية م ‪4 /‬ج ‪ 5‬صفحــة ‪ 127‬و ‪ 129‬واملختــارات اجلليــة صفحــة ‪ 187‬و‬\n‫‪ 181‬و ‪ 180‬والفتــاوى صفحــة ‪256‬وكالهمــا ألبــن ســعدي وحيــث‬\n‫تصــادق الطرفــان علــى أن األقســاط املتبقيــة للشــركة املدعــى عليهــا‬\n‫مبلغـ ًا قــدره أربعــة وأربعــون ألفـ ًا وســبعمائة ريــال وأن األقســاط املتبقيــة‬\n‫مبلغ ـ ًا قــدره أربعــة وثالثــون ألف ـ ًا وثالثمائــة وتســعة عشــر ريــا ًال وهــو‬\n‫تصفيــة تعجيــل الدفــع وأن املبلــغ املتوقــع للتعويــض عــن احلــادث مــن‬\n\n\n                                                                                        ‫‪248‬‬\n\f      ‫شــركة التأمــن فيمــا لــو مت قبولهــا مبلغ ـ ًا قــدره أثنــان وثالثــون الف ـ ًا‬\n      ‫وأربعمائــة وواحــد وخمســون ريــا ًال وإن الســيارة قــدرت بعــد احلــادث مــن‬\n      ‫ثالثــة معــارض هــم ‪ ..... ..... .....‬بعشــرة آالف ريــال وحيــث أن الشــركة‬\n      ‫تصرفــت يف الســيارة وباعتهــا لــذا فتكــون ضامنــة لهــا كمــا أنهــا‬\n      ‫تســببت يف تفويــت التعويــض املســتحق للمدعــي وحيــث تقــرر أن العقــد‬\n      ‫بيــع وأن الســيارة يف احلقيقــة ملــك ًا للمدعــي وحيــث أن التأجيــل يف‬\n      ‫األقســاط أمنــا هــو ألجــل تســديد األقســاط حســب املــدة املتفــق عليهــا‬\n      ‫وحيــث أن الشــركة حقهــا يف األقســاط حتــى نهايتهــا إمنــا هــو يف‬\n      ‫اكتمــال املــدة وقــد تبــن أن الشــركة قــد اســتلمت الســيارة بعــد احلادث‬\n      ‫وأبقــت الســيارة لديهــا مــن أجــل مــا يقتضيــه العقــد ثــم باعــت الســيارة‬\n      ‫دون الرجــوع إلــى املدعــي وقــد تقــرر أن العقــد بيع برهــن فيطبق أحكام‬\n      ‫املغصــوب علــى الســيارة وأن املســتحق لهــم حســب إقرارهــم ومصادقــة‬\n      ‫املدعــي علــى ذلــك مبلغ ـ ُا قــدره اربعــة وثالثــون الف ـ ًا وثالثمائــة وتســعة‬\n      ‫عشــر ريــا ًال فيكــون املســتحق للمدعــي قيمــة الســيارة بعــد احلــادث‬\n      ‫مبلغـ ًا قــدره عشــرة االف ريــال زائــد ًا مبلــغ التعويــض املتوقــع وقــدره اثنــان‬\n      ‫وثالثــون الــف وثالثمائــة وتســعة عشــر ريــا ًال ويخصــم منــه األقســاط‬\n      ‫املســتحقة للشــركة مبلغ ـ ًا قــدره أربعــة وثالثــون الف ـ ًا وثالثمائــة وتســعة‬\n      ‫عشــر ريــا ًال ويكــون النــاجت مبلغ ـ ًا قــدره ثمانيــة آالف ومائــة واثنــان‬\n      ‫وثالثــون ريــا ًال هــي املســتحقة للمدعــي وأمــا مطالبتــه بأضــرار ببيــع‬\n      ‫الســيارة دون قيمتهــا وأجــرة الســيارة التــي حتملهــا بســبب الشــركة‬\n      ‫طيلــة القضيــة وتســببهم يف عجــزه عــن عــاج ابنــه حتــى تــويف فلــم يظهــر‬\n      ‫لنــا توجههــا ألن حقــه يف رفــع الضــرر وقــد مت رفعــه بإعطائــه مــا يســتحق‬\n      ‫ولهــذا نظائــر عنــد العلمــاء حيــث نــص ســماحة املفتــي الســابق الشــيخ‬\n\n\n‫‪249‬‬\n\f‫محمــد بــن إبراهيــم‪ :‬ال يتحمــل مــا ينفقــه املصــاب املتســبب علــى املجنــي‬\n‫عليــه مــدة مرضــه فتــاوى الشــيخ محمــد بــن إبراهيــم ‪ 341‬و ‪ 342‬اجلــزء‬\n‫(‪ )11‬واملدعــي قــد ســلم الســيارة للشــركة بســبب احلــادث وتصرفــت‬\n‫الشــركة بهــا ومت احلكــم لــه بقيمــة الســيارة بعــد احلــادث مــع الضمــان‬\n‫املســتحق لــه الــذي تســببت الشــركة يف تفويتــه وحيــث أن منافــع‬\n‫املغصــوب مضمونــه والغاصــب يضمــن أجــرة املغصــوب الــذي جــرت‬\n‫العــادة بتأجيلــه إلــى حــن رده أو تلفــه شــرح املنتهــى ‪ 403/2‬و ‪421‬‬\n‫والكشــاف ‪ 187/4‬ولذلــك كلــه فقــد قــررت أو ًال ألــزام الشــركة‬\n‫املدعــى عليهــا بتســليم املدعــي مبلغ ـ ًا قــدره ثمانيــة األف ومئــة وأثنــان‬\n‫وثالثــون ريــا ًال ثاني ـ ًا صرفــت النظــر عــن باقــي مــا يطالــب بــه املدعــي‬\n‫وبــكل مــا تقــدم حكمــت وأفهمــت املدعــي بــأن لــه مطالبــة الشــركة‬\n‫بأجــرة الســيارة مــدة بقائهــا عنــد الشــركة مــن اســتالمها بتاريــخ‬\n‫‪1430/6/16‬ه ـ وحتــى بيعهــا يف ‪1430/7/1‬ه ـ وبإعــان احلكــم قــرر‬\n‫الطرفــان عــدم القناعــة واســتعدا بتقــدمي الئحــة فأفهمــا بــأن مــدة‬\n‫االعتــراض قدرهــا ثالثــون يوم ـ ًا تبــدأ بعــد مهلــة اســتالم الصــك وأن‬\n‫عليهمــا املراجعــة يف يــوم الســبت املوافــق ‪1434/2/16‬ه ـ الســاعة‬\n‫الواحــدة ظهــر ًا الســتالم صــورة الصــك وإذا مضــت املــدة ولــم يقدمــا‬\n‫اعتراضهمــا خاللهــا فــإن احلكــم يكتســب القطعيــة ويكــون بات ـ ًا‬\n‫واجــب النفــاذ ففهمــا ذلــك ورفعــت اجللســة يف الســاعة ‪ 9 : 21‬وعليــه‬\n‫حصــل التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه‬\n                                             ‫اجمعني حرر يف ‪1434/2/10‬هـ ‪.‬‬\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 3460333‬وتاريــخ‬\n                                                          ‫‪1434/3/11‬هــ‪.‬‬\n\n\n                                                                                      ‫‪250‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":218,"source_page_end":250,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cd1627afb1b2cffa933719ebca63ee280020e5003ba7e13ec6ec1852dd6521e5","normalized_text_hash":"b7a1221bf6bae1e47c17729af6074cd26b618e25f0b699a4cb6e0637a2150ac0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p218-3438433"},{"id":"e4823d3e-ae53-51c1-ada2-0eda4a5d6bd3","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقار -شراء قطعة أرض من مورث القاصر حال حياته - إقرار ولي القاصر بصحه الدعوى -قبول شهادة املدعى عليه يف حق القاصر -القضاء بالشاهد واليمن -ثبوت شراء املدعي للعقار","document_number":"3451723","case_number":"3499120","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/1","year":"1434","subject":"بيع -عقار -شراء قطعة أرض من مورث القاصر حال حياته - إقرار ولي القاصر بصحه الدعوى -قبول شهادة املدعى عليه يف حق القاصر -القضاء بالشاهد واليمن -ثبوت شراء املدعي للعقار","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/3/1 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3451723 :‬‬\n                          ‫َر ْق ُم الدعوى‪3499120 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34955041‬تاريخه‪1434/5/14 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬عقــار‪ -‬شــراء قطعــة أرض مــن مــورث القاصــر حــال حياتــه ‪-‬‬\n      ‫إقــرار ولــي القاصــر بصحــه الدعــوى ‪ -‬قبــول شــهادة املدعــى عليــه يف‬\n      ‫حــق القاصــر‪ -‬القضــاء بالشــاهد واليمــن ‪ -‬ثبــوت شــراء املدعــي للعقــار‬\n                                                                ‫موضــع الدعــوى ‪.‬‬\n\n\n\n\n      ‫مــا رواه مســلم يف صحيحــه أن النبــي صلــى اهلل عليــه وســلم قضــى‬\n                                                         ‫بشــاهد وميــن ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بأنــه اشــترى مــن مــورث املدعــى عليهــم قطعــه أرض‬\n      ‫(ذكــر وصفهــا) حــال حياتــه وأنــه ســلمه جــزء مــن قيمــة األرض واجلــزء‬\n      ‫املتبقــي ســلمه لوكيــل الورثــة بعــد مــوت املــورث ‪ ،‬طلــب املدعــى احلكــم‬\n      ‫بنقــل ملكيــه العقــار املذكــور لــه ‪ ،‬أقــر املدعــى عليــه أصالــة ووكالــة‬\n      ‫مبــا جــاء يف دعــوى املدعــى ‪ ،‬شــهد املدعــى عليــه أصالــة ووكالــة بصحة‬\n      ‫الدعــوى ‪ ،‬جــرى تعديــل املدعــى عليــه ‪ ،‬حلــف املدعــي اليمــن تكملــة‬\n      ‫لبينتــه ‪ ،‬صــدر احلكــم بثبــوت شــراء املدعــي للعقــار موضــع الدعــوى‬\n      ‫مــن مــورث املدعــى عليهــم وتســليم ثمنــه ‪ ،‬والتهميــش علــى صــك امللــك‬\n      ‫بذلــك بعــد اكتســاب احلكــم القطعيــة ‪ ،‬رفعــت املعاملــة حملكمــة‬\n\n‫‪251‬‬\n\f‫االســتئناف حيــث إن مــن ضمــن املدعــى عليهــم قاصــرة ‪ ،‬صــدق احلكــم‬\n                                             ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا د‪ )....( .‬القاضــي باحملكمــة العامــة‬\n‫بالريــاض بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض املســاعد برقــم ‪ 3499120‬يف ‪1434/2/30‬ه ـ‬\n‫املقيــدة برقــم ‪ 34514642‬يف ‪1434/2/30‬ه ـ يف يــوم األحــد املوافــق‬\n‫‪1434/3/1‬ه ـ افتتحــت اجللســة الســاعة ‪ 10.15‬وفيهــا حضــر املدعــي‬\n‫‪ ...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪...‬وادعــى علــى احلاضــر معــه‬\n‫‪ ...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪...‬أصالــة عــن نفســه وبصفتــه‬\n‫ا عــن ‪ ...‬أصالــة عــن نفســها وبصفتهــا وليــة علــى ابنتهــا ‪...‬‬    ‫وكي ـ ً‬\n‫مبوجــب صــك الواليــة الصــادر مــن هــذه احملكمــة برقــم ‪ 28/19‬يف‬\n‫‪1429/9/1‬ه ـ وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة بجنــوب الريــاض رقــم ‪ 72645‬يف ‪1429/9/1‬ه ـ والتــي تخولــه‬\n‫يف املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإقامــة الدعــوى ولــه حــق‬\n‫البيــع والشــراء واإلفــراغ وقبولــه ‪ ،‬قائــا يف دعــواه عليــه ‪ :‬لقــد اشــتريت‬\n‫ا عنهــم قطعــة األرض رقــم‬     ‫مــن مــورث املدعــى عليــه ومــن هــو وكي ـ ً‬\n‫‪ 1208‬مــن املخطــط ‪ 3200‬الواقعــة يف حــي املصفــاة بالريــاض وحدودهــا‬\n‫وأطوالهــا شــما ًال ‪ :‬قطعــة األرض رقــم ‪ 1209‬بطــول خمســة وثالثــن متــرا‬\n‫‪ ،‬وجنوبــا قطعــة رقــم ‪ 1207‬بطــول خمســة وثالثــن متر ًا ‪ ،‬وشــرق ًا قطعة‬\n‫رقــم ‪ 1203‬بطــول ســبعة عشــر متــر ًا وأربعــة عشــر ســنتيمتر ًا ‪ ،‬وغرب ـ ًا‬\n‫شــارع عــرض ‪15‬م بطــول ســبعة عشــر متــر ًا وأربعــة عشــر ســنتيمتر ًا ‪،‬‬\n\n                                                                                    ‫‪252‬‬\n\f      ‫ومجمــوع مســاحتها خمســمائة وتســعة وتســعني متــر ًا مربع ـ ًا وتســعني‬\n      ‫ســنتيمتر ًا ‪ ،‬واململوكــة لــه مبوجــب الصــك الصــادر مــن كتابــة العــدل‬\n      ‫األولــى بالريــاض برقــم ‪ 13/71216‬يف ‪1424/11/7‬ه ـ وذلــك يف عــام‬\n      ‫‪1428‬ه ـ وذلــك بقيمــة إجماليــة قدرهــا ثالثــون ألــف ريــال دفعــت منهــا‬\n      ‫أربعــة وعشــرين ألــف ريــال نقــد ًا ملــورث املدعــى عليهــم ‪ ...‬حــال حياتــه‬\n      ‫‪ ،‬والباقــي وقــدره ســتة آالف ريــال ســلمتها نقــد ًا للمدعــى عليــه احلاضــر‬\n      ‫بعــد وفــاة مورثهــم ‪ ،‬أطلــب احلكــم بنقــل ملكيــة العقــار املذكــور لــي‬\n      ‫ا ‪ :‬إن مــا ذكــره‬  ‫‪ ،‬هكــذا ادعــى‪ ،‬وبســؤال املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫ا ‪ ،‬وقــد أبلغنــي والــدي قبــل وفاتــه‬ ‫املدعــي كلــه صحيــح جملــة وتفصيـ ً‬\n      ‫بذلــك وأشــهد بذلــك ‪ ،‬وال مانــع لــدى الورثــة مــن نقــل ملكيــة العقــار‬\n      ‫للمدعــي متــى مــا صــدر حكــم بذلــك بــراءة لذمــة مورثنــا ‪ ،‬حيــث أن‬\n      ‫أحــد الورثــة قاصــرة وهــي ‪ ،...‬كمــا أبــرز صــك حصــر ورثــة ‪ ...‬الصــادر‬\n      ‫مــن هــذه احملكمــة برقــم ‪ 30/100/385‬يف ‪1429/8/29‬ه ـ املجلــد‬\n      ‫رقــم ‪ 30/7‬املتضمــن وفاتــه يف ‪1429/8/22‬ه ـ وانحصــار ورثتــه يف‬\n      ‫زوجتــه ‪...‬ويف ابنــه ‪...‬وابنتــه ‪...‬املولــودة يف ‪1427/2/23‬ه ـ ‪ ،‬كمــا أبــرز‬\n      ‫صــك الواليــة علــى ‪...‬الصــادر مــن هــذه احملكمــة برقــم ‪ 18/19‬يف‬\n      ‫‪1429/9/1‬ه ـ املتضمــن إقامــة والدتهــا ‪...‬وليــة عليهــا ‪ ،‬وباالطــاع عليها‬\n      ‫وجدتهــا مطابقــة ملــا ذكــره ‪ ،‬وبطلــب البينــة مــن املدعــي قــال ‪ :‬بينتــي‬\n      ‫هــي إقــرار املدعــى عليــه احلاضــر وشــهادته بــأن والــده قــد أبلغــه ببيــع‬\n      ‫األرض املذكــورة لــي حــال حياتــه وأنــه اســتلم مــن القيمــة مبلــغ وقــدره‬\n      ‫أربعــة وعشــرون ألــف ريــال نقــد ًا ‪ ،‬وكذلــك إقــراره باســتالمه للباقــي‬\n      ‫وقــدره ســتة آالف ريــال نقــد ًا منــي بعــد وفــاة مورثــه ‪ ،‬هكــذا أجــاب ‪،‬‬\n      ‫وبســؤاله هــل لديــه زيــادة بينــة قــال ‪ :‬ليــس لــدي زيــادة بينــة ‪ ،‬فطلبــت منــه‬\n\n\n‫‪253‬‬\n\f‫تعديــل املدعــى عليــه فأحضــر كال مــن ‪... :‬ســعودي مبوجــب الســجل‬\n‫املدنــي رقــم ‪...‬و ‪...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪...‬فشــهدا بعدالــة‬\n‫وثقــة املدعــى عليــه ‪ ،‬وبعــرض ميــن االســتظهار علــى املدعــي تقويــة للبينة‬\n‫ا ‪ :‬واهلل العظيــم إنني‬            ‫قــال‪ :‬ال مانــع لــدي مــن أداء اليمــن ‪ ،‬ثــم حلــف قائـ ً‬\n‫قــد اشــتريت األرض املذكــورة يف الدعــوى مــن مــورث املدعــى عليهــم‬\n‫‪...‬حــال حياتــه مببلــغ وقــدره ثالثــون ألــف ريــال ســلمت منهــا لــه نقــد ًا‬\n‫أربعــة وعشــرون ألــف ريــال ‪ ،‬والباقــي وقــدره ســتة آالف ريــال ســلمتها‬\n‫نقــد ًا للمدعــى عليــه احلاضــر بعــد وفــاة مورثهــم ‪ ،‬هكــذا حلــف ‪ ،‬كمــا‬\n‫جــرى االطــاع علــى صــك العقــار املذكــور فوجــدت يف أعــاه أنــه‬\n‫ســاري املفعــول يف ‪1434/02/17‬ه ـ ‪ ،‬فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وحيــث صــادق املدعــى عليــه علــى دعــوى املدعــي وشــهد بهــا‬\n  ‫ا ‪َ ،‬وقَ ــدْ ثَبـ َـت ( َأ َّن ال َّن ِبــي ‪َ -‬ص َّلــى َّ ُ‬\n‫الل‬                                                            ‫وأنــه اســتلم مبلــغ الشــراء كام ـ ً‬\n                   ‫َّ‬                         ‫َ‬\n‫ن ) ‪َ .‬ر َو ُاه ُمسـل ٌِم ‪ ،‬وألن املدعــي حلــف‬               ‫َع َليـ ِه َو َسـل ََّم ‪ -‬قَ َضــى ِب َشــاهِ دٍ َو َ ِيـ ٍ‬\n‫ميــن االســتظهار فقــد ثبــت لــدي شــراء املدعــي العقــار املذكــور أعــاه‬\n‫مــن مــورث املدعــى عليهــم وتســليمه أربعــة وعشــرين ألــف ريــال نقــد ًا‬\n‫ملورثهــم وســتة آالف ريــال نقــد ًا للمدعــى عليــه ‪ ،‬وأمــرت برفــع كامــل‬\n‫املعاملــة حملكمــة االســتئناف وبعــد تصديقــه ســيتم التهميــش مبوجبــه‬\n‫علــى صــك العقــار وســجله ‪ ،‬ورفعــت اجللســة الســاعة ‪ ، 10.45‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                                                   ‫حــرر يف ‪1434/3/1‬ه ـ‬\n‫ويف يــوم األحــد املوافق‪1434/05/19‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 10.15‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف بالريــاض‬\n‫برقــم ‪ 34955041‬يف ‪1434/5/14‬ه ـ مرفــق بهــا قــرار الدائــرة الثانيــة‬\n\n\n                                                                                                                            ‫‪254‬‬\n\f      ‫لألحــوال الشــخصية واإلنهــاءات رقــم ‪ 34196714‬يف ‪1434/4/24‬ه ـ‬\n      ‫املتضمــن ‪ :‬املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬قاضــي اســتئناف‬\n      ‫‪ ...‬ختمــه وتوقيعــه قاضــي اســتئناف ‪...‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n      ‫‪...‬ختمــه وتوقيعــه أ‪.‬ه ـ وحتــى ال يخفــى جــرى حتريــره ‪ ،‬وبــاهلل التوفيــق‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪ 1434/05/19‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض املســاعد برقــم ‪ 34514642‬وتاريــخ ‪1434/4/9‬ه ـ املرفــق بهــا‬\n      ‫الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ... /‬املســجل‬\n      ‫برقــم ‪ 3451723‬وتاريــخ ‪1434/3/1‬ه ـ اخلــاص بدعــوى‪... /‬ضــد‪... /‬‬\n      ‫بشــأن إفــراغ العقــار املوضــح بالصــك ‪ ،‬وقــد تضمــن الصــك حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق‬\n                       ‫وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪255‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":251,"source_page_end":255,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b4445be13956ae82de773c00a335257da4bd0b7a0242ab0e873f713b8f03f708","normalized_text_hash":"8bb6a94de6c5a19682ec27098dd0d8029ba3e6d5ac70d6139ef432d751842ae5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p251-3451723"},{"id":"98f26839-ab21-5f43-95a1-c57a70653b25","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع أغنام -املطالبة بقيمة املبيع حللول موعد السداد -إثبات احلق بالقرائن واليمن املكملة -احلكم بسداد ثمن املبيع .","document_number":"34200343","case_number":"3458017","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/29","year":"1434","subject":"بيع أغنام -املطالبة بقيمة املبيع حللول موعد السداد -إثبات احلق بالقرائن واليمن املكملة -احلكم بسداد ثمن املبيع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/29 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34200343 :‬‬\n                    ‫َر ْق ُم الدعوى‪3458017 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34284082‬تاريخه‪1434/8/1 :‬هـ‬\n\n\n‫بيــع أغنــام ‪ -‬املطالبــة بقيمــة املبيــع حللــول موعــد الســداد ‪ -‬إثبــات‬\n    ‫احلــق بالقرائــن واليمــن املكملــة ‪ -‬احلكــم بســداد ثمــن املبيــع ‪.‬‬\n\n\n\n\n‫‪ -1‬ذكــر ابــن قدامــة رحمــه اهلل يف الــكايف (‪ )128/6‬مــا نصــه‪« :‬فــإن‬\n‫امتنــع اخلصــم مــن احلضــور عنــد احلاكــم حكــم عليــه ألنــه لــو لــم‬\n‫يحكــم عليــه جلعــل االمتنــاع واالســتتار طريق ـ ًا لتضييــع احلقــوق»‪.‬‬\n‫‪ -2‬ذكــر أبــو إســحاق إبراهيــم بــن حســن يف كتابــه معــن احلــكام علــى‬\n‫القضايــا واألحــكام مــا نصــه « مســألة قــال املــاوردي يف تفســير قولــه‬\n‫تعالــى «وإذا دعــوا إلــى اهلل ورســوله ليحكــم بينهــم» اآليــة دليــل علــى‬\n‫أنــه مــن دعــي إلــى حاكــم مــن حــكام املســلمني فعليــه اإلجابــة ويحــرج‬\n                                                                   ‫إن تأخــر)‪.‬‬\n‫‪ -3‬مــا ورد عــن احلســن بــن علــي رضــي اهلل عنهمــا أن النبــي صلــى اهلل‬\n‫عليــه وســلم قــال (مــن دعــي إلــى حاكــم مــن حــكام املســلمني ولــم يجــب‬\n                                                    ‫فهــو ظالــم ال حــق لــه)‪.‬‬\n        ‫‪ -4‬املادة (‪ )55‬من نظام املرافعات الشرعية والئحته التنفيذية ‪.‬‬\n\n\n\n‫ادعــى املدعــي بــأن املدعــى عليــه اشــترى منــه عــدد ًا مــن األغنــام ولــم‬\n‫يســدد لــه أي شــيء مــن ثمنهــا بعــد حلــول موعــد أدائــه‪ ،‬لــذا طلــب إلــزام‬\n                                                                                     ‫‪256‬‬\n\f      ‫املدعــى عليــه بســداد ثمنهــا حــاالً‪ ،‬املدعــى عليــه لــم يحضــر رغــم تبلغــه‬\n      ‫باحلضــور لــذا فقــد طلبــت احملكمــة بينــة املدعــي فأبــرز كمبيالــة مــن‬\n      ‫املدعــى عليــه تتضمــن التزامــه باملبلــغ املدعــى بــه للمدعــي كمــا طلبــت‬\n      ‫احملكمــة منــه اليمــن علــى صحــة دعــواه فأداهــا طبــق مــا طلــب منــه‪،‬‬\n      ‫املدعــى عليــه لــم يحضــر رغــم تبلغــه باحلضــور ولــم يقــدم عــذرا لعــدم‬\n      ‫احلضــور كمــا لــم يقــدم دفاعــه علــى هــذه الدعــوى واملدعــي تقــوى‬\n      ‫جانبــه مبــا قدمــه مــن بينــة كمــا أنــه حلــف اليمــن التــي طلبــت منــه ‪،‬‬\n      ‫قضــت احملكمــة بإلــزام املدعــى عليــه أن يدفــع للمدعــي املبلــغ املدعــى‬\n                     ‫بــه ‪ ،‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة املســاعد بالطائــف برقــم ‪ 3458017‬وتاريــخ ‪1434/02/04‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34289712‬وتاريــخ ‪1434/02/04‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافق‪1434/03/07‬ه ـ افتتحــت اجللســة الســاعة ‪11: 00‬‬\n      ‫وفيهــا حضــر املدعــي (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫ا عنــه ولــم يقــدم عــذر ًا‬\n                                  ‫رقــم (‪ )........‬ولــم يحضــر املدعــى عليــه وال وكيـ ً‬\n      ‫عــن عــدم حضــوره ولــم يردنــا مــن قســم احملضريــن مــا يفيــد تبلغــه‬\n      ‫مبوعــد اجللســة لــذا قــررت رفــع اجللســة وإعــادة تبليــغ املدعــى عليــه ويف‬\n      ‫جلســة أخــرى حضــر املدعــي (‪ )........‬ســعودي اجلنســية مبوجــب الهويــة‬\n      ‫الوطنيــة رقــم (‪ )........‬الصــادرة مــن أحــوال الطائــف ولــم يحضــر املدعــى‬\n      ‫عليــه وال مــن ينــوب عنــه ولــم يقــدم عــذرا عــن عــدم حضــوره ولــم يردنــا‬\n\n‫‪257‬‬\n\f‫خطــاب قســم محضــري اخلصــوم باإلفــادة هــل املدعــى عليــه تبلــغ أم ال‬\n‫؟ وقــد وردنــا مــا يفيــد تبليــغ املدعــى عليــه لشــخصه مبوعــد اجللســة‬\n‫املاضيــة بخطــاب مديــر عــام التربيــة والتعليــم مبحافظــة الطائــف رقــم‬\n‫‪ 34311725‬يف ‪1434 /2/10‬هــ‪ ،‬واســتناد ًا للمــادة اخلامســة واخلمســن‬\n‫مــن نظــام املرافعــات الشــرعية رفعــت اجللســة ويف جلســة أخــرى أفتحــت‬\n‫اجللســة يف متــام الســاعة التاســعة والنصــف صباحـ ًا وفيهــا حضــر املدعــي‬\n‫(‪ )........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ )........‬ولــم‬\n‫ا عنــه وال مــن ينــوب عنــه ولــم يقــدم‬     ‫يحضــر املدعــى عليــه وال وكي ـ ً‬\n‫عــذر ًا عــن عــدم احلضــور وقــد وردنــا خطــاب مديــر عــام التربيــة والتعليــم‬\n‫بالطائــف رقــم ‪ 34579937‬يف‪1434/3/8‬ه ـ واملتضمــن‪( :‬تبليــغ املدعــى‬\n‫عليــه مبوعــد اجللســة املاضيــة لشــخصه) ‪ ،‬ثــم طلبــت مــن املدعــي حتريــر‬\n‫دعــواه فادعــى قائ ـاً‪ :‬إننــي أدعــي علــى الغائــب عــن مجلــس احلكــم‬\n‫الشــرعي املدعــو (‪ )........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫رقــم (‪ )........‬حيــث إنــه يف شــهر ‪ 9‬مــن عــام ‪1433‬ه ـ تقريبـ ًا اشــترى منــي‬\n‫عــدد ســتة عشــر رأس ـ ًا مــن الغنــم مــن نــوع طليــان حريــة بثمــن الــرأس‬\n‫الواحــد ألــف وخمســمائة ريــال واملجمــوع مبلــغ قــدره أربعــة وعشــرون‬\n‫ألــف ريــال علــى أن يســددني كامــل الثمــن بتاريــخ ‪1434/1/30‬ه ـ إال‬\n‫أن املدعــى عليــه لــم يســدد حتــى اآلن أي شــيء مــن هــذا املبلــغ وهــي حالــة‬\n‫األداء لــذا أطلــب إلــزام املدعــى عليــه بســداد هــذا املبلــغ لــي حــا ًال هــذه‬\n‫دعــواي‪ ،‬وبطلــب البينــة مــن املدعــي أبــرز لنــا كمبيالــة برقــم ‪10628‬‬\n‫بتاريــخ ‪1433/9/17‬ه ـ صــادرة مــن معــرض (‪. )........‬ت‪4323087/1‬‬\n‫باســم املديــن مبلــغ الكمبيالــة أربعــة وعشــرون ألــف ريــال ال غيــر تاريــخ‬\n‫االســتحقاق يف ‪1434/1/30‬ه ـ ثــم طلبــت مــن املدعــي اليمــن علــى‬\n\n\n                                                                                         ‫‪258‬‬\n\f      ‫ا (واهلل العظيــم الــذي ال إلــه‬   ‫صحــة دعــواه فاســتعد بهــا وحلــف قائ ـ ً‬\n      ‫إال هــو الــذي يعلــم اجلهــر ومــا يخفــى ويعلــم خائنــة األعــن ومــا تخفــي‬\n      ‫الصــدور إن اشــترى منــي عــدد ســتة عشــر رأس مــن الغنــم ثمنهــا أربعــة‬\n      ‫وعشــرون ألــف ريــال واتفقــت معــه علــى أن يكــون الســداد يف تاريــخ‬\n      ‫‪1434/1/30‬ه ـ وهــي حالــة األداء اآلن ولــم يصلنــي منهــا شــيء ولــم‬\n      ‫أبرئــه منهــا أي شــيء واهلل واهلل واهلل‪ ).‬هكــذا حلــف فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واســتنادا علــى املــادة اخلامســة واخلمســن مــن نظــام‬\n      ‫املرافعــات الشــرعية ولوائحهــا التنفيذيــة ومبــا أن املدعــى عليــه لــم‬\n      ‫يحضــر ولــم يقــدم عــذرا عــن ســبب عــدم احلضــور ولــم يقــدم دفاعــه علــى‬\n      ‫هــذه الدعــوى مــع أنــه تبلــغ بهــا حســب التعليمــات ‪ ،‬ومبــا أن املدعــي‬\n      ‫أبــرز الكمبيالــة وحلــف اليمــن التــي طلبــت منــه ‪ ،‬وعــدم حضــور‬\n      ‫املدعــى عليــه وهــذه قرائــن تقــوي جانــب املدعــي وقــد ذكــر ابــن قدامــه‬\n      ‫رحمــه اهلل تعالــى يف كتابــه الــكايف ‪ 128/6‬مــا نصــه (فــإن امتنــع‬\n      ‫اخلصــم مــن احلضــور عنــد احلاكــم حكــم عليــه ألنــه لــو لــم يحكــم‬\n      ‫عليــه جلعــل االمتنــاع واالســتتار طريقــا لتضييــع احلقــوق ) اهــ‪ .‬وقــد ذكــر‬\n      ‫أبــو إســحاق إبراهيــم بــن حســن يف كتابــه معــن احلــكام علــى القضايــا‬\n      ‫واألحــكام مــا نصــه (مســالة قــال املــاوردي يف تفســير قولــه تعالــى (وإذا‬\n      ‫دعــوا إلــى اهلل ورســوله ليحكــم بينهــم )اآليــة دليــل علــى أنــه مــن دعــي‬\n      ‫إلــى حاكــم مــن حــكام املســلمني فعليــه اإلجابــة ويحــرج إن تأخــر وقــد‬\n      ‫ورد عــن احلســن بــن علــي رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه قــال‬\n      ‫(مــن دعــي إلــى حاكــم مــن حــكام املســلمني ولــم يجــب فهــو ظالــم ال‬\n      ‫حــق لــه ) اهــ‪ ،‬لذلــك كلــه فقــد حكمــت بإلــزام املدعــى عليــه الغائــب‬\n      ‫عــن مجلــس احلكــم الشــرعي أن يدفــع للمدعــي مبلــغ أربعــة وعشــرين‬\n\n\n‫‪259‬‬\n\f‫ألــف ريــال حــاال هــذا مــا ظهــر لــي وبــه حكمــت ‪ ،‬وقــررت بعــث نســخة‬\n‫مــن صــك احلكــم للمدعــى عليــه ليقــدم اعتراضــه خــال ثالثــن يوم ـ ًا‬\n‫مــن تاريــخ التبليــغ باحلكــم وإذا لــم يقــدم اعتراضــه خاللهــا فيســقط‬\n‫حقــه يف االعتــراض ويكتســب احلكــم القطعيــة‪ ،‬وكان اختتــام‬\n‫هــذه اجللســة يف متــام الســاعة العاشــرة صباح ـاً‪ ،‬وبــاهلل التوفيــق وصلــى‬\n‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪ ،‬حــرر يف‬\n                                                            ‫‪1434/4/27‬هــ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪:‬‬\n‫ثــم عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة مصادقـ ًا‬\n‫عليهــا بالقــرار رقــم ‪34284082‬يف ‪1434/8/1‬ه ـ ونصــه احلمــد هلل‬\n‫والصــاة والســام علــى رســول اهلل وبعــد فقــد جــرى اطالعنــا نحــن‬\n‫رئيــس عضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة علــى الصك الصادر من فضيلة الشــيخ (‪)........‬‬\n‫القاضــي باحملكمــة العامــة بالطائــف واملســجل بعــدد ‪34200343‬‬\n‫وتاريــخ ‪1434/4/29‬ه ـ املتضمــن دعــوى ضــد(‪ )........‬واحملكــوم فيــه‬\n‫مبــا دون باطنــه وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫تقــرر املوافقــة علــى احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم قاضــي اســتئناف ختــم وتوقيــع‪ .‬قاضــي اســتئناف (‪)........‬‬\n‫ختــم وتوقيــع‪ .‬رئيــس الدائــرة موقــع يف االصــل وموافــق علــى احلكــم‬\n‫ومجــاز ‪ .‬وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬حــرر يف ‪1434/8/14‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪260‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":256,"source_page_end":260,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"13521853caf09c9cc1fbfcf836cab199baf8bc86288e8b10b8fc4fa8f027a591","normalized_text_hash":"92a73cb710b5ab7ee70ff0bb1f8d68f25e4265ca4e17a21c4ee8e910d34cf344","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p256-34200343"},{"id":"133222ef-9cc2-5691-9a0b-b176e17f760e","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع إبل بثمن آجل -سماع الدعوى غيابيا لعدم حضور املدعى عليه -شهادة الشاهد العدل شرع ا وحلف اليمن -اإللزام بدفع باقي مبلغ املبايعة -الغائب على حجته متى حضر .","document_number":"34272302","case_number":"3469186","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملويه","circuit":"الدائرة احلقوقية اخلامسة رقم 34339440وتاريخ 1434/10/25ه","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/18","year":"1434","subject":"بيع -بيع إبل بثمن آجل -سماع الدعوى غيابيا لعدم حضور املدعى عليه -شهادة الشاهد العدل شرع ا وحلف اليمن -اإللزام بدفع باقي مبلغ املبايعة -الغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/18 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34272302 :‬‬\n                          ‫َر ْق ُم الدعوى‪3469186 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34377010‬تاريخه‪1434/12/3 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬بيــع إبــل بثمــن آجــل ‪ -‬ســماع الدعــوى غيابيــا لعــدم حضــور‬\n      ‫املدعــى عليــه ‪ -‬شــهادة الشــاهد العــدل شــرع ًا وحلــف اليمــن ‪ -‬اإللــزام‬\n             ‫بدفــع باقــي مبلــغ املبايعــة‪ -‬الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n\n      ‫‪ -‬حديــث ابــن عبــاس رضــي اهلل عنهمــا إن النبــي صلــى اهلل عليــه وســلم‬\n                                                ‫قضــى بيمــن وشــاهد رواه مســلم‪.‬‬\n                             ‫‪ -‬املادة ‪ 5/176‬و ‪178‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n      ‫ادعــى املدعــي أنــه بــاع للمدعــى عليــه عــدد ثمــان مــن اإلبــل ذكــر‬\n      ‫قيمتهــا ‪ ،‬علــى أن تســدد بعــد شــهرين ‪ ،‬حــل األجــل ولــم يســدد املدعــى‬\n      ‫عليــه ســوى جــزء مــن املبلــغ ‪ ،‬طلــب املدعــى إلــزام املدعــى عليــه بدفــع‬\n      ‫املبلــغ املتبقــي ‪ ،‬تخلــف املدعــى عليــه عــن احلضــور ‪ ،‬احضــر املدعــي‬\n      ‫شــاهد ًا جــرى تعديلــه وحلــف املدعــي اليمــن تكملــة لبينتــه ‪ ،‬بنــاء علــى‬\n      ‫مــا ســبق مــن الدعــوى ولشــهادة الشــاهد املعــدل شــرعا وحللــف املدعــي‬\n      ‫اليمــن تكملــة لبينتــه وملــا رواه ابــن عبــاس رضــي اهلل عنهمــا أن النبــي‬\n      ‫صلــى اهلل عليــه وســلم قضــى بيمــن وشــاهد رواه مســلم ‪ ،‬صــدر احلكــم‬\n      ‫بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه ‪ ،‬الغائــب علــى حجتــه متــى‬\n                              ‫حضــر ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n‫‪261‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬رئيــس احملكمــة العامــة‬\n‫باملويــه وبنــاء علــى املعاملــة الــواردة لنــا مــن قســم االحــاالت باحملكمــة‬\n‫برقــم ‪ 3469186‬وتاريــخ ‪1434/02/11‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 34348035‬وتاريــخ ‪1434/02/11‬ه ـ ففــي يــوم الثالثــاء‬\n‫املوافــق‪ 1434/02/26‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا‬\n‫حضــر ‪ ..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪..........‬‬\n‫ولــم يحضــر املدعــى عليــه ‪ .............‬ولــم تردنــا افــادة مــن مديــر مركــز‬\n‫شــرطة رضــوان علــى خطابنــا رقــم ‪ 34/64‬يف ‪1434 /1/21‬ه ـ بشــأن‬\n‫تبلــغ املدعــى عليــه مــن عدمــه لــذا قــررت تأجيــل اجللســة إلبــاغ املدعــى‬\n‫عليــه باحلضــور ويف جلســة اخــرى حضــر املدعــي ولــم يحضــر املدعــى‬\n‫عليــه وقــد وردنــا صــورة خطــاب مديــر مركــز شــرطة ‪ ......‬رقــم ‪412‬ع‬\n‫يف‪ 1434/3/10‬ه ـ املوجــه الــى ســعادة مديــر مــرور محافظــة جــدة‬\n‫املتضمــن طلــب ابــاغ منســوبهم املدعــى عليــه حلضــور هــذه اجللســة انتهــى‬\n‫ولــم يردنــا شــيء بخصــوص هــذا اخلطــاب كمــا اطلعــت علــى االقــرار‬\n‫املرفــق بصــورة اخلطــاب املرفــق بعاليــه والصــادر مــن عمــدة مركــز ‪......‬‬\n‫بتاريــخ ‪1434/3/4‬ه ـ املتضمــن ان املدعــى عليــه يعمــل مبــرور محافظــة‬\n‫جــدة انتهــى وبســؤال املدعــي عــن مــا ورد يف اقــرار العمــدة اجــاب انــه‬\n‫غيــر صحيــح وان املدعــى عليــه ليــس موظفـ ًا مدنيـ ًا وال عســكري ًا وانــه‬\n‫يســكن يف رضــوان هكــذا اجــاب ومبــا ان العمــدة مخــول نظامـ ًا مبثــل‬\n‫هــذه االفــادات فقــد قــررت انتظــار جــواب مديــر مــرور جــدة للتحقــق مــن‬\n‫ذلــك وقــررت رفــع اجللســة إلبــاغ املدعــى عليــه للمــرة الثالثــة ويف جلســة‬\n\n                                                                                      ‫‪262‬‬\n\f      ‫اخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه ولــم يردنــا شــيء علــى‬\n      ‫خطابنــا املوجــه ملديــر مــرور محافظــة جــدة لتبليــغ املدعــى عليــه مبوعــد‬\n      ‫هــذه اجللســة ‪ .............‬وقــد قــرر املدعــي بقولــه ان االســم الصحيــح‬\n      ‫للمدعــى عليــه هــو ‪ .............‬ويســكن يف مركــز ‪ ......‬وليــس موظفــا‬\n      ‫مدنيــا وال عســكريا هكــذا قــرر فبنــاء عليــه قــررت الكتابــة لشــرطة‬\n      ‫رضــوان إلبــاغ املدعــى عليــه بعدمــا صحــح املدعــي اســمه ويف جلســة‬\n      ‫اخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه ولــم يردنــا مــا يفيــد‬\n      ‫تبلغــه مــن عدمــه علــى خطابنــا املوجــه الــى شــرطة ‪ ......‬برقــم ‪34 /153‬‬\n      ‫يف ‪1434/5/7‬ه ـ لــذا قــررت رفــع اجللســة ال بــاغ املدعــى عليــه مــرة‬\n      ‫اخــرى ويف جلســة اخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه وقــد‬\n      ‫وردنــا خطــاب مديــر مركــز شــرطة ‪ ......‬رقــم ‪ 895‬يف ‪1434/6/26‬ه ـ‬\n      ‫بخصــوص تبليــغ املدعــى عليــه حلضــور هذه اجللســة واملتضمــن (نفيدكم‬\n      ‫انــه جــرى البحــث والتحــري طــوال هــذه املــدة مبنطقــة ‪ ......‬ولــم يتــم‬\n      ‫العثــور عليــه كمــا يتضــح مــن احملاضــر املرفقــة) انتهــى وقــد جــرى‬\n      ‫اطالعــي عليهــا فوجدتهــا ســبعة محاضــر كل محضــر يف يــوم مســتقل‬\n      ‫وتوافــق مــا جــاء يف خطــاب مديــر الشــرطة ثــم قــرر املدعــي بقولــه ان‬\n      ‫املدعــى عليــه لديــه علــم بالدعــوى هكــذا قــرر ومبــا أن الفقهــاء نصــوا‬\n      ‫علــى أن الدعــوى تســمع علــى الغائــب واملســتتر مــن بــاب أولــى لــذا قــررت‬\n      ‫ا لقــد‬\n            ‫ســماع الدعــوى غيابيــا يف حــق املدعــى عليــه ثــم ادعــى املدعــي قائـ ً‬\n      ‫بعــت املدعــى عليــه الغائــب عــن مجلــس احلكــم ‪ .......‬يف شــهر ذي القعــدة‬\n      ‫لعام‪1433‬ه ـ ال اذكــر اليــوم بالتحديــد عــدد ثمــان مــن اإلبــل ســبع منهــا‬\n      ‫نيــاق وفحــل واحــد وأوصــاف النيــاق ثــاث منهــا ألوانهــا عفــر واحــدة‬\n      ‫عمرهــا حوالــي ثــاث ســنني وواحــدة فاطــر وواحــدة عمرهــا حوالــي أربع‬\n\n\n‫‪263‬‬\n\f‫ســنني وعليهــا وســمنا نحــن ‪ .............‬وهــو مغــزل علــى الرقبــة مــن اجلهــة‬\n‫اليمنــى ومطرقــن علــى اخلــد األميــن واثنتــان الوانهــن مجاهيــم وعمرهمــا‬\n‫حوالــي ثــاث ســنني وواحــدة لونهــا صفــراء وعمرهــا حوالــي ثــاث ســنني‬\n‫وواحــدة لونهــا ملحــاء وهــي فاطــر وعليهــا وســم مشــعاب يف الرقبــة مــن‬\n‫اجلهــة اليمنــى والبعيــر لونــه عفــر هــذا الــذي اذكــره مــن أوســامهن‬\n‫وأوصافهــن وأنواعهــا كلهــا عربيــة وثمــن الناقــة الواحــدة عشــرة آالف‬\n‫ريــال‪ 10000‬وثمــن البعيــر احــد عشــر ألــف ريــال‪ 11000‬ومجمــوع املبلــغ‬\n‫واحــد وثمانــون ألــف ريــال ‪ 81000‬علــى أن يســددنيها بعــد شــهرين مــن‬\n‫املبايعــة وقــد وصلنــي منــه مبلغــا وقــدره ثالثــة آالف ريــال‪ 3000‬وتبقــى‬\n‫لــي بذمتــه ثمانيــة وســبعون ألــف ريــال‪ 78000‬اطلــب إلزامــه واحلكــم‬\n‫عليــه بتســليمي املبلــغ املتبقــي وقــدره ثمانيــة وســبعون ألــف ريــال‪78000‬‬\n‫وبســؤاله ألديــك بينــة علــى دعــواك فقــال نعــم لدي شــاهدان األول يدعى‬\n‫‪ ............‬والثانــي ‪ .............‬اطلــب إمهالــي إلحضارهمــا وعليــه قــررت رفــع‬\n‫اجللســة إلحضــار املدعــي بينتــه ويف جلســة اخــرى حضــر املدعــي ولــم‬\n‫يحضــر املدعــى عليــه وقــد وردنــا خطــاب مديــر مركــز شــرطة ‪ ......‬رقــم‬\n‫‪ 895‬يف ‪1434/6/26‬ه ـ بخصــوص تبليــغ املدعــى عليــه حلضــور هــذه‬\n‫اجللســة واملتضمــن (نفيدكــم انــه جــرى البحــث والتحــري طــوال هــذه‬\n‫املــدة مبنطقــة رضــوان ولــم يتــم العثــور عليــه كمــا يتضــح مــن احملاضــر‬\n‫املرفقــة) انتهــى وقــد جــرى اطالعــي عليهــا فوجدتهــا ســبعة محاضــر‬\n‫كل محضــر يف يــوم مســتقل وتوافــق مــا جــاء يف خطــاب مديــر الشــرطة‬\n‫ثــم قــرر املدعــي بقولــه ان املدعــى عليــه لديــه علــم بالدعــوى هكــذا قــرر‬\n‫ومبــا أن الفقهــاء نصــوا علــى أن الدعــوى تســمع علــى الغائــب واملســتتر‬\n‫مــن بــاب أولــى لــذا قــررت ســماع الدعــوى غيابيــا يف حــق املدعــى عليــه‬\n\n\n                                                                                        ‫‪264‬‬\n\f      ‫ا لقــد بعــت املدعــى عليــه الغائــب عــن مجلــس‬       ‫ثــم ادعــى املدعــي قائ ـ ً‬\n      ‫احلكــم ‪ ..............‬يف شــهر ذي القعــدة لعام‪1433‬ه ـ ال اذكــر اليــوم‬\n      ‫بالتحديــد عــدد ثمــان مــن اإلبــل ســبع منهــا نيــاق وفحــل واحــد وأوصــاف‬\n      ‫النيــاق ثــاث منهــا ألوانهــا عفــر واحــدة عمرهــا حوالــي ثــاث ســنني‬\n      ‫وواحــدة فاطــر وواحــدة عمرهــا حوالــي أربــع ســنني وعليهــا وســمنا نحــن‬\n      ‫‪ ..........‬وهــو مغــزل علــى الرقبــة مــن اجلهــة اليمنــى ومطرقــن علــى اخلــد‬\n      ‫األميــن واثنتــان الوانهــن مجاهيــم وعمرهمــا حوالــي ثــاث ســنني وواحــدة‬\n      ‫لونهــا صفــراء وعمرهــا حوالــي ثــاث ســنني وواحــدة لونهــا ملحــاء وهــي‬\n      ‫فاطــر وعليهــا وســم مشــعاب يف الرقبــة مــن اجلهــة اليمنــى والبعيــر لونــه‬\n      ‫عفــر هــذا الــذي اذكــره مــن أوســامهن وأوصافهــن وأنواعهــا كلهــا‬\n      ‫عربيــة وثمــن الناقــة الواحــدة عشــرة آالف ريــال‪ 10000‬وثمــن البعيــر‬\n      ‫أحــد عشــر ألــف ريــال‪ 11000‬ومجمــوع املبلــغ واحــد وثمانــون ألــف ريــال‬\n      ‫‪ 81000‬علــى أن يســددنيها بعــد شــهرين مــن املبايعــة وقــد وصلنــي منــه‬\n      ‫مبلغــا وقــدره ثالثــة آالف ريــال‪ 3000‬وتبقــى لــي بذمتــه ثمانيــة وســبعون‬\n      ‫ألــف ريــال‪ 78000‬اطلــب إلزامــه واحلكــم عليــه بتســليمي املبلــغ املتبقــي‬\n      ‫وقــدره ثمانيــة وســبعون ألــف ريــال‪ 78000‬وبســؤاله ألديــك بينــة علــى‬\n      ‫دعــواك فقــال نعــم لــدي شــاهدان األول يدعــى ‪ ...........‬والثانــي‪..............‬‬\n      ‫اطلــب إمهالــي إلحضارهمــا وعليــه قــررت رفــع اجللســة إلحضــار املدعــي‬\n      ‫بينتــه ويف جلســة اخــرى وحضــر املدعــي ولــم يحضــر املدعــى عليــه ولــم‬\n      ‫تردنــا إفــادة علــى تبلغــه مــن عدمــه مــن شــرطة رضــوان وبســؤال املدعــي‬\n      ‫هــل أحضــرت شــهودك فقــال نعــم أحضــرت ‪......‬وأمــا ‪ ......‬فليــس معــه مــا‬\n      ‫يثبــت هويتــه وبالفعــل احضــر‪ .............‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ............‬وبســؤاله عمــا لديــه مــن شــهادة قــال اشــهد هلل‬\n\n\n‫‪265‬‬\n\f‫انــه يف شــهر ذي القعــدة لعــام ‪1433‬ه ـ حضــرت املدعــي وقــد بــاع ســبع‬\n‫نيــاق اثنتــان منهــا الوانهــا مجاهيــم وواحــدة لونهــا صفــراء وفحــل لونــه‬\n‫عفــر والباقــي ال اذكــر ألوانهــن باعهــن علــى ‪ ...............‬مببلــغ وقــدره‬\n‫واحــد وثمانــون ألــف ريــال‪ 81000‬ثمــن الواحــدة مــن النيــاق عشــرة آالف‬\n‫ريــال‪ 10000‬وثمــن البعيــر احــد عشــر ألــف ريال‪11000‬علــى أن يســدده‬\n‫املبلــغ بعــد مــدة قريبــة ال اذكرهــا وبعــد شــهرين مــن املبايعــة ذهبــت مــع‬\n‫املدعــي للمدعــى عليــه لطلــب املبلــغ املتبقــي وقــدره ثمانيــة وســبعني ألــف‬\n‫ريــال‪ 78000‬فوعــد بتســديدها للمدعــي هكــذا شــهد وبطلــب املدعــي‬\n‫تزكيــة شــاهدها حضــر كال مــن ‪ ............‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...........‬و‪ ............‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم‪ .............‬وشــهد كل واحــد مبفــردة قائــا أن الشــاهد عقــاب‬\n‫عــدل ثقــة هكــذا شــهدا فســألت املدعــي هــل أنــت مســتعد باحللــف علــى‬\n‫دعــواك مــع شــاهدك فقــال نعــم بعــد حتذيــري لــه مــن خطــر اليمــن إن‬\n‫كانــت كاذبــة فأصــر فأذنــت لــه فحلــف قائــا واهلل العظيــم لقــد بعــت‬\n‫املدعــى عليــه الغائــب عــن مجلــس احلكــم ‪ .............‬يف شــهر ذي القعــدة‬\n‫لعام‪1433‬ه ـ ال اذكــر اليــوم بالتحديــد عــدد ثمــان مــن اإلبــل ســبع منهــا‬\n‫نيــاق وفحــل واحــد وأوصــاف النيــاق ثــاث منهــا ألوانهــا عفــر واحــدة‬\n‫عمرهــا حوالــي ثــاث ســنني وواحــدة فاطــر وواحــدة عمرهــا حوالــي‬\n‫أربــع ســنني وعليهــا وســمنا نحــن ‪ ..........‬وهــو مغــزل علــى الرقبــة مــن‬\n‫اجلهــة اليمنــى ومطرقــن علــى اخلــد األميــن واثنتــان ألوانهــن مجاهيــم‬\n‫وعمرهمــا حوالــي ثــاث ســنني وواحــدة لونهــا صفــراء وعمرهــا حوالــي‬\n‫ثــاث ســنني وواحــدة لونهــا ملحــاء وهــي فاطــر وعليهــا وســم مشــعاب‬\n‫يف الرقبــة مــن اجلهــة اليمنــى والبعيــر لونــه عفــر وأنواعهــا كلهــا‬\n\n\n                                                                                      ‫‪266‬‬\n\f      ‫عربيــة وثمــن الناقــة الواحــدة عشــرة آالف ريــال‪ 10000‬وثمــن البعيــر‬\n      ‫احــد عشــر ألــف ريــال‪ 11000‬ومجمــوع املبلــغ واحــد وثمانــون ألــف ريــال‬\n      ‫‪ 81000‬علــى أن يســددنيها بعــد شــهرين مــن املبايعــة وقــد وصلنــي منــه‬\n      ‫مبلغــا وقــدره ثالثــة آالف ريــال‪ 3000‬وتبقــى لــي بذمتــه ثمانيــة وســبعون‬\n      ‫ألــف ريــال‪ 78000‬لــم يســددنيها وال شــيء منهــا واهلل العظيــم فبنــاء علــى‬\n      ‫مــا ســبق مــن الدعــوى ولشــهادة الشــاهد املعــدل شــرعا وحللــف املدعــي‬\n      ‫اليمــن تكملــة لبينتــه بعــد إذنــي حتذيــري لــه مــن خطرهــا إن كانــت‬\n      ‫كاذبــة وملــا رواه ابــن عبــاس رضــي اهلل عنهمــا إن النبــي صلــى اهلل عليــه‬\n      ‫وســلم قضــى بيمــن وشــاهد رواه مســلم لذلــك كلــه فقــد حكمــت‬\n      ‫علــى املدعــى عليــه بــأن يســلم للمدعــي املبلــغ املتبقــي مــن املبايعــة وقــدره‬\n      ‫ثمانيــة وســبعون الــف ريــال‪ 78000‬وان الغائــب علــى حجتــه متــى حضــر‬\n      ‫وقــررت تســليم املدعــى عليــه صــورة مــن احلكــم لتقــدمي مــا لديــه مــن‬\n      ‫اعتــراض وان لــه مهلــة ثالثــون يومـ ًا مــن تاريــخ اســتالمه لصــورة احلكــم‬\n      ‫واذا انتهــت هــذه املهلــة ولــم يتقــدم بشــي فيســقط حقــه يف طلــب التمييــز‬\n      ‫ـاء علــى املادتــن السادســة والســبعني‬       ‫ويكتســب احلكــم القطعيــة بنـ ً‬\n      ‫بعــد املائــة والثامنــة والســبعني بعــد املائــة مــن نظــام املرافعــات الشــرعية‬\n      ‫ولوائحــه التنفيذيــة وأغلقــت اجللســة الســاعة التاســعة وصلــى اهلل علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/07/18‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء ‪1434 /10 /7‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة التاســعة والنصــف وقــد وردنــا خطــاب مديــر مركــز‬\n      ‫شــرطة ‪ .........‬رقم ‪ 1239‬يف ‪1434 /9 /1‬هـ ونص احلاجة منه نفيدكم‬\n      ‫بأنــه مت البحــث عــن املذكــور يف قريــة ‪ .........‬ولــم يتــم العثــور عليــه‬\n      ‫وذلــك كمــا يتضــح لكــم مــن صــور احملاضــر املرفقــة وكذلــك صــور‬\n\n\n‫‪267‬‬\n\f‫محضــر عمــدة مركــز رضــوان املرفــق هــذا واليــزال البحــث جــاري عــن‬\n‫املذكــور ويف حــال العثــور عليــه ســوف يتــم تســليمه صــورة مــن احلكــم‬\n‫الصــادر ضــده انتهــى ولتعــذر تبليغــه قــررت بعــث كامــل أوراق املعاملــة‬\n‫حملكمــة االســتئناف مبنطقــة مكــة املكرمــة بــدون الئحــة اعتراضيــة‬\n‫بنــاء علــى الفقــرة اخلامســة مــن املــادة السادســة والســبعني بعــد املائــة مــن‬\n‫نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة وعليــه أغلقــت اجللســة‬\n‫الســاعة العاشــرة وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                  ‫وســلم حــرر ‪1434 /10 /7‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء ‪1434/11/11‬ه ـ افتتحــت‬\n‫اجللســة الســاعة التاســعة وقد عادت املعاملة من فضيلة رئيس محكمة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة املكلــف برقــم ‪342284783‬‬\n‫وتاريــخ ‪1434/10/22‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة‬\n‫الدائــرة احلقوقيــة اخلامســة رقــم ‪ 34339440‬وتاريــخ ‪1434/10/25‬ه ـ‬\n‫ونــص احلاجــة منــه (وبدراســة احلكــم وصــورة ضبطــه تقــرر إعادتهــا‬\n‫لفضيلــة حاكمهــا حيــث ثبــت مــن أوراق املعاملــة أن املدعــى عليــه يعمــل‬\n‫يف مــرور جــده ومــا أجــراه فضيلــة حاكمهــا بخطابــه رقــم ‪34811797‬‬\n‫يف ‪1434/4/2‬ه ـ بعــد إقــرار عمــدة رضــوان بــأن املدعــى عليــه يعمــل‬\n‫يف جــده يف غيــر محلــه ألنــه ال واليــة لــه يف جــده وعليــه إفهــام املدعــي‬\n‫بإقامــة دعــواه يف مقــر عمــل املدعــى عليــه بجــده) انتهــى وعليــه أجيــب‬\n‫أصحــاب الفضيلــة وفقهــم اهلل بــأن األمــر ليــس كمــا ورد يف املالحظــة‬\n‫بــل إن نظــر الدعــوى داخــل يف واليتــي وذلــك ظاهــر مــن ضبــط جلســة‬\n‫يــوم االثنــن ‪1434/5/6‬ه ـ والــذي يتضــح مــن خاللهــا أن اســم املدعــى‬\n‫عليــه املنظــورة ضــده الدعــوى هــو ‪ .............‬ويســكن يف رضــوان‬\n\n\n                                                                                         ‫‪268‬‬\n\f      ‫وليــس موظفــا مدنيــا وال عســكريا وأمــا إفــادة عمــدة مركــز رضــوان‬\n      ‫فكانــت بنــاء علــى أن اســم جــد املدعــى عليــه هــو ‪ .........‬والصحيــح هــو‬\n      ‫‪ ..........‬فوقــع اخللــط بينهمــا يف اســم اجلــد لعــدم بيانــه مــن قبــل املدعــي يف‬\n      ‫صحيفــة دعــواه إال بعــد وقــوع اخللــط يف األســماء وألجــل ذا مضيــت يف‬\n      ‫نظــر الدعــوى وقــررت رفــع املعاملــة حملكمــة االســتئناف وعليــه أغلقــت‬\n      ‫اجللســة الســاعة التاســعة والنصــف وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/11/11‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬رئيــس احملكمــة العامــة باملويه‬\n      ‫ففــي يــوم اخلميــس املوافــق‪ 1435/01/04‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫التاســعة والنصــف وقــد عــادت املعاملــة بخطــاب رئيــس محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة املســاعد برقــم ‪ 342583084‬يف‬\n      ‫‪1434/12/29‬ه ـ وبرفقهــا قــرار قضــاة الدائــرة احلقوقيــة اخلامســة رقــم‬\n      ‫‪ 34377010‬يف ‪1434/12/3‬ه ـ املتضمــن وبدراســة احلكــم وصــورة‬\n      ‫ضبطــه تقــرر املوافقــة علــى احلكــم بعــد اإليضــاح األخيــر والغائــب علــى‬\n      ‫حجتــه إذا حضــر انتهــى وقــررت التهميــش بذلــك علــى ســجله وعليــه‬\n      ‫أغلقــت اجللســة الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1435/01/04‬ه ـ ‪.‬‬\n\n\n\n\n‫‪269‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":261,"source_page_end":269,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4fdd708ce27ed31256fc5ccaaf259e1e13f81d435cd42330c987c783591b3e56","normalized_text_hash":"b24ce9f39224ace63240371c5a120883fba72310b4c1f77be6fdc6c250e0f79c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p261-34272302"},{"id":"1bcb2883-2d56-5236-b688-be68bf66b46e","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -املبايعة على أرض ليس عليها صك شرعي -احلكم ببطان البيع وإرجاع ثمن األرض لعدم تنفيذ الشروط -احلكم ال يفيد التملك وال يغني عن حجة االستحكام .","document_number":"34213467","case_number":"3474551","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/14","year":"1434","subject":"بيع -املبايعة على أرض ليس عليها صك شرعي -احلكم ببطان البيع وإرجاع ثمن األرض لعدم تنفيذ الشروط -احلكم ال يفيد التملك وال يغني عن حجة االستحكام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/14 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34213467 :‬‬\n                    ‫َر ْق ُم الدعوى‪3474551 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34244884‬تاريخه‪1434/6/19 :‬هـ‬\n\n\n‫بيــع ‪ -‬املبايعــة علــى أرض ليــس عليهــا صــك شــرعي ‪ -‬احلكــم ببطــان‬\n‫البيــع وإرجــاع ثمــن األرض لعــدم تنفيــذ الشــروط ‪ -‬احلكــم ال يفيــد‬\n                          ‫التملــك وال يغنــي عــن حجــة االســتحكام ‪.‬‬\n\n\n\n\n‫قولــه صلــى اهلل عليــه وســلم (املســلمون علــى شــروطهم) رواه أحمــد‬\n                                                           ‫وأبــو داوود ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه مبطالبتــه بإبطــال عقــد البيــع وإلزامــه‬\n‫بإعــادة مــا اســتلمه مــن املدعــي وقــدره ســبعة وثالثــون ألف ـ ًا وخمســمائة‬\n‫ريــال لكونــه لــم ينفــذ الشــرط وبــاع مــا ال ميلــك ‪ ،‬حيــث اشــترى‬\n‫املدعــي مــن املدعــى عليــه قطعــة أرض بيضــاء معقمــة ليــس عليهــا صــك‬\n‫شــرعي واشــترط عليــه بــأن يتعهــد بحمايتــه مــن أي منازعــات مــن قبــل‬\n‫املواطنــن‪ ،‬التــزم املدعــى عليــه بهــذا الشــرط لكنــه لــم ينفــذه حيــث‬\n‫قــام أحــد املواطنــن بشــكاية املدعــي واعتراضــه علــى التملــك ولــم يقــم‬\n‫املدعــى عليــه بحمايتــه ‪ ،‬صــادق املدعــى عليــه علــى البيــع وعلــى الشــرط‬\n‫وعلــى عــدم وجــود صــك شــرعي عليهــا وعلــى اعتــراض أحــد املواطنــن‬\n‫للمدعــي وأنــه ليــس داخــل يف الشــرط ألن اعتراضــه للمصلحــة العامــة‬\n\n                                                                                    ‫‪270‬‬\n\f      ‫وليــس للتملــك ‪ ،‬أبــرز املدعــي عقــد املبايعــة وقــد نــص علــى تعهــد املدعى‬\n      ‫عليــه علــى حمايتــه مــن أي منازعات وعلى أن للمدعي التصرف بكامل‬\n      ‫األرض املباعــة ‪ ،‬صــادق املدعــى عليــه علــى العقــد ‪ ،‬وحيــث نــص عقــد‬\n      ‫املبايعــة أعــاه علــى تعهــد الطــرف األول بحمايــة الطــرف الثانــي مــن‬\n      ‫أي منازعــات مــن قبــل املواطنــن وحيــث اعتــرف املدعــى عليــه بأنــه لــم‬\n      ‫يســتطع حمايــة املدعــي مــن منازعــة أحــد املواطنــن وهــو مــن ســكان‬\n      ‫نفــس القريــة حســب جــواب املدعــى عليــه وحيــث إن عقــد املبايعــة لــم‬\n      ‫يرصــد فيــه ذكــر لطريــق يشــق األرض املباعــة نصفــن بــل نــص العقــد‬\n      ‫علــى أن للمشــتري التصــرف الكامــل بــاألرض املباعــة باإلحيــاء دون‬\n      ‫أي شــروط أو قيــود مــن ســكان القريــة ا‪.‬ه ـ ولقولــه صلــى اهلل عليــه‬\n      ‫وســلم (املســلمون علــى شــروطهم) وحيــث لــم يلتــزم املدعــى عليــه بتنفيــذ‬\n      ‫هــذا الشــرط ‪ ،‬احلكــم ببطــان عقــد البيــع أعــاه وإلــزام املدعــى عليــه‬\n      ‫بإرجــاع ثمــن األرض إلــى املدعــي حــا ًال ‪ ،‬قنــع املدعــي باحلكــم واعتــرض‬\n      ‫املدعــى عليــه بالئحــة ‪ ،‬جــرى إفهــام الطرفــن بــأن هــذا احلكــم ال يفيــد‬\n      ‫التملــك وال يغنــي عــن حجــة االســتحكام ‪ ،‬صــدق احلكــم مــن الدائــرة‬\n          ‫احلقوقيــة الســابعة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n      ‫باملدينة املنورة وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n      ‫العامــة باملدينــة املنــورة برقــم ‪ 3474551‬وتاريــخ ‪1434/02/13‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34374318‬وتاريــخ ‪ 1434/02/13‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافــق‪ 1434/05/14‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 15‬‬\n\n‫‪271‬‬\n\f‫وفيهــا حضــر ‪ ........‬ســعودي بالســجل املدنــي ‪ ........‬وادعــى علــى احلاضــر‬\n‫ا يف دعــواه ‪ :‬إنــه بتاريــخ‬\n                            ‫معــه ‪ ........‬ســعودي بالســجل املدنــي ‪ ........‬قائـ ً‬\n‫‪1433/1/26‬ه ـ اشــتريت قطعــة أرض بيضــاء معقمــة وليــس عليهــا صــك‬\n‫شــرعي مــن املدعــى عليــه هــذا احلاضــر‪ ........‬وتقــع يف قريــة ‪ ........‬حــي‬\n‫‪ ........‬ويحدهــا شــما ًال طريــق ‪ ........‬ثــم مســجد ‪ ...‬واســتراحة ‪........‬‬\n‫وروضــة ‪ ........‬وجنوبـ ًا طريــق ‪ ........‬وأرض ‪ ........‬وشــرق ًا مجــرى الســيل‬\n‫‪ ........‬وأرض ‪ ........‬وغربـ ًا الطريــق الواصــل بــن طريقــي ‪ ........‬ثــم أرض‬\n‫أبنــاء ‪ .....‬مببلــغ مقــداره ســبعة وثالثــون ألف ـ ًا وخمســمائة( ‪)37500‬‬\n‫ريــال اســتلمها املدعــى عليــه عــد ًا ونقــد ًا واشــترطت عليــه أن يتعهــد‬\n‫بحمايتــي مــن أي منازعــات مــن قبــل املواطنــن والتــزم لــي بهــذا الشــرط‬\n‫ولكنــه لــم ينفــذه حيــث تقــدم املواطــن ‪ ........‬بشــكايتي واعتراضــي‬\n‫علــى متلكــي لهــذه األرض وأزيلــت حدودهــا ومعاملهــا وعقومهــا مــن قبــل‬\n‫ـاء علــى شــكوى املواطــن املذكــور ولــم يقــم املدعــى‬   ‫مركــز إمــارة ‪ ....‬بنـ ً‬\n‫عليــه بحمايتــي مــن املواطــن املذكــور بــل ملــا طلبــت منــه املســاعدة قــال‬\n‫لــي ‪:‬تســتاهل وهــو قــد تعهــد لــي بحمايتــي مــن أي منازعــات مــن قبــل‬\n‫املواطنــن وأطلــب إلزامــه باســترجاع مادفعتــه إليــه وهــو مبلــغ مقــداره‬\n‫ســبعة وثالثــون ألف ـ ًا وخمســمائة (‪ )37500‬ريــال وإبطــال عقــد املبايعــة‬\n‫هــذا لكونــه لــم ينفــذ الشــرط ولكونــه بــاع مــا ال ميلــك حيــث ملــا أبــرزت‬\n‫عقــد املبايعــة أمــام رئيــس مركــز ‪ ....‬أجابنــي بــأن عقــد املبايعــة هــذا‬\n‫ال يفيــد التملــك وال ينفعــك بشــيء هــذه دعــواي‪ .‬وبســؤال املدعــى عليــه‬\n‫ا ‪ :‬ماذكــره املدعــي يف دعــواه غيــر صحيــح والصحيــح أنــه‬           ‫أجــاب قائـ ً‬\n‫بتاريــخ ‪1433/1/26‬ه ـ بعــت علــى املدعــي أرض معقمــة وليــس عليهــا‬\n‫صــك شــرعي وتقــع يف قريــة ‪ ........‬حــي ‪ ........‬طريــق ‪ .......‬حســب‬\n\n\n                                                                                        ‫‪272‬‬\n\f      ‫حدودهــا التــي ذكرهــا املدعــي مببلــغ ســبعة وثالثــون ألفـ ًا وخمســمائة‬\n      ‫(‪ )37500‬ريــال اســتلمتها كاملــة وتعهــدت لــه بحمايتــه مــن أي‬\n      ‫منازعــات مــن املواطنــن الطماعــن ولكــن املواطــن ‪ ........‬لــم يدعــي‬\n      ‫متلكهــا ولكنــه تقــدم لالعتــراض للمصلحــة العامــة وهــذا غيــر داخــل‬\n      ‫يف الشــرط حيــث أن الشــرط ينــص علــى املواطنــن الطامعــن فقــط‬\n      ‫دون املعترضــن للمصلحــة العامــة ثــم أبــرز املدعــي عقــد مبايعــة األرض‬\n      ‫وهــذا نصــه (احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد لقــد‬\n      ‫مت االتفــاق بــن كل مــن ‪( ........ :‬طــرف أول) ‪( ........‬طــرف ثانــي)‬\n      ‫حيــث قــام الطــرف األول ببيــع األرض الواقعــة يف قريــة ‪ ........‬حــي ‪.....‬‬\n      ‫والتــي يحدهــا مــن جهــة الشــمال ‪ ........‬واســتراحة ‪ ........‬وروضــة ‪........‬‬\n      ‫ا بــن األرض املباعــة وحدودهــا مــن‬     ‫حيــث يقــع طريــق ‪ ........‬حــد ًا فاصـ ً‬\n      ‫الشــمال ومــن جهــة الشــرق يحدهــا مجــرى الســيل ‪ ........‬وأرض ‪........‬‬\n      ‫ومــن جهــة اجلنــوب يحدهــا طريــق الرحبــة وأرض ‪ ........‬ويحدهــا مــن‬\n      ‫جهــة الغــرب أرض أبنــاء ‪ ........‬حيــث يفصــل بينهمــا الطريــق الواصــل‬\n      ‫بــن طريقــي ‪ ........‬و‪ ........‬مببلــغ قــدره ‪( 37500‬ســبعة وثالثــون ألف ـ ًا‬\n      ‫وخمــس مئــة ريــال ســعودي) وتعهــد الطــرف األول بحماية الطــرف الثاني‬\n      ‫مــن أي منازعــات مــن قبــل املواطنــن كمــا أن الطــرف الثانــي لــه احلق يف‬\n      ‫التصــرف الكامــل بــاألرض املباعــة بالبيــع أو اإلحياء دون أي شــروط أو‬\n      ‫قيــود مــن ســكان القريــة ‪ .‬واهلل املوفــق ‪ ) ...‬انتهــى وبعرضــه على املدعى‬\n      ‫ا ‪ :‬لــم أســتطع‬  ‫عليــه صــادق عليــه حرفـ ًا بحــرف وقــرر املدعــى عليــه قائـ ً‬\n      ‫مســاعدة وحمايــة املدعــي مــن منازعــة املواطــن ‪ ........‬وهــو مــن ســكان‬\n      ‫نفــس القريــة لكــون منازعــة املواطــن املذكــور وشــكواه للمصلحــة‬\n      ‫العامــة وليســت للمصلحــة اخلاصــة حيــث أن املواطــن‪ ........‬يطالــب بفتــح‬\n\n\n‫‪273‬‬\n\f‫الطريــق الــذي يشــق األرض املباعــة نصفــن حيــث قــام املدعــي بإغالقــه‬\n‫هــذا جوابــي وبعرضــه علــى املدعــي أجــاب قائـاً‪ :‬األرض التــي اشــتريتها‬\n‫ال يشــقها أي طريــق وهــذا مــا نــص عليــه عقــد املبايعــة هــذا جوابــي ثــم‬\n‫باطالعــي أنــا حاكــم القضيــة علــى عقــد املبايعــة املذكــور تبــن أنــه‬\n‫لــم يرصــد فيــه ذكــر لطريــق يشــق األرض املباعــة نصفــن انتهــى ثــم‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬‫إنــه وبعــد التأمــل يف القضيــة وبنـ ً‬\n‫وحيــث نــص عقــد املبايعــة أعــاه علــى تعهــد الطــرف األول بحمايــة‬\n‫الطــرف الثانــي مــن أي منازعــات مــن قبــل املواطنــن وحيــث اعتــرف‬\n‫املدعــى عليــه بأنــه لــم يســتطع حمايــة املدعــي مــن منازعــة املواطــن ‪........‬‬\n‫وهــو مــن ســكان نفــس القريــة حســب جــواب املدعــى عليــه وحيــث أن‬\n‫عقــد املبايعــة لــم يرصــد فيــه ذكــر لطريــق يشــق األرض املباعــة نصفــن‬\n‫بــل نــص العقــد علــى أن للمشــتري التصــرف الكامــل بــاألرض املباعــة‬\n‫باإلحيــاء دون أي شــروط أو قيــود مــن ســكان القريــة اه ـ ولقولــه صلــى‬\n‫اهلل عليــه وســلم (املســلمون علــى شــروطهم) رواه اإلمــام أحمــد وأبــو‬\n‫داود وحيــث لــم يلتــزم املدعــى عليــه بتنفيــذ هــذا الشــرط لذلــك فقــد‬\n‫حكمــت ببطــان عقــد البيــع أعــاه وألزمــت املدعــى عليــه بإرجــاع ثمــن‬\n‫األرض وذلــك بتســليم ســبعة وثالثــن ألف ـ ًا وخمســمائة (‪)37500‬ريــال‬\n‫إلــى املدعــي حــا ًال وقنــع املدعــي باحلكــم ولــم يقنــع املدعــى عليــه وطلــب‬\n‫محكمــة االســتئناف مبوجــب الئحــة اعتراضيــة وأجيــب لطلبــه وأفهــم‬\n‫بــأن لــه مهلــة ثالثــن يومـ ًا لتقــدمي الالئحــة االعتراضيــة ففهــم ذلــك كمــا‬\n‫افهمــت الطرفــن بــأن هــذا احلكــم اليفيــد التملــك واليصلــح لالحتجــاج‬\n‫بــه يف هــذا واليغنــي عــن حجــة االســتحكام وإمنــا هــو لرفــع النــزاع ففهما‬\n     ‫ذلــك وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/5/14‬هــ‪.‬‬\n\n\n                                                                                         ‫‪274‬‬\n\f      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باملدينــة املنــورة املســاعد برقــم ‪34/374318‬‬\n      ‫وتاريــخ ‪1434/06/10‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫‪ ........‬باحملكمــة العامــة باملدينــة املنــورة املســجل برقــم ‪ ........‬وتاريــخ‬\n      ‫‪1434/05/14‬ه ـ املتضمــن دعــوى ‪ ........‬ضــد ‪ ........‬وبدراســة الصــك‬\n      ‫وص ــورة ضبط ــه والئحتــه اإلعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم‬\n             ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪275‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":270,"source_page_end":275,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f9c92817cb56b5d18f7090929e99d8b0bba4a7b09d1b03794d65b0a2eb82daf3","normalized_text_hash":"f504da947b3d9a5106e83c3a45d166a28e6b444ded5c3d8b12ce4eb549e2873d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p270-34213467"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"7cd24718-9020-50ba-aa70-23a736039897","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع عقار -بيع قطعة أرض بعقد -إفراغ قطعة أرض أخرى مبخطط آخر -الداللة ومقابلها -املطالبة بفسخ العقد وإعادة ثمن األرض وأجرة الداللة -عدم صحة البيع لالختاف بن املعقود عليه والواقع -احلكم بفسخ العقد وإعادة الثمن وأجرة الداللة ورفض","document_number":"34186372","case_number":"3436313","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/13","year":"1434","subject":"بيع عقار -بيع قطعة أرض بعقد -إفراغ قطعة أرض أخرى مبخطط آخر -الداللة ومقابلها -املطالبة بفسخ العقد وإعادة ثمن األرض وأجرة الداللة -عدم صحة البيع لالختاف بن املعقود عليه والواقع -احلكم بفسخ العقد وإعادة الثمن وأجرة الداللة ورفض","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/4/13 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34186372 :‬‬\n                          ‫َر ْق ُم الدعوى‪3436313 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34277873‬تاريخه‪1434/7/24 :‬هـ‬\n\n\n      ‫بيع عقار ‪ -‬بيع قطعة أرض بعقد ‪ -‬إفراغ قطعة أرض أخرى مبخطط‬\n      ‫آخــر ‪ -‬الداللــة ومقابلهــا ‪ -‬املطالبــة بفســخ العقــد وإعــادة ثمــن األرض‬\n      ‫وأجــرة الداللــة ‪ -‬عــدم صحــة البيــع لالختــاف بــن املعقــود عليــه‬\n      ‫والواقــع ‪ -‬احلكــم بفســخ العقــد وإعــادة الثمــن وأجــرة الداللــة ورفــض‬\n                                                                  ‫مــا عــدا ذلــك ‪.‬‬\n\n\n\n\n                        ‫ما ذكره القاضي من مبادئ وقواعد يف تسبيب حكمه ‪.‬‬\n\n\n\n\n      ‫قــام املدعــي بشــراء قطعــة أرض مقابــل ثمــن معــن‪ ،‬كمــا قــام بتســليم‬\n      ‫مبلــغ مــن املــال ملــن د ّلــه علــى هــذه القطعــة‪ ،‬وقد وافــق على القيــام بإفراغ‬\n      ‫قطعــة أرض أخــرى مبخطــط آخــر بنفــس مســاحة القطعــة األولــى‪،‬‬\n      ‫وعنــد البنــاء وبعــد شــهر مــن اإلفــراغ تبــن أن األرض املفرغــة غيــر التــي‬\n      ‫وقــع عليهــا العقــد األمــر الــذي يســتوجب احلكــم بفســخ العقــد وإلــزام‬\n      ‫املدعــى عليــه بإعــادة املبلــغ الــذي تســلمه قيمــة األرض وكذلــك أربــاح‬\n                                                       ‫هــذا املبلــغ هكــذا ادعــى ‪.‬‬\n      ‫رفــض مــوكل املدعــى عليــه‪ ،‬رد ثمــن األرض‪ ،‬أقــر الــدالل (الوســيط)‬\n      ‫بداللتــه وقبضــه ثمــن ذلــك واســتعداده لــرد املبلــغ حــن ثبــوت اإلفــراغ‪،‬‬\n\n‫‪209‬‬\n\f‫مــن كل مــا تقــدم وقيــام املدعــى عليــه وكالــة باملصادقــة علــى مــا قــرره‬\n‫املدعــي‪ ،‬وجــود شــيك بالديــون وســند للقبــض‪ ،‬وقــوع البيــع علــى مــا‬\n‫تراضــى عليــه الطرفــان مــن العــن والثمــن‪ ،‬عــدم رضــاء املدعــي بــاألرض‬\n‫املفرغــة‪ ،‬عــدم ملكيــة املدعــى عليــه لــأرض املفرغــة التــي وقــع عليهــا‬\n‫البيــع ومــن ثــم عــدم صحــة البيــع‪ ،‬وألن امللــك ال يعنــي تصحيــح العقــد‬\n‫أو إفســاده‪ ،‬وأن مــال املســلم ال يحــل إال بطيــب نفــس منــه‪ ،‬حكمــت‬\n‫احملكمــة ‪ -1‬إلــزام املدعــى عليــه بــرد مبلــغ األرض ‪ -2‬رد املدعــى‬\n‫عليهمــا مبلــغ الداللــة ‪ -3‬رد دعــوى املدعــي باملطالبــة بأربــاح املبلــغ الــذي‬\n‫ســلمه‪ .‬ومبــا ســبق حكمــت احملكمــة وأفهــم القاضــي املدعــى عليــه‬\n‫وكالــة أن ملوكلــه ‪ ...............‬ميــن املدعــي أنــه لــم يــرض بــاألرض محــل‬\n‫اإلفــراغ ‪ -‬قنــع املدعــي باحلكــم ولــم يقنــع املدعــى عليــه ‪ -‬صــدق احلكــم‬\n                                                     ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبكــة املكرمــة برقــم ‪ 3436313‬وتاريــخ‬\n‫‪ 1434/01/20‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34176550‬وتاريــخ‬\n‫‪ 1434/01/20‬ه ـ حضــر منصــور ‪ ..........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪ ...........‬وحضــر حلضــوره ‪ .........‬ســعودي بالســجل‬\n‫املدنــي رقــم ‪ ..........‬و ‪ .......‬ســعودي بالســجل املدنــي رقــم ‪ .........‬و ‪...........‬‬\n‫ســعودي بالســجل املدنــي رقــم ‪ ..........‬بصفتــه وكيــا عــن ‪...........‬‬\n‫ســعودي بالســجل املدنــي رقــم ‪ ................‬مبوجــب الوكالــة الصــادرة‬\n\n                                                                                              ‫‪210‬‬\n\f      ‫مــن كتابــة العــدل الثانيــة مبكــة برقــم ‪ 34339717‬يف ‪1434/3/18‬ه ـ‬\n      ‫والتــي تخولــه حــق املرافعــة واملدافعــة واإلقــرار واإلنــكار والصلــح‬\n      ‫واجلــرح والتعديــل إلــخ وادعــى األول قائــا إننــي اشــتريت مــن ‪............‬‬\n      ‫قطعــة أرض بــأم الكتــاد خلــف االســكان مبكــة ورقــم القطعــة ‪....‬‬\n      ‫مســاحتها ‪750‬م‪ 2‬بثمــن قــدره مليــون وأربعمائــة ألــف ريــال كمــا ســلمت‬\n      ‫أربعــن ألــف ريــال داللــة ملــن دلنــي علــى األرض وهــم ‪..........‬و‪ ............‬ثــم‬\n      ‫أنــه أفــرغ لــي أرضــا أخــرى مبخطــط الهــدى خلــف مخطــط أم الكتــاد‬\n      ‫أرضــا رقــم القطعــة ‪ ...‬بنفــس املســاحة املذكــورة للقطعــة األولــى علــى‬\n      ‫أنهــا هــي وغلطــة منــي وافقــت علــى هــذا االفــراغ ووقعــت عليــه فلمــا‬\n      ‫أردت البنــاء بعــد شــهر تقريبــا مــن االفــراغ تبــن أن األرض املفرغــة‬\n      ‫غيــر التــي وقــع عليهــا العقــد بينــي وبــن املدعــى عليــه البائــع لــذا أطلــب‬\n      ‫احلكــم بفســخ العقــد لوقوعــه علــى غيــر األرض املتفــق عليهــا وإلــزام‬\n      ‫املدعــى عليــه بإعــادة املبلــغ الــذي ســلمته وقــدره مليــون وأربعمائــة ألــف‬\n      ‫ريــال واحلكــم علــى مــن أخــذ الداللــة وقدرهــا أربعــون ألــف ريــال وهــم‬\n      ‫‪...........‬و‪ ............‬مــع احلكــم بأربــاح املبلــغ الــذي اســتلمه مــن غيــر وجــه‬\n      ‫حــق وأســاله اجلــواب هــذه دعــواي وبعرضهــا علــى املدعــى عليــه قــال مــا‬\n      ‫ذكــره املدعــي أن موكلــي باعــه قطعــة األرض رقــم ‪ ...‬مــن مخطــط أم‬\n      ‫الكتاد مبكة صحيح وصحيح أن األرض املفرغة برقم ‪ ...‬من مخطط‬\n      ‫الهــدى وهــو خلــف مخطــط أم الكتــاد لكــن موكلــي قــد عــرض علــى‬\n      ‫املدعــي صــورة صــك األرض واطلــع عليهــا ووافــق علــى الشــراء وصحيــح‬\n      ‫أن ثمــن األرض مليــون وأربعمائــة ألــف ريــال كمــا أن املعتــاد أن كاتــب‬\n      ‫العــدل يســأله هــل وقفــت علــى األرض هــل اطلعــت عليهــا لــذا فهــو علــى‬\n      ‫علــم واطــاع بــاألرض املبيعــه وعليــه فــا يوافــق موكلــي علــى رد ثمــن‬\n\n\n‫‪211‬‬\n\f‫األرض املذكــورة هكــذا أجــاب كمــا حضــر ‪...............‬وقــرر بقولــه‬\n‫أننــي أنــا الــذي دللــت املدعــي علــى األرض رقــم ‪ 919‬بــأم الكتــاد ال‬\n‫مبخطــط الهــدى ووقفتــه عليهــا وقــد توافــق املخططــان يف املســاحة‬\n‫والشــوارع ورقــم القطعــة ثــم أننــي علمــت بعــد ذلــك أن الــذي أفــرغ لــه‬\n‫هــو أرض مخطــط الهــدى وقــد اســتلمت منــه أجــرة الداللــة عشــرين‬\n‫ألــف ريــال كمــا اســتلم ‪ .............‬مثلهــا وال مانــع لــدي مــن إعــادة الداللــة‬\n‫التــي اســتلمت هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه ‪..............‬‬\n‫قــال إننــي أملــك شــركة ‪ .............‬للســيارات وقــد تعامــل معنــا ‪.......‬‬\n‫واســتلم منــا قرضــا مــن خمســة أشــخاص ممــن يتعامــل مــع الشــركة‬\n‫ورهننــا أرضــا وســلمنا صكهــا وأفرغهــا لنــا علــى صفــة ضمــان للتمويــل‬\n‫والقــرض ثــم اتصــل بنــا بعــد ذلــك وطلــب منــا بيعهــا فعرضناهــا وطلبــت‬\n‫مبليــون وثالثمائــة ألــف ريــال ثــم عرضتهــا علــى ‪ ............‬أن يبحــث عــن‬\n‫مشــتر آخــر فأتــى بهــذا احلاضــر وطلبهــا مبليــون وأربعمائــة ألــف ريــال‬\n‫فبعانــا أيــاه ســلمنا مليونــا وســلم للمالــك األصلــي أربعمائــة ألــف ريــال‬\n‫كمــا ســلمني أنــا و ‪ ...............‬أربعــن ألــف ريــال تناصفناهــا بيننــا وال‬\n‫أدري عمــا يذكــره أن البيــع وقــع علــى أرض أم الكتــاد واإلفــراغ علــى‬\n‫أرض الهــدى بــل تعاملــي كان مــع الــدالل ‪...............‬والــذي أعلمــه أن‬\n‫املدعــي اطلــع علــى األرض وصكهــا وهــو مــن أهــل اخلبــرة بالعقــار‬\n‫والتعامــل فيــه لــذا فــا حــق لــه يف إعــادة األرض لكــن أن حكــم علــي‬\n‫بإعــادة مبلــغ الداللــة فــا مانــع لــدي هكــذا أجــاب وبعــرض ذلــك علــى‬\n‫املدعــي قــال إننــي لــم أطلــع علــى صــورة الصــك وليــس بهــا علــم ولــم يقــل‬\n‫لــي كاتــب العــدل هــل وقفــت علــى األرض أوال بــل قــال لــه الوكيــل‬\n‫ياشــيخ األرض بــأم الكتــاد األرض بــأم الكتــاد فقــال لــي كاتــب‬\n\n\n                                                                                           ‫‪212‬‬\n\f            ‫العــدل هــل هــو كمــا يقــول فقلــت نعــم بــأم الكتــاد هكــذا قــال‬\n      ‫ثــم ســالت املدعــى عليــه وكالــة هــل لديــه بينــه علــى مــا يذكــره أن‬\n      ‫املدعــي علــم ال حقــا أن األرض بالهــدى فقــال ليــس لــدي بينــه ســوى‬\n      ‫صــك العقــار فأبــرز املدعــي صــك العقــار فوجدتــه برقــم ‪1/229/371‬‬\n      ‫يف ‪1415/8/24‬ه ـ صــادرا مــن كاتــب عــدل مكــة بــأن مــن اجلــاري يف‬\n      ‫ملــك ‪ .............‬القطعــة رقــم ‪ 919‬الواقعــة باملخطــط رقــم ‪ 12/29/1‬يف‬\n      ‫الهــدى احملــدوده شــماال بالقطعــة رقــم ‪ 916‬وجنوبــا القطعــة رقــم ‪920‬‬\n      ‫وشــرقا القطعــة رقــم ‪ 918‬وغربــا شــارع ‪25‬م مســاحتها ‪75‬م ثــم همــش‬\n      ‫عليهــا بانتقالهــا إلــى ملــك ‪ ...........‬مبائــة ألــف ريــال ثــم أبــرز الصــك‬\n      ‫رقــم ‪ 720109000436‬يف ‪1433/11/27‬ه ـ الصــادر مــن كاتــب عــدل‬\n      ‫مكــة بــأن األرض املذكــورة بيعــت للمدعــي مبليــون وأربعمائــة ألــف‬\n      ‫ريــال ( ‪ ) 1400.000‬وبعرضــه علــى املدعــي قــال الصحيــح مــا ذكــرت‬\n      ‫أوال وليــس لــدي علــم بذلــك وأن صــك العقــار فهــو كمــا ذكــرت لــم‬\n      ‫اعلــم عنــه حتــى أفــرغ ومضــى شــهرا وأكثــر وعلمــت ذلــك بعــد أن أردت‬\n      ‫البنــاء ويــدل علــى ذلــك الشــيك العربــون الــذي ســلمته وســند القبــض ثــم‬\n      ‫أبــرز الشــيك رقــم ‪ 306‬يف ‪1433/11/10‬ه ـ واملســحوب مــن حســابي‬\n      ‫‪ ............‬علــى مصــرف ‪ ......‬فــرع أم القــرى عربــون قطعــة األرض برقــم‬\n      ‫‪ 919‬بــأم الكتــاد كمــا أبــرز كربــون ســند القبــض رقــم ‪ 244‬علــى‬\n      ‫مطبوعــات ‪ ..............‬أنــه اســتلم مائــة ألــف ريــال بالشــيك املذكــور‬\n      ‫بعاليــه عربــون أرض أم الكتــاد وبعرضــه علــى املدعــى عليــه قــال لــم‬\n      ‫يســتلم موكلــي الشــيك والســند مــن مكتــب ‪ ..............‬للداللــة وبعرضــه‬\n      ‫علــى احلاضــر ‪ .............‬فقــال إننــي الــذي اســتلمت الشــيك املذكــور‬\n      ‫وســلمت للمدعــي ســند بالقبــض وعرضــت الشــيك علــى ‪ .............‬ووافــق‬\n\n\n‫‪213‬‬\n\f‫عليــه هكــذا قــال ويف جلســة أخــرى حضــر الطرفــان وحضــر وكيــل‬\n‫املدعــى عليــه ‪..............‬وهــو‪ ...........‬وكيــا عــن‪ .................‬بالوكالــة‬\n‫رقــم ‪ 32787‬يف‪1432/11/17‬ه ـ الصــادرة مــن كتابــة عــدل مكــة‬\n‫الثانيــة وتخولــه املرافعــة واملدافعــة واإلقــرار واإلنــكار والصلــح والتنازل‬\n‫إلــخ وبعــد النظــر يف الدعــوى واإلجابــة ومــا قــرره املدعــي أنــه اشــترى‬\n‫القطعــة رقــم ‪ 919‬مبخطــط أم الكتــاد وأن األرض املفرغــة لــه بالرقــم‬\n‫نفســه مبخطــط الهــدى وتأسيســا علــى تصديــق املدعــى عليــه وكالــة‬\n‫علــى ذلــك ومــا قــرره احلاضــر ‪ ...............‬أن وقوفــه مــع املدعــي كان علــى‬\n‫أرض أم الكتــاد ال أرض الهــدى ونظــرا ملــا ورد يف شــيك العربــون وســند‬\n‫القبــض وفيــه أن األرض بــأم الكتــاد وتأسيســا علــى مــا تقــرر شــرعا‬\n‫أن البيــع إمنــا يقــع علــى مــا تراضــى عليــه الطرفــان مــن العــن والثمــن‬\n‫وغيــر ذلــك وألن املدعــي لــم يــرض بــاألرض املفرغــة لــه حســب دعــواه‬\n‫وألن املدعــى عليــه ال ميلــك أرض أم الكتــاد والتــي وقــع عليهــا البيــع بــن‬\n‫الطرفــن فبيعــه لهــا غيــر صحيــح وال معتبــر شــرعا فأمــا االفــراغ فأنــه‬\n‫توثيــق للبيــع وامللــك وال يعنــي تصحيــح العقــد أو افســاده وألن مــال املســلم‬\n‫ال يحــل إال بطيــب نفــس منــه ولــم يــرض املدعــي بتســليم مالــه عوضــا‬\n‫عــن أرض حــي الهــدى فأمــا مــا ذكــره املدعــى عليــه أن املدعــي رضــي‬\n‫بــاألرض حــن اإلفــراغ فقــد نفــاه املدعــي ولــم يقــم عليــه املدعــى عليــه‬\n‫بينــه فأمــا احتجــاج املدعــي باإلفــراغ نفســه علــى رضــى املدعــى عليــه‬\n‫فليــس بوجيــه ألن مــا ذكــره املدعــي مــن وقــوع اللبــس كمــا فصلــه‬\n‫يف إجابتــه عــن ذلــك ممــا هــو ســائغ وممــا يقــع عــاده لكــن ملــا يكــن‬\n‫للمدعــى عليــه بينــة علــى رضــى املدعــي بــاألرض املفرغــة بعــد اإلفــراغ‬\n‫فــإن لــه ميينــه علــى نفــي ذلــك وبعرضــه علــى املدعــى عليــه وكالــة قــال ال‬\n\n\n                                                                                         ‫‪214‬‬\n\f      ‫أرغــب يف ميــن املدعــي علــى نفــي مــا ذكــر هكــذا قــرر وأمــا احلاضــران‬\n      ‫املدعــى عليهمــا بالداللــة ‪..........‬و‪...........‬فقــد أقــرا باســتالمهما أجــرة‬\n      ‫الداللــة وملــا كانــت الداللــة بهــذه املثابــة غيــر صحيحــة ألنهمــا داله‬\n      ‫علــى غيــر األرض التــي ميلكهــا املدعــى عليــه وعليــه فــا يســتحقان تلــك‬\n                                      ‫األجــرة ويلزمهمــا شــرعا ردهــا إلــى املدعــي‬\n      ‫فأمــا مــا طلبــه املدعــي مــن احلكــم لــه باألربــاح عــن ثمــن األرض للمــدة‬\n      ‫التــي مــن حــن التســليم إلــى اآلن فهــو طلــب ال وجــه لــه ألن املدعــى عليــه‬\n      ‫اســتلم املــال علــى أنــه ضامــن لــه فهــو إن هلــك املــال ضامــن لهالكــه ولــه‬\n      ‫زيادتــه لــو زاد وقــد تقــرر شــرعا أن الغنــم بالغــرم فــإذا كان املدعــي لــو‬\n      ‫تلــف املــال أو ضــاع أو نحــو ذلــك لــم يضمنــه فــا يحــق لــه طلــب أرباحــه‬\n      ‫وأيضــا فــإن األمــر الواقــع بــن الطرفــن يظهــر منــه الغلــط و اخلطــأ وال‬\n      ‫يظهــر منــه اخلــداع واملكــر لــذا فــا يتوجــه ضمــان املدعــي ألربــاح ثمــن‬\n      ‫األرض لذلــك كلــه فقــد قــررت مــا يلــي‪ -1 :‬علــى املدعــي عليــه أن‬\n      ‫يعيــد إلــى املدعــي مليونــا وأربعمائــة ألــف ريــال ‪ -2‬علــى املدعــى عليهمــا‬\n      ‫‪............‬و‪ ...........‬أن يعيــد كل منهمــا إلــى املدعــي عشــرين ألــف ريــال‬\n      ‫‪ -3‬رددت دعــوى املدعــي باملطالبــة بأربــاح املبلــغ الــذي ســلمه ومبــا ســبق‬\n      ‫حكمــت وأفهمــت املدعــى عليــه وكالــة أن ملوكلــة ‪ ........‬اليمــن علــى‬\n      ‫املدعــي أنــه لــم يــرض بــأرض الهــدى وبعرضــه علــى املدعــى عليــه وكالــة‬\n      ‫لــم يقنــع بــه عــن موكليــه‪.............‬و‪ ...........‬وبعرضــه علــى احلاضــر‬\n      ‫‪ .............‬قنــع بــه وبعرضــه علــى املدعــي قنــع بــه فأفهمــت املدعــى عليــه‬\n      ‫وكالــة بتعليمــات االســتئناف ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n                  ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/09‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/07/05‬ه ـ‬\n\n\n‫‪215‬‬\n\f‫افتتحــت اجللســة الســاعة ‪ 1.35‬وفيهــا فقــد عــادت املعاملــة مــن محكمة‬\n‫االســتئناف بخطابهــم رقــم ‪ 34176550‬يف ‪1434/6/18‬ه ـ ارفــق بهــا‬\n‫القــرار رقــم ‪ 34239132‬يف ‪1434/6/12‬ه ـ ونــص احلاجــة منــه وبدراســة‬\n‫الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر باألكثريــة إعادتهــا‬\n‫لفضيلــة حاكمهــا حيــث لــم جنــد فضيلتــه افهــم املدعــي بــان عليــه‬\n‫إعــادة إفــراغ تلــك القطعــة املباعــة جلهــة املدعــى عليــه املالــك األول عنــد‬\n‫اســتالم ثمنهــا فعلــى فضيلتــه إكمــال مــا يلــزم اه ـ ‪ .‬عليــه فقــد حضــر‬\n‫املدعــي وقــرر بقولــه بعــد افهامــه بذلــك اننــي مســتعد بإعــادة إفــراغ‬\n‫األرض إلــى املدعــى عليــه ‪ .................‬حــال تســليمي املبلــغ احملكــوم‬\n‫بــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                         ‫وســلم ‪ .‬حــرر يف ‪ 1434/07/05‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫بخطابهــم رقــم ‪ 34176550‬يف ‪1434/8/1‬ه ـ ارفــق بهــا القــرار رقــم‬\n‫‪ 34277873‬يف ‪1434/7/24‬ه ـ املــدون علــى ظهــر الصــك املتضمــن‬\n‫املوافقــة علــى احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                 ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/08/09‬ه ـ‬\n‫احلمد هلل ‪ ،‬والصالة والسالم على رسول اهلل ‪ ،‬وبعد ‪ :‬ـ فقـد جـرى م ّنا‬\n‫نحـن رئيس وأعضاء الدائـرة احلقوقيـة السادسة يف محكمة االستئناف‬\n‫مبنطقة مك ــة املكرم ــة االطال ُع عل ــى هذا احلكم الصادر من فضيلة‬\n‫الشــيخ‪ ................./‬القاضــي باحملكمــة العامــة مبكــة املكرمــة‪،‬‬\n‫واملســجل بع ــدد ‪ 34186372‬وتاريــخ ‪1434/4/13‬هـ‪،‬املتضمــن دعــوى‬\n‫منصــور ‪ ...........‬ضــد ‪ ............‬احملكــوم في ــه مبــا دون باطــن الصــك‪،‬‬\n‫وبدراس ــة احلكــم وص ــورة ضبط ــه و الئحتــه االعتراضيــة تق ــررت‬\n\n\n                                                                                       ‫‪216‬‬\n\f      ‫املوافق ــة عل ــى احلكــم بعــد اإلجــراء األخيــر جواب ـ ًا علــى قــرار الدائــرة‬\n      ‫رقــم ‪ 34239132‬وتاريــخ ‪1434/6/12‬هــ‪،‬واهلل املوفــق‪ .‬وصل ــى اهلل‬\n                                      ‫عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم ‪.‬‬\n\n\n\n\n‫‪217‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":209,"source_page_end":217,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"569389900f2b05e015eaede4dccc6851a400e086800b6e0fb663c2a94e58418a","normalized_text_hash":"af18538b6263b38ccd38f541cbd6f06637a42e404a4dd1a094513fca93a7454a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p209-34186372"},{"id":"f2a8db77-fb1e-5086-b390-399d855abf21","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -تعويض -إيجار منتهي بالتمليك -دعوى تعويض عن ضرر -مطالبة بالتعويض عن فسخ عقد إيجار سيارة منتهي بالتمليك -استعانة برأي اخلبراء -رهن املبيع للبائع ال مينع من بقاءه بيد املشتري -منافع املغصوب يضمنها الغاصب -مقاصة قضائية .","document_number":"3438433","case_number":"3281602","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/16","year":"1434","subject":"بيع -تعويض -إيجار منتهي بالتمليك -دعوى تعويض عن ضرر -مطالبة بالتعويض عن فسخ عقد إيجار سيارة منتهي بالتمليك -استعانة برأي اخلبراء -رهن املبيع للبائع ال مينع من بقاءه بيد املشتري -منافع املغصوب يضمنها الغاصب -مقاصة قضائية .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/02/16 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3438433 :‬‬\n                    ‫َر ْق ُم الدعوى‪3281602 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34364150‬تاريخه‪1434/11/20 :‬هـ‬\n\n\n‫بيــع ‪ -‬تعويــض ‪ -‬إيجــار منتهــي بالتمليــك ‪ -‬دعــوى تعويــض عــن ضــرر‬\n‫‪ -‬مطالبــة بالتعويــض عــن فســخ عقــد إيجــار ســيارة منتهــي بالتمليــك‬\n‫‪ -‬اســتعانة بــرأي اخلبــراء ‪ -‬رهــن املبيــع للبائــع ال مينــع مــن بقــاءه بيــد‬\n     ‫املشــتري ‪ -‬منافــع املغصــوب يضمنهــا الغاصــب ‪ -‬مقاصــة قضائيــة ‪.‬‬\n\n\n\n‫‪ -1‬البيــع مــع رهــن املبيــع للبائــع ال مينــع مــن بقاء العني يف يد املشــتري‬\n                                                        ‫وعــدم قبض الرهن ‪.‬‬\n‫‪ -2‬منافــع املغصــوب مضمونــة والغاصــب يضمــن أجــرة املغصــوب إلــى‬\n        ‫حــن رده أو تلفــه‪ .‬شــرح املنتهــى ‪403/2‬و ‪ 421‬والكشــاف ‪187/4‬‬\n‫‪ -3‬قــول الشــيخ محمــد بــن إبراهيــم يف الفتــاوى(‪ ....« :)342-341/11‬ال‬\n  ‫يتحمــل مــا ينفقــه املصــاب املتســبب علــى املجنــي عليــه مــدة مرضــه» ‪.‬‬\n\n\n\n\n‫ادعى املدعي بأنه تعاقد مع الشركة املدعى عليها على شراء السيارة‬\n‫املوصوفــة يف دعــواه بالتأجيــر املنتهــي بالتمليــك وبالقيمــة املذكــورة‬\n‫مقســطة علــى عــدد األشــهر املذكــور ثــم وقــع عليهــا حــادث مــروري‬\n‫نتــج عنــه تلفهــا فســلمها للشــركة إلجــراء مــا يوجبــه العقــد إال أنهــا‬\n‫باعتهــا دون علمــه مبــا يقــل عــن ثلــث قيمتهــا الفعليــة ســوقي ًا فأضــرت بــه‬\n\n                                                                                       ‫‪218‬‬\n\f      ‫بذلــك‪ ،‬لــذا طلــب إلزامهــا بتعويضــه بســيارة مماثلــة وحتميلهــا أضــرار‬\n      ‫بيــع الســيارة دون قيمتهــا وأجــرة الســيارة التــي حتملهــا بســبب الشــركة‬\n      ‫طيلــة مــدة القضيــة وتســببها يف عجــزه عــن عــاج ابنــه حتــى تــويف‪ -‬أقــر‬\n      ‫وكيــل املدعــى عليهــا مبــا جــاء يف الدعــوى ودفــع بــأن موكلتــه التزمــت‬\n      ‫ببنــود العقــد املبــرم بينهمــا‪ ،‬كمــا أن املدعــي فــرط يف تعريــض العــن‬\n      ‫للمخاطــر بــأن خالــف شــروط التأمــن فســلم الســيارة ملــن عمــره أقــل مــن‬\n      ‫(‪ )20‬ســنه برغبتــه واختيــاره واملفــرط أولــى باخلســارة ولذلــك فموكلتــه‬\n      ‫غيــر مســتعدة بتعويضــه مبــا طلــب ‪ -‬قــررت احملكمــة تكليــف جلنــة مــن‬\n      ‫اخلبــراء للتحقيــق يف القضيــة مــن جميــع جوانبهــا وإصــدار تقريــر يبــن‬\n      ‫فيــه حتديــد مســئولية الشــركة املدعــى عليهــا مــن عدمــه بهــا فتوصلــت‬\n      ‫إلــى حتميــل الشــركة املدعــى عليهــا مســئولية إصــاح ســيارة املدعــي أو‬\n      ‫تعويضــه عــن قيمتهــا وأن الشــركة املدعــى عليهــا ال تتحمــل مــا يتعلــق‬\n      ‫مبــا ذكــره مــن تســببهم يف وفــاة ابنــه وأن باقــي طلباتــه راجعــة للنظــر‬\n      ‫القضائــي ‪ -‬حقيقــة العقــد بــن الطرفــن بيــع برهــن والثمــن مؤجــل‬\n      ‫يســدد علــى أقســاط لــذا فيجــري عليــه أحكامــه ‪ -‬الشــركة تصرفــت‬\n      ‫يف الســيارة وباعتهــا ممــا تســبب يف تفويــت التعويــض املســتحق للمدعــي‬\n      ‫فتكــون ضامنــة للســيارة ألنهــا يف حكــم املغصــوب ‪ -‬مطالبــة املدعــي‬\n      ‫بأضــرار بيــع الســيارة وأجــرة الســيارة التــي حتملهــا بســبب الشــركة‬\n      ‫طيلــة مــدة القضيــة وتســببهم يف عجــزه عــن عــاج ابنــه حتــى تــويف غيــر‬\n      ‫متوجهــة ألن حقــه يف رفــع الضــرر وقــد مت رفعــه بإعطائــه مــا يســتحق ‪-‬‬\n      ‫قضــت احملكمــة بإلــزام الشــركة املدعــى عليهــا بتســليم املدعــي مبلغـ ًا‬\n      ‫يعــادل قيمــة الســيارة بعــد احلــادث وتســليمه قيمــة التعويــض املتوقــع عــن‬\n      ‫التلفيــات بســبب احلــادث بعــد أن خصمــت األقســاط املتبقيــة للشــركة‬\n\n\n‫‪219‬‬\n\f‫وصــرف النظــر عــن باقــي مــا يطالــب بــه املدعــي وأفهمــت املدعــي بــأن لــه‬\n‫مطالبــة الشــركة بأجــرة الســيارة مــدة بقائهــا لديهــا‪ -‬عــارض املدعــي‬\n‫ووكيــل املدعــى عليهــا علــى احلكــم ‪ -‬قــررت محكمــة االســتئناف‬\n                                                        ‫املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بحائــل برقــم ‪ 3281602‬وتاريــخ ‪ 1432/03/17‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 32250587‬وتاريــخ ‪ 1432/3/16‬ه ـ ففــي يــوم األحــد‬\n‫املوافق‪ 1432/07/10‬هـ افتتحت اجللســة الســاعة ‪ 09 : 09‬وفيها حضر‬\n‫‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .....‬وادعــى علــى‬\n‫احلاضــر معــه ‪ .....‬ســجل مدنــي رقــم ‪ .....‬الوكيــل عــن ‪ .....‬و‪ .....‬بصفتهــم‬\n‫مــدراء شــركة ‪ .....‬للســيارات احملــدودة مبوجــب الوكالــة الصــادرة مــن‬\n‫ا يف دعــواه‬ ‫كتابــة عــدل عرقــه برقــم ‪ 329721‬يف ‪1432/1/19‬ه ـ قائـ ً‬\n‫عليــه اشــتريت مــن الشــركة ســيارة اوبتــرا صنــع ‪2007‬م رقــم اصــل‬\n‫‪ 2647‬بالعقــد رقــم ‪1589‬عــام ‪1430‬ه ـ بالتأجيــر املنتهــي بالتمليــك‬\n‫قيمتــه (‪ )55150‬ريــال مقســطة علــى (‪ )48‬قســطا تبــدا مــن ‪2008/7/1‬‬\n‫وتنتهــي يف ‪2012/6/1‬م وكنــت منتظم ـ ًا بأقســاطهم حتــى حصــل‬\n‫عليهــا حــادث مــروري نتــج عنــه تلــف الســيارة ســلمتها لهــم إلجــراء مــا‬\n‫يوجبــه العقــد بيننــا محقـ ًا للطرفــن فباعوهــا دون علمــي بأقــل مــدة علــى‬\n‫التشــليح مبــا يقــل عــن ثلــث قيمتهــا الفعليــة ســوقي ًا وزوروا علــي ورقــة‬\n‫بالعلــم والقبــول منــي والتعهــد بدفــع باقــي متأخــرات العقــد فاضــروا بــي‬\n\n                                                                                     ‫‪220‬‬\n\f      ‫ضــررا محدقــا متعمــدا منهــم لكــون الشــركة املدعــى عليهــا أضــرت‬\n      ‫بــي ضــررا محدقــا ولــم تعمــل الواجــب النظامــي بشــروط العقــد بيننــا‬\n      ‫وانتهــزت فرصــة الكارثــة علــى الســيارة فباعوهــا بثمــن بخــس زيــادة يف‬\n      ‫ضــرري دون علمــي وزورا علــي املوافقــة والعلــم اطلــب نظــر دعــواي‬\n      ‫بالوجــه الشــرعي بإلزامهــم مبنطــوق العقــد بتعويضــي بســيارة مماثلــه‬\n      ‫وحتميلهــم أضــراري ببيــع الســيارة دون قيمتهــا واجــرة الســيارات التــي‬\n      ‫حتملتهــا بســببهم طيلــة القضيــة وتســببهم يف عجــزي عــن عــاج ابنــي‬\n      ‫حتــى تــويف وبرفقــه مذكــرة لتحريــر الدعــوى مفصلــة وبســؤال املدعــى‬\n      ‫عليــه وكالــة أجــاب قائــا اطلــب مهلــة للجــواب للرجــوع إلــى الشــركة‬\n      ‫وافادتكــم باجللســة القادمــة ورفعــت اجللســة ويف يــوم األحــد افتتحــت‬\n      ‫اجللســة وفيهــا حضــر املدعــي كمــا حضــر ‪ .....‬ســعودي الســجل املدنــي‬\n      ‫رقــم ‪ .....‬الوكيــل عــن شــركة ‪ .....‬للســيارات احملــدودة مبوجــب‬\n      ‫الوكالــة الصــادرة مــن كتابــة عــدل عرقــه برقــم ‪ 329721‬يف‬\n      ‫‪1432/1/19‬ه ـ وقــرر املدعــى عليــه وكالــة ان الشــركة تطلــب مهلــة‬\n      ‫إضافيــة للجــواب حيــث طلبــت أوراق املعاملــة اخلاصــة بالقضيــة لالطــاع‬\n      ‫عليهــا ونطلــب مهلــة إضافيــة فاهمتــه بــان املوعــد القــادم آخــر موعــد‬\n      ‫وعلــى الشــركة أن تعــد اجلــواب وإال عديتهــا ناكله عــن اجلواب واجرينا‬\n      ‫الــازم الشــرعي والنظامــي ففهــم املدعــى عليــه وكالــة ذلــك ثــم رفعــت‬\n      ‫اجللســة ويف يــوم األحــد املوافــق ‪1432/9/21‬ه ـ افتتحــت اجللســة يف‬\n      ‫الســاعة ‪ 11 : 30‬وحضــر الطرفــان وقــدم املدعــى عليــه وكالــه رد ًا‬\n      ‫مكتوب ـ ًا ملخصــه ان املدعــى عليــه قــد اســتأجر ثــاث ســيارات بعقــد‬\n      ‫واحــد وليــس ســيارة واحــده ومنهــا الســيارة محــل الدعــوى كمــا قــرر‬\n      ‫املدعــى عليــه وكالــه ان الشــركة ملتزمــة مبــا جــاء يف العقــد وبنــوده‬\n\n\n‫‪221‬‬\n\f‫وان الشــركة غيــر مســئوله عــن مــا جــاء يف دعــوى املدعــي ويطلــب‬\n‫املدعــى عليــه وكالــه احلكــم بــرد الدعــوى وبعــرض ذلــك علــى املدعــي‬\n‫قــال أطلــب مهلــة للجــواب ورفعــت اجللســة ويف يــوم االثنــن املوافــق‬\n‫‪1432/10/27‬هـ افتتحت اجللســة يف الســاعة العاشــرة وحضر الطرفان‬\n‫وقــدم املدعــي رد ًا مخزن ـ ًا يف ذاكــرة ونصهــا ( بســم اهلل الرحمــن‬\n‫الرحيــم التاريــخ احلمــد هلل وحــده وبعــد مذكــرة الــرد يف الدعــوى املقامة‬\n‫مــن ‪ ...‬ضــد شــركة ‪ ...‬للســيارات ردا علــى مذكــرة الوكيــل الشــرعي‬\n‫لشــركة ‪ ...‬والتــي جــاءت مذكرتــه بدفــاع تهــرب بــه عــن احلقيقــة‬\n‫الواضحــة ولــم ينــف ادعاءاتــي باألدلــة القاطعــة مــع أنــي اثبــت خطــأ‬\n‫الشــركة وتهربهــم عــن تعويضــي مبســتندات لــم يتطــرق إليهــا الشــك أو‬\n‫الطعــن فيهــا واســتكماال لدعــواي ضــد الشــركة أرد علــى مذكــرة‬\n‫وكيــل الشــركة مبــا يلــي‪ -:‬أوال‪ :‬ذكــر وكيل الشــركة أني اشــتريت‬\n‫ثــاث ســيارات مــن نفــس النــوع وال اعلــم مــا عالقــة ذلــك بدعــواي حيــث‬\n‫أنــي لــم أنكــر هــذه الســيارات ولكن دعــواي على احد هذه الســيارات‪.‬‬\n‫ثانيــا‪ :‬ذكــر وكيــل الشــركة أنــي ذكــرت يف مذكــرة ادعائــي بــان‬\n‫الشــركة لــم تلتــزم بالعقــد وهــذه حقيقــة ال يســتطيع نفيهــا أمــام وجــود‬\n‫البينــة القاطعــة لــدي حالــة إنــكاره وإال أيــن ســيارتي أو تعويضهــا أو‬\n‫تعويضــي عــن مضرتــي املترتبــة علــى إتالفهــا وإضاعــة وقتــي يف قضايــا‬\n‫ومحاكــم علــى الرغــم مــن أنــي لــم اخــل بــأي بنــد مــن بنــود عقدهــم معــي‬\n‫فيمــا يخــص هــاك الســيارة فلمــاذا لــم احصــل علــى حقــي حتــى اآلن مــن‬\n‫تعويــض وإال مــا معنــى أن شــركة التأمــن لــم تقبــل الســيارة مــع العلــم‬\n‫انــه مذكــور بعقــد التأجيــر يف (البنــد عاشــرا) أن الســيارة املؤجــرة‬\n‫مؤمــن عليهــا مــن قبــل املؤجــر مبوجــب بوليصــة تأمــن طــوال مــدة هــذا‬\n\n\n                                                                                     ‫‪222‬‬\n\f      ‫العقــد ضــد (احلــوادث املروريــة) واقتضــاء ملــا قضــت بــه املــادة (‪ )100‬مــن‬\n      ‫نظــام املرافعــات الشــرعية اســأل وكيــل الشــركة إذا كان دفاعــه‬\n      ‫بعــدم شــمول الســيارة للتامــن بســبب صغــر ســن قائــد الســيارة فلمــاذا‬\n      ‫لــم ابلــغ بهــذا الشــرط الذيــن يعلمونــه باعتبارهــم هــم جهــة التعاقــد مــع‬\n      ‫شــركة التامــن وأنــا ال اعلمــه عندمــا طلبــت عمــل هــذا التفويــض‬\n      ‫للقائــد وهــم يعلمــون أن شــروط التأمــن ال تنطبــق عليــه وبالتالــي أكــون‬\n      ‫علــى علــم بهــذا الشــرط إمــا أن يصــدر تفويــض لــه تأمــن شــامل وهــو‬\n      ‫مخالــف لشــروط التأمــن ثــم أحتمــل أنــا هــذه املخالفــة فهــذا مخالــف‬\n      ‫للشــرع والنظــام ثالثــا‪ :‬أقــر وكيــل الشــركة يف مذكرتــه مبــا نصــه‪:‬‬\n      ‫(بأنــي أحضــرت جميــع األوراق املطلوبــة للشــركة لرفعهــا إلــى شــركة‬\n      ‫التامــن مــن تقريــر باحلــادث وتســعيرات مصدقــة مــن إدارة مــرور حائــل‬\n      ‫وهــذا يــدل علــى أن املذكــور متابــع ومتواصــل مــع الشــركة عــاوة انــه‬\n      ‫يقــوم ســداد األجــرة الشــهرية املســتحقة عليــه نهايــة كل شــهر للســيارة‬\n      ‫األخــرى) وهــذا إقــرار مــن ممثــل املدعــى عليهــا يشــكر عليــه فانــا لــم‬\n      ‫اخــل بــأي التــزام وهــذا دوري لكــي أحصــل علــى حقــي مــن شــركة‬\n      ‫التأمــن كمــا هــو متبــع يف نظــام شــركات التأمــن أما أن تباع الســيارة‬\n      ‫بــدون علمــي وبأقــل مــن ثلــث ثمنهــا فهــذا فيــه إضاعــة حلقــي فبعــد‬\n      ‫أســبوعني قمــت مبراجعــة الشــركة فذكــرت أن التأمــن ال يشــمل‬\n      ‫الســيارة وأنــا عقــدي مــع الشــركة املدعــى عليهــا أن الســيارة يشــملها‬\n      ‫التامــن أمــا أن التامــن رفــض الســيارة فليــس لــي عالقــة بهــذا فحقــي‬\n      ‫معــروف كمــا ذكــرت ســابقا بنظــام شــركات التأمــن عنــد حــدوث‬\n      ‫حادثــة للســيارة أن تتكفــل شــركة التأمــن بإصالحهــا أو إعطــاء‬\n      ‫صاحــب الســيارة ســيارة بديلــة وهــذا هــو املعــروف يف عقــود التأمــن‬\n\n\n‫‪223‬‬\n\f‫كمــا نصــت القاعــدة (املعــروف عرفــا كاملشــروط شــرطا) مــع وجــود‬\n‫الشــرط فيــه أمــا املبــرر التــي ذكرتــه الشــركة املدعــى عليهــا مــن‬\n‫رفــض شــركة التأمــن تعويــض الســيارة هــو صغــر ســن قائــد الســيارة‬\n‫فهــذا املبــرر ليــس لــه أســاس مــن الصحــة حيــث أن القائــد لديــه رخصــة‬\n‫قيــادة وتفويــض مــن الشــركة املدعــى عليهــا‪ .‬فهــم مــن فوضــوه بقيــادة‬\n‫الســيارة حينمــا كانــوا مســتفيدين وعنــد املطالبــة جعلــوا ذلــك محــا‬\n‫لطعنهــم بــه وادعائهــم باملخالفــة وهــم مصــدر املخالفــة إن اعتبــرت‬\n‫مخالفــة ومــع افتــراض ذلــك فبــأي قانــون تعطــي الشــركة احلــق لنفســها‬\n‫يف بيــع الســيارة دون علــم مســتأجرها‪ .‬حيــث أن الشــركة أخــذت منــي‬\n‫مبلــغ (‪ )500‬ريــال لدخــول الســيارة الورشــة إلصالحهــا وحتــى علمــت‬\n‫بالبيــع لــم اعلــم أيــن الســيارة وملــاذا اخــذوا منــي هــذا املبلــغ إذا كان يف‬\n‫نيتهــم بيعهــا‪ .‬رابعــا‪ :‬أمــا بالنســبة لورقــة التعهــد واإلقــرار الــذي يدفــع بــه‬\n‫وكيــل الشــركة بــأن مثــل هــذه الورقــة ترســل للعميــل ويؤخــذ توقيــع‬\n‫مــن اســتلمها هــذا الدفــاع كلــه لــدد خصومــة ومغالطــة وتناقضــات وال‬\n‫يعقــل مــا ذكــر بخصوصهــا فهــو دفــع غيــر مــاق للدعــوى واضــح منــه‬\n‫التهــرب مــن احلــق وبالرغــم مــن الصفــة التجاريــة للورقــة وأهميتها كيف‬\n‫يؤخــذ إقــرار أو تعهــد مــن شــخص علــى إجــراء مهــم مثــل ذلــك دون‬\n‫صاحــب الصفــة فيهــا فهــذا خطــأ فــادح مــن الشــركة املدعــى عليهــا‬\n‫وهــذا الدفــع منهــم بعــد أن طعنــت بتزويــر توقيعــي عليهــا لــدى اجلهــة‬\n‫املختصــة فأطالــب بإحضــار املُوقــع علــى الورقــة واملوظــف الــذي تولــى‬\n‫اإلجــراء ‪.‬واألمــر الثانــي ذكــر وكيــل الشــركة يف مذكرتــه بالبنــد‬\n‫ثالثــا أنــي كنــت أســدد األجــرة الســنوية ثــم يأتــي يف نفس هــذه املذكرة‬\n‫بالفقــرة الرابعــة منهــا ويذكــر أن التعهــد يرســل إلــى العميــل يف حالــة‬\n\n\n                                                                                           ‫‪224‬‬\n\f      ‫تأخــره عنــد الســداد فلمــاذا هــذا التناقــض الــذي يوضــح التهــرب مــن‬\n      ‫احلــق والدفــع بأســباب واهيــة ال ترقــى إلــى ســبب إلضاعــة حقــي‪ .‬وأنبــه‬\n      ‫أحضــرت بعــد أن كســبت القضيــة يف‬         ‫فضيلــة القاضــي أن هــذه الورقــة ُ‬\n      ‫فــرع وزارة التجــارة بحائــل يف اجللســة األخيــرة احضرهــا الوكيــل‬\n      ‫الشــرعي الســابق لــدى الشــركة املدعــى عليهــا (‪ ).....‬وعنــد ســؤالي لــه‬\n      ‫مــن أيــن أحضرتهــا قــال مــن امللــف فقلــت لــه ملــاذا كل أوراق القضيــة‬\n      ‫يوجــد عليهــا صــورة فتحــات اخلرامــة أمــا ورقــة التعهــد واإلقــرار ال يوجــد‬\n      ‫عليهــا آثــار اخلرامــة فقــال يجــوز آلــه التصويــر اخفــت آثــار الفتحــات وهــي‬\n      ‫إجابــة مراوغــة غيــر منطقيــة !!! وقــد أراد وكيــل الشــركة يف دفاعــه‬\n      ‫أن يخفــي احلقيقــة بدفــاع ُيبعــد عــن موضــوع القضيــة فذكــر أن هــذا‬\n      ‫التعهــد واإلقــرار ال يقيــد الشــركة حتــى تقــوم بتزويــره وهــذا صحيــح‬\n      ‫وال يحتــاج إلــى ذكــر ألن هــذه الورقــة تقيدنــي وتضيــع حقــي أنــا وإال لــم‬\n      ‫تقــم الشــركة بتزويرهــا ألن لــو هــذا التوقيــع صحيــح ملــا اســتطعت‬\n      ‫مطالبــة الشــركة بــأي شــيء مــن حقوقــي التــي أطالــب بهــا حاليــا يف‬\n      ‫دعــواي‪ .‬كمــا ذكــر وكيــل الشــركة املدعــى عليهــا بــان تاريــخ ورقــة‬\n      ‫التعهــد بتاريــخ ‪1430/4/16‬ه ـ وتاريــخ احلــادث بتاريــخ ‪1430/4/22‬ه ـ‬\n      ‫وهــذا دليــل قاطــع علــى أن املوضــوع مدبــر فلمــاذا يؤخــذ تعهــدي قبــل‬\n      ‫احلــادث بأربعــة أيــام فقــط فهــل هــم علــى علــم باحلــادث انــه ســيحدث‬\n      ‫وبالتالــي قامــوا بأخــذ تعهــدي قبلــه بأربعــة أيــام كتأمني حلقهــم وإضاعة‬\n      ‫حقــي ولــو متعنتــم فضيلتكــم هــذا اإلقــرار لوجــدمت فيــه احلقيقــة وكيــف‬\n      ‫دبــروا وخططــوا إلضاعــة حقــي‪ .‬هــذا باإلضافــة انــه مــزور‪ .‬وأضيــف‬\n      ‫لفضيلتكــم دليــل آخــر علــى نيتهــم وتهربهــم مــن إعطائــي حقــي أن‬\n      ‫فواتيــر التشــليح كلهــا مــزورة ومكتوبــة بخــط واحــد وغيــر كاملــة‬\n\n\n‫‪225‬‬\n\f‫البيانــات باإلضافــة أن احــد أصحــاب ورش التشــليح ذكــر بأنــه ال علــم‬\n‫لــه بالفاتــورة وغيــر صحيحــة‪ .‬هــل يعقــل أن يتــم خــال أربعــة وعشــرين‬\n‫ســاعة ‪-1‬إجــراء خطــاب موجــه مــن مديــر التحصيــل إلــى مديــر الفــرع‬\n‫باالستفســار وانتظــار التوجيــه بخصــوص ســيارة لــم يشــملها التأمــن‪-2.‬‬\n‫عمــل تســعيرة مــن ثــاث ورش تشــليح‪ -3 .‬بيــع الســيارة عــن طريــق‬\n‫الشــركة ‪ .‬هــل هــذه هــي إجــراءات الشــركة يف مثــل هــذه املواقــف أم‬\n‫هــي إجــراءات إلضاعــة حــق املواطنــن بــدون وجــه حــق‪ .‬أمــا فيمــا يتعلــق‬\n‫بالتفويــض فقــد ذكــر وكيــل الشــركة املدعــى عليهــا بــان إعطائــي‬\n‫الســيارة لشــخص آخــر بأنــه تفريــط وتعــدي وكأنــه جتاهــل بــان إدارة‬\n‫املــرور منحتــه رخصــة قيــادة وكذلــك جتاهــل أيضـ ًا بــأن التفويــض منــح‬\n‫مــن قبــل الشــركة وليــس مــن قبلــي للســماح لــه بقيــادة الســيارة وموضــح‬\n‫بالســيارة أن عليهــا تامــن شــامل‪ .‬فلمــاذا لــم تتأكــد الشــركة بــان قائــد‬\n‫الســيارة لــم تشــمله شــروط التامــن وبالتالــي عــدم إعطائــه التفويــض او‬\n‫تنبيــه صاحــب الســيارة بــان الشــخص املفــوض لــه ال يشــمله التامــن‬\n‫وهــذا مــن واجــب عملهــا ‪ .‬اســتخلص مــن هــذا كلــه بــان الشــركة لــم‬\n‫تبالــي ألنهــا ضامنــة حلقهــا حقـ ًا او باطـاً‪ .‬والتفويــض يعمــل منــه كثيــر‬\n‫لغيــر صاحــب العقــد (املســتأجر) يجعلــوه مــن الباطــن‪ .‬خامسـاً‪ :‬مــا دامت‬\n‫التســعيرات املعتمــدة هــي التســعيرات الصــادرة مــن املعــارض كمــا‬\n‫تدعــي الشــركة فلمــاذا تقــوم بتزويــر فواتيــر التشــليح علمــا بــأن‬\n‫التســعيرات اخلاصــة باملعــارض هــي خاصــة بشــركات التأمــن حلســاب‬\n‫قيمــة الســيارة بعــد احلــادث مــن قبــل شــركات التأمــن وهــذا املتبــع يف‬\n‫نظــام املــرور أمــا عنــد بيــع الســيارة التــي ال يشــملها التأمــن فيتــم‬\n‫تســعيرها مــن قبــل ورش التشــليح علمـ ًا بــان قيمــة الســيارة تكــون أعلــى‬\n\n\n                                                                                   ‫‪226‬‬\n\f      ‫مــن قيــم املعــارض ألن التشــليح يســتفيد مــن كل قطعــة بالســيارة أمــا‬\n      ‫املعــرض فيقيــم الســيارة ككل‪ .‬سادســا‪ :‬أمــا بالنســبة للدعــوى اخلاصــة‬\n      ‫بابنــي فانــا ال أتكلــم مــن فــراغ والتقاريــر واملواعيــد املتداخلــة بــن‬\n      ‫مواعيــد اجلهــات املختصــة اخلاصــة بالقضيــة ومواعيــد مراجعــات ابنــي‬\n      ‫باملستشــفيات تثبــت ذلــك ومطالبــة الشــركة باملبالــغ املاليــة التــي ال حــق‬\n      ‫لهــم فيهــا أثــرت علــي نفســيا وماديــا ولــم اســتطع أن أتفــرغ البنــي ومتابعة‬\n      ‫حالتــه الصحيــة حتــى جــاء قضــاء اهلل وقــدره وتوفــى ابنــي بســبب جتاهــل‬\n      ‫الشــركة لــي ومبطالبتــي‪ .‬وقــد انفــردوا بالســبب يف ضــرري ووفــاة ابنــي‬\n      ‫بســبب مباشــر افتعلــوه بهــدف االنتفــاع غيــر املشــروع متجرديــن مــن أي‬\n      ‫وازع‪ .‬خالصــة الــرد‪ :‬اســتخلص لفضيلتكــم مــن هــذا الــرد ان الشــركة‬\n                                               ‫هي املسئولة عن ضياع حقي لسببني‪:‬‬\n      ‫األول‪ -:‬لكــون الشــركة تعمــدت التفويــض لســائق ال يشــمله التامــن‬\n      ‫بــدون علمــي بــان ســنه ال ينطبــق عليهــا نظــام رخصــة القيــادة وال يشــمله‬\n      ‫التامــن وهــم اطلعــوا علــى وثائقــه برخصــة قيــادة مؤقتــة وعمــره اقــل مــن‬\n      ‫املشــروط بنظــام التامــن واخفــوا عنــي ذلــك‪ .‬ثانيــا‪ -:‬الشــركة زورت‬\n      ‫توقيعــي علــى ورقــة تعهــد تديننــي وحتملنــي مســؤولية خســارة وخطــأ لــم‬\n      ‫ارتكبــه ‪ .‬الطلــب‪ :‬اطلــب صــرف النظــر عــن دفــاع ممثــل اجلهــة املدعــى‬\n      ‫عليهــا واحلكــم لــي بدعــواي كمــا فصلتــه بحقــل الطلــب مــن صحيفــة‬\n      ‫الدعــوى ‪ .‬املقــدم ع‪.).....‬أ‪.‬ه ـ وبعــرض ذلــك علــى املدعــى عليــه وكالــة‬\n      ‫قــال اطلــب مهلــة للــرد ثــم رفعــت اجللســة ويف يــوم االربعــاء‬\n      ‫املوافق‪1432/1/28‬ه ـ افتتحــت اجللســة الســاعة (‪ )9:51‬وفيهــا حضــر‬\n      ‫الطرفــان وقــدم املدعــى عليــه وكالــة الئحــة رده ونصهــا‪ -1‬ذكــر‬\n      ‫املدعــى انــه ال يعلــم بعالقــة الســيارة محــل الدعــوي بالســيارات الثــاث‬\n\n\n‫‪227‬‬\n\f‫املؤجــرة عليــه يف الدعــوى املقدمــة منــه بتاريــخ ‪1432/6/6‬ه ـ حيــث‬\n‫أشــار املدعــي يف البنــد ثانيــا أن هــاك الســيارة قــد تســبب لــه بخســائر‬\n‫ماديــة جــراء اســتجارة ســيارة خــال مــدة مطالبتــه للشــركة وكذلــك‬\n‫عجــزه عــن الســفر إلــى األردن لعــاج ابنــه لعــدم وجــود ســيارة بديلــة ‪ ،‬إذ ًا‬\n‫أيــن الســيارة الثالثــة املتبقيــة لديــه ‪ ،‬وملــاذا لــم يســتخدمها ملــا ذكــر‬\n‫أعــاه جتنبــا ملــا ذكــر مــن األســباب ‪ ،‬مبــا أن عقــد التأجيــر عقــد لثالث‬\n‫ســيارات ‪ -2 .‬ذكــر املدعــي أن الشــركة لــم تلتــزم ببنــود العقــد وإال‬\n‫أيــن ســيارته أو تعويضهــا كمــا ذكــر ‪ ،‬نذكــر املدعــى انــه مســتأجر‬\n‫ســيارات مملوكــة للشــركة وليســت ملــكا لــه ‪ ،‬ذكــر أن الســيارة‬\n‫مؤمــن عليهــا بنــاء علــى مــا جــاء بالبنــد العاشــر ضــد احلــوادث املروريــة‬\n‫هــذا صحيــح حيــث أن جميــع الســيارات التابعــة للشــركة مؤمــن عليهــا‬\n‫حســب تعليمــات التامــن وشــروطها املوضحــة بالعقــد وأفــاد انــه لــم يبلــغ‬\n‫عنهــا بينمــا هــو موقــع علــى العقــد مــن ضمنهــا شــروط التامــن والبنــد‬\n‫احلــادي عشــر( بنــود ال يشــملها التامــن)‪ ،‬ومبــا أن املذكــور خالــف‬\n‫شــروط التامــن بالعقــد بتســليم الســيارة ملــن هــو اقــل مــن (‪ )20‬ســنه‬\n‫برغبتــه واختيــاره فهــذا يــدل علــى أنــه عــرض العــن للمخاطــر ومفــرط‬\n‫واملفــرط أولــى باخلســارة حســب كالم أهــل العلــم ومنهــم الشــيخ صالــح‬\n‫الفــوزان يف كتــاب امللخــص الفقهــي بــاب اإلجــارة ‪،‬علمــا أن العميــل‬\n‫لديــه الدرايــة الكاملــة بعقــود التأجيــر حيــث أنــه كفيــل ملكتــب‬\n‫مباشــر لتأجيــر الســيارات عــاوة أنــه تقــدم ألكثــر مــن مــرة بطلــب منــح‬\n‫أشــخاص تفاويــض بقيــادة ســيارة داخليــا وخارجيــا كمــا هــو مرفــق‪،‬‬\n‫وحتــى لــو أن شــركة التامــن جتــاوزت هــذا الســبب لنظــرت إلــى الســبب‬\n‫األخــر وهــو نســبة اخلطــأ (‪ )%100‬علــى الســائق فهــذا يعــد إهمــال متعمــد‬\n\n\n                                                                                       ‫‪228‬‬\n\f      ‫وإضــرار مبمتلــكات الغيــر املؤمتــن عليهــا ‪ .‬أمــا مــا ذكــر بشــان اخــذ‬\n      ‫الشــركة (‪ )500‬ريــال لدخــول الســيارة فهــذه رســوم لعمــل التقديــرات‬\n      ‫الالزمــة كمــا هــو موضــح نســخته بالتقريــر الــذي قدمــه املدعــي وهــو‬\n      ‫علــى علــم بذلــك حيــث اســتحصلت منــه مثــل هــذه الرســوم للســيارة‬\n      ‫األخــرى التــي حصــل عليهــا احلــادث قبــل هــذه الســيارة محــل الدعــوي‬\n      ‫‪ -3‬بالنســبة لورقــة التعهــد املؤرخــة بتاريــخ ‪1430/4/16‬ه ـ ومــا ذكــر‬\n      ‫املدعــي بشــأنها ‪ ،‬نرغــب أن نوضــح لفضيلتكــم وكمــا ذكرنــا ســابقا‬\n      ‫بــان العميــل مســتأجر (‪ )3‬بعقــد واحــد حصــل حــادث علــى إحداهــا‬\n      ‫بتاريــخ ‪1430/4/10‬ه ـ وبلغــت الشــركة مبوافقــة التأمــن علــى قبولهــا‬\n      ‫بتاريــخ ‪1430/6/12‬ه ـ ‪،‬وحصــل حــادث أخــر علــى ســيارة اخــرى محــل‬\n      ‫الدعــوي بتاريــخ ‪1430/4/22‬ه ـ ورفضــت مــن شــركة التأمــن بتاريــخ‬\n      ‫‪1430/6/22‬ه ـ ‪ ،‬وجــاء بنــص الورقــة (مســتأجر ثــاث ســيارات بعقــد‬\n      ‫رقــم (‪ )1589‬وانــه متأخــر قســطني وان يلتــزم بســداد (‪ )5400‬وإال‬\n      ‫ســحب الســيارة وبيعهــا وشــكايتي بــأي مبالــغ ) ‪ ،‬لــذا يجــب توضيــح‬\n      ‫التالــي ‪ :‬تاريــخ التعهــد متداخــل بــن تاريــخ احلادثــن ‪ ،‬ونــص التعهــد‬\n      ‫يشــمل كل الســيارات بالعقــد وان املبلــغ املطلــوب هــو قيمــة أجرة ســابقة‬\n      ‫مســتحقة علــى العميــل بواقــع أجــرة شــهرين لــكل ســيارة مــن الســيارات‬\n      ‫الثــاث قبــل احلــوادث وليــس كمــا ذكــر بــان الشــركة علــى علــم‬\n      ‫بالغيــب ‪ ،‬ولــم يحــدد التعهــد ســيارة بعينهــا وان عبــارة ســحب الســيارة‬\n      ‫مقصــود التنبيــه بســحب ســيارة أو كل الســيارات املؤجــرة ‪ ،‬اذ ًا ملــاذا‬\n      ‫العميــل حــدد الســيارة محــل الدعــوي ولــم يشــير إلــى الســيارة التــي‬\n      ‫حصــل عليهــا حــادث قبلهــا أو التــي بحوزتــه اآلن‪ -4 .‬مــا ذكــر املدعــي‬\n      ‫عــن تزويــر التســعيرات اخلاصــة بالتشــاليح ‪ ،‬نفيدكــم أن العميــل ليــس‬\n\n\n‫‪229‬‬\n\f‫لــه شــان باإلجــراءات الداخليــة التــي تخــص الشــركة وان الــذي بــن‬\n‫الشــركة والعميــل هــي التســعيرات الرســمية املوجهــة إلدارة املــرور‬\n‫املعتمــدة واملصدقــة مــن قبلهــم والتــي يتــم التعامــل مبوجبهــا بحكــم‬\n‫صفتهــا القانونيــة ‪ -5 .‬أمــا ذكــر بالفقــرة سادســا مــن عــدم تفرغــه البنــه‬\n‫ومتابعــة حالتــه الصحيــة ووفــاة ابنه بســبب جتاهل الشــركة لــه وملطالبه‬\n‫فهــذا موضــوع يخصــه شــخصيا وليــس للشــركة عالقــة مبــا ذكــر مــن‬\n‫أســباب أو كانــت ســبب فيــه ألنــه هــو مــن قــام بتقــدمي ورفــع الدعــاوى‬\n‫واملراجعــات وليــس الشــركة‪ -6 .‬أمــا مــا ذكــر أن الشــركة تعمــدت‬\n‫التفويــض لســائق ال يشــمله التأمــن ‪ ،‬ذكرنــا ســابقا أن التفويــض عمــل‬\n‫مــن اجــل إكمــال األوراق إلدخــال احلــادث لشــركة التامــن مســاعدة‬\n‫للعميــل ‪ ،‬والعميــل اســتغل مثــل هــذه الورقــة حتــى يديــن الشــركة‪،‬‬\n‫ونتســأل مــن ســلم الشــخص الســيارة الــذي عمــل احلــادث بهــا وقــام بتبليــغ‬\n‫الشــركة باحلــادث ووقــع بذلــك ومــا صلــت القرابــة بينهــم‪ ،‬وهــل‬\n‫الشــركة تســليم ســيارة لشــخص غيــر املســتأجر‪ ،‬ال كنــه بعــد رفــض‬\n‫الســيارة مــن شــركة التامــن يحــاول حتميــل الشــركة خطئــه‪ ،‬وأمــا مــا‬\n‫ذكــر بشــان تزويــر توقيعــه وان الورقــة تدينــه وحتملــه مســؤولية اخلســارة‬\n‫واخلطــاء ‪ ،‬ســبق وأوضحنــا بــان مثــل ورقــة التعهــد هــذه ترســل ألي عميــل‬\n‫لــدى الشــركة وهــى إنــذار وتنبيــه بــان لديــه أجــرة شــهران مســتحقة لــم‬\n‫تدفــع للســيارات الثــاث (‪3(*)1800 =2*900‬ســيارات )= ‪ 5400‬ريــال‬\n‫وإال ســوف تســحب الســيارة أو الســيارات ‪.‬بنــاء ملــا تقــدم توضيحــه‬\n‫لفضيلتكــم نأمــل البــت يف يــراه فضيلتكــم ورد دعــوى املدعــي عليــه‬\n‫وإلزامــه بحقــوق الشــركة ‪، ،‬وفقكــم اهلل وســدد خطاكــم والســام‬\n‫عليكــم وبعــرض ذلــك علــى املدعــي قــال أطلــب مهلــة للــرد واجبتــه‬\n\n\n                                                                                    ‫‪230‬‬\n\f      ‫لطلبــه ورفعــت اجللســة ويف يــوم االثنــن املوافــق ‪1433/1/10‬ه ـ افتتحــت‬\n      ‫اجللســة يف الســاعة ‪ 11 : 00‬وحضــر الطرفــان وبســؤال املدعــي عــن رده‬\n      ‫قــال لقــد أطلعــت علــى مذكــرة الدفــع املقدمــة مــن الشــركة املدعــى‬\n      ‫عليهــا ولــم اجــد فيهــا مــا يوجــب الــرد وقــرر الطرفــان أنهمــا ليــس لديهمــا‬\n      ‫مــا يرغبــان إضافتــه ثــم لتأمــل مــا مت ضبطــه ودراســته رفعــت اجللســة ويف‬\n      ‫يــوم الثالثــاء املوافــق ‪1433/4/13‬ه ـ افتتحــت اجللســة يف الســاعة ‪: 35‬‬\n      ‫‪ 10‬وفيهــا حضــر الطرفــان وطلبــت مــن املدعــى عليــه وكالــة أصــل‬\n      ‫العقــد بــن الطرفــن بهــذه القضيــة فاســتعد بإحضــاره وطلــب مهلــة‬\n      ‫فأجبتــه لطلبــه ويف يــوم الســبت املوافــق ‪1433/4/17‬ه ـ افتتحت اجللســة‬\n      ‫يف الســاعة ‪ 9 : 30‬وحضــر الطرفــان وقــدم املدعــى عليــه وكالــة العقــد‬\n      ‫بــن الطرفــن ونصــه ( بســم اهلل الرحمــن الرحيــم عقــد تأجيــر ســيارة‬\n      ‫احلمــد هلل وحــده وصلــى اهلل وســلم علــى رســول اهلل وعلــى آلــه وأصحابــه‬\n      ‫ومــن وااله وبعــد بعــون اهلل وتوفيقــه مت ابــرام هــذا العقــد بتاريــخ‬\n      ‫‪1429/7/11‬ه ـ املوافــق ‪2008/7/14‬م مبدينــة حائــل بــن كل مــن ‪-1‬‬\n      ‫املؤجــر شــركة ‪ .....‬للســيارات وهــي شــركه ســعودية ذات مســئولية‬\n      ‫محــدودة مبوجــب الســجل التجــاري رقــم ‪ ....‬ومركزهــا الرئيســي‬\n      ‫بالريــاض وعنوانهــا ص ب ‪ ....‬الريــاض ‪ ....‬وميثلهــا يف التوقيــع علــى هــذا‬\n      ‫العقــد ع‪ .....‬طــرف أول ‪ -2‬املســتأجر ‪ ....‬اجلنســية ســعودي املهنــة معلــم‬\n      ‫العنــوان حائــل ‪ ....‬رمــز البريــدي هاتــف املنزل ‪ .....‬هاتــف العمل‪ ...‬واجلوال‬\n      ‫‪ ...‬طــرف ثــان متهيــد حيــث أن الطــرف األول املؤجــر يتملــك الســيارة‬\n      ‫احملــدد نوعهــا ومواصفاتهــا أدنــاه نــوع الســيارة ‪ ....‬عــدد ‪ 3‬املوديــل‬\n      ‫‪2007‬م رقــم الهيــكل ‪ ....‬ذهبــي ‪ ....7‬ابيــض ‪ ....‬عنابــي ‪ ....7‬وحيــث أن‬\n      ‫الطــرف الثانــي «املســتأجر» قــد أبــدى رغبتــه يف اســتئجار الســيارة املبني‬\n\n\n‫‪231‬‬\n\f‫مواصفاتهــا أعالهــا والوفــاء بكامــل الشــروط وااللتزامــات الــواردة‬\n‫بهــذا العقــد ‪ .‬لــذا فقــد اتفــق الطرفــان وهمــا بكامــل أهليتهمــا املعتبــرة‬\n‫ـرعا علــى أن يقــوم املؤجــر بتأجيــر الســيارة احملــدد نوعهــا وكامــل‬      ‫شـ ً‬\n‫وفقــا للشــروط التاليــة‪ :‬أوالً‪ :‬يعتبــر‬\n                                        ‫مواصفاتهــا أعــاه علــى املســتأجر ً‬\n‫ثانيــا ‪ :‬مــدة‬\n           ‫ـزءا ال يتجــزأ مــن هــذا العقــد‪ً .‬‬  ‫التمهيــد املذكــور أعــاه جـ ً‬\n‫العقــد‪ :‬اتفــق الطرفــان علــى أن مــدة هــذا العقــد هــي ‪ 48‬شــهرا تبــدأ مــن‬\n‫‪2008/7/1‬م وينتهــي يف ‪2012/6/1‬م ثال ًثــا ‪ :‬يقــر املســتأجر بأنــه قــد‬\n‫عايــن الســيارة محــل هــذا العقــد معاينــة نافيــة للجهالــة واســتلمها مــن‬\n‫املؤجــر بحالــة جيــدة وقبلهــا بحالتهــا الراهنــة خاليــة مــن أي عيب وصاحلة‬\n‫للغــرض املســتأجرة مــن أجلــه ‪ .‬كمــا يقــر أنــه قــد مت تزويدهــا بــكل‬\n‫اإلضافــات املتفــق عليهــا وأنهــا قــد أصبحــت حتــت مســئوليته اخلاصــة من‬\n‫رابعــا ‪ :‬ملكيــة الســيارة‪ :‬يقــر املســتأجر مبعرفتــه أن‬ ‫تاريــخ هــذا العقــد ً‬\n‫العقــد هــو عقــد إيجــار ملــدة طويلــة وأن الســيارة ملــك للمؤجــر طــوال مــدة‬\n‫هــذا العقــد وليــس للمســتأجر حــق يف ملكيتهــا وال يحــق لــه بيعهــا أو‬\n‫هبتهــا إلــى أي طــرف ثالــث أو التصــرف فيهــا بــأي تصــرف ناقــل‬\n‫للملكيــة ‪ .‬كمــا أنهــا ال تعتبــر مــن أمالكــه التــي تــؤول إلــى الورثــة ‪.‬‬\n‫ولضمان ســداد األجرة يوافق املســتأجر على أن تبقى اســتمارة الســيارة‬\n‫لــدى املؤجــر وباســمه وكذلــك يكــون لــدى املؤجــر نســخة مــن املفاتيــح‬\n‫االحتياطيــة للســيارة لســحبها يف أي وقــت عنــد مخالفــة املســتأجر‬\n‫خامســا ‪ :‬قيمــة العقــد ‪5-1‬‬‫ً‬       ‫اللتزاماتــه اجلوهريــة احملــددة بهــذا العقــد‬\n‫يكــون مبلــغ إيجــار الســيارة طيلــة املــدة اجلــاري عليهــا التأجيــر مبلــغ‬\n‫‪ 165450‬ريــال ســعودي موزعــة علــى إيجــارات شــهرية وفــق مــا هــو مبــن‬\n‫يف هــذا العقــد‪ .‬وحيــث أن العقــد هــو عقــد تأجيــر ســيارة طويــل املــدى‬\n\n\n                                                                                       ‫‪232‬‬\n\f      ‫وقــد روعيــت فيــه تخفيــض قيمة األجرة عن األســعار الســائدة يف الســوق‬\n      ‫لطــول مدتــه ونظـ ًـرا ألن الســيارة يختلــف ســعرها مــن وقــت آلخــر حســب‬\n      ‫خصوصــا بعــد اســتعمالها مــن قبــل املســتأجر بحيــث يكــون‬     ‫ً‬          ‫حالتهــا‬\n      ‫مرتفعــا يف البدايــة وينخفــض بعــد اســتعمالها ‪ .‬وحيــث أن‬        ‫ً‬       ‫ســعرها‬\n      ‫املســتأجر ال يرغــب يف أن يدفــع قيمــة إيجــار مختلفــة مــن شــهر إلــى آخــر‬\n      ‫فقــد طلــب مــن املؤجــر توزيــع القيمــة اإليجاريــة الفعليــة علــى أقســاط‬\n      ‫شــهرية متســاوية بحيــث تتناســب مــع دخلــه الشــهري ‪ .‬لذا اتفــق الطرفان‬\n      ‫علــى ســداد القيمــة الفعليــة علــى النحــو التالــي‪ :‬توقيــع املســتأجر وتوقيــع‬\n      ‫الكفيــل الغــارم ‪ -‬دفعــة مقدمــة مــن مجموع القيمــة اإليجارية بالكامل‬\n      ‫مقدارهــا ‪ 12450‬ريــال يقــوم املســتأجر بدفعهــا عنــد التوقيــع علــى هــذا‬\n      ‫ـهرا تدفــع يف‬\n                   ‫العقــد‪ - .‬دفعــة إيجــار شــهري تبلــغ‪ 2700‬ريــال ملــدة ‪ 48‬شـ ً‬\n      ‫ـارا مــن ‪2008/7/1‬م ‪ -‬دفعــة‬     ‫اليــوم الثالثــن يف بدايــة كل شــهر اعتبـ ً‬\n      ‫أخيــرة مــن مــدة عقــد اإليجــار مقدارهــا ‪ 23400‬ريــال تســدد بتاريــخ‬\n      ‫اســتحقاق القســط األخيــر مــن هــذا العقــد‪ .‬وقــد قــام املســتأجر بالتوقيــع‬\n      ‫علــى ســندات ألمــر واجبــة الدفــع بعــدد الدفعــات الشــهرية املذكــورة‬\n      ‫والدفعــة األخيــرة‪ 2-5.‬يقــر املســتأجر ويوافــق علــى أن دفعــات القيمــة‬\n      ‫اإليجاريــة املبينــة أعــاه ال متثــل األجــرة الفعليــة يف حــاالت املــدد القصيرة‬\n      ‫حيــث روعــي فيهــا التخفيــض كمــا ذكــر أعــاه لطــول مــدة العقــد ‪.‬‬\n      ‫لذلــك فإنــه مــن املتفــق عليــه بــن الطرفــن أنــه إذا رغــب املســتأجر يف‬\n      ‫إنهــاء هــذا العقــد قبــل انتهــاء مدتــه وإعــادة الســيارة إلــى املؤجــر‪ ،‬أو يف‬\n      ‫حالــة رغبتــه يف اســتبدالها قبــل نهايــة العقــد أو عنــد نهايتــه‪ ،‬أو يف حالــة‬\n      ‫تعــرض الســيارة حلــادث ينتــج عنــه الهــاك أو التلــف الكلــي للســيارة‬\n      ‫(وفــق تقاريــر شــركة التأمــن) أو يف حالــة تعــرض الســيارة للســرقة‬\n\n\n‫‪233‬‬\n\f‫(بــدون إهمــال مــن املســتأجر ) فــإن املســتأجر يوافــق علــى احتســاب‬\n‫القيمــة اإليجاريــة الفعليــة الشــهرية وفــق اجلــدول االســتهالكي املرفــق‬\n‫ـزءا ال يتجــزأ منــه )‪.‬‬‫بهــذا العقــد (ملحــق رقــم) «‪ »1‬والــذي يعتبــر جـ ً‬\n‫سادســا ‪ :‬املســافات الزائــدة‪ :‬مــن املتفــق عليــه بــن الطرفــن أن املســافة‬‫ً‬\n‫املجانيــة التــي تقطعهــا الســيارة خــال مــدة هذا العقــد ‪ 2.500‬كيلومتر‬\n‫شــهرياً‪ .‬فــإذا رغــب املســتأجر يف إنهــاء العقــد وإعــادة الســيارة إلــى‬\n‫املؤجــر فــإن املؤجــر ســيقوم مبحاســبته عــن املســافة الزائــدة بواقــع ‪50‬‬\n‫ـابعا ‪ :‬الوعــد بالبيــع‪ :‬إذا التــزم‬\n                                   ‫هللــة عــن كل كيلــو متــر إضــايف‪ .‬سـ ً‬\n‫املســتأجر بســداد كامــل دفعــات األجــرة الشــهرية املتفــق عليهــا يف هــذا‬\n‫العقــد ورغــب يف متلــك الســيارة فــإن املؤجــر يلتــزم ببيــع الســيارة محــل‬\n‫هــذا العقــد للمســتأجر ونقــل ملكيتهــا لــه مقابــل األجــرة التــي دفعــت‬\n‫والدفعــة األخيــرة مــن العقــد ‪ .‬ويف هــذه احلالــة يتــم إنهــاء عقــد اإليجــار‬\n‫هــذا وحتريــر عقــد بيــع بــن الطرفــن ‪ .‬وبعــد إمتــام عقــد البيــع ودفــع‬\n‫القيمــة يقــوم املؤجــر بنقــل ملكيــة الســيارة للمشــتري علــى أن يدفــع‬\n‫املشــتري تكاليــف نقــل ملكيــة الســيارة باســمه لــدى اجلهــات املختصــة‬\n‫ثام ًنــا‪ :‬التزامــات املســتأجر‪ :‬يلتــزم املســتأجر طيلــة مــدة هــذا العقــد مبــا‬\n‫يلــي‪ -1 :‬أن يقــوم بدفــع مبلــغ اإليجــار الشــهري املتفــق عليهــا يف هــذا‬\n‫العقــد دون اعتبــار للحالــة الفنيــة للســيارة أو فتــرة تواجدهــا يف مراكــز‬\n‫اخلدمــة إن وجــدت هنــاك‪ ،‬فــإذا تأخــر املســتأجر عــن دفــع األجــرة ملــدة‬\n‫ـهرا وعشــرة‬‫شــهرين متتاليــن بالنســبة للعقــود التــي أطــول مــن ‪ 12‬شـ ً‬\n‫أيــام للعقــود األقــل مــن ذلــك‪ ،‬فــإن املســتأجر يعتبــر وكأنــه قــد أنهــى‬\n‫العقــد مــن قبلــه و يحــق للمؤجــر اســتنا ًدا إلــى ذلــك اإلنهــاء التعميــم علــى‬\n‫الســيارة لــدى اجلهــات املختصــة الســترجاعها دون أدنــى مســؤولية علــى‬\n\n\n                                                                                         ‫‪234‬‬\n\f      ‫املؤجــر عــن أي نتائــج مترتبــة علــى ذلــك التعميــم ‪.‬وعندهــا يحــق للمؤجــر‬\n      ‫مطالبــة املســتأجر بدفــع مبلــغ األجــرة املتأخــرة عــن الفتــرة الســابقة‬\n      ‫لتاريــخ ســحب الســيارة‪ ،‬وكذلــك دفــع نســبة اســتهالك الســيارة حيــث‬\n      ‫يتــم حســاب األجــرة عندهــا وفــق اجل ــدول االســتهالكي املرفــق بهــذا‬\n      ‫العقد مل ــحق رقم «‪ ،»1‬باإلض ــافة إلى مص ــاريف الس ــحب (‪ 250‬ريال‪/‬‬\n      ‫ســيارة) واي مصاريــف اخــري إن وجــدت‪ .‬ويتعهــد املســتأجر بــان ال‬\n      ‫يحتفــظ املســتأجر بــاي نقــود او اغــراض ثمينــة وأن ال يطالــب املؤجــر‬\n      ‫بــاي التزامــات كانــت داخــل الســيارة‪ -2 .‬أن يقــوم باســتخدام الســيارة‬\n      ‫بنفســه للغــرض املؤجــرة مــن أجلــه وهــو االســتخدام الشــخصي فقــط‪،‬‬\n      ‫وأن ال يســمح ملــن ال يحمــل رخصــة قيــادة ســارية املفعــول بقيادتهــا‪ .‬كمــا‬\n      ‫يلتــزم بــأن ال يعــرض الســيارة ألي خطــر بشــكل متعمــد أو يســتخدمها‬\n      ‫للتجــارب أو التدريــب أو الســباق أو األجــرة أو نقــل البضائــع‪ .‬ويجــوز لــه‬\n      ‫تفويــض غيــره بقيــادة الســيارة املســتأجرة بشــرط اســتخدام منــوذج‬\n      ‫التفويــض املعــد مــن شــركة ‪ .....‬للســيارات واملوافــق عليــه مــن قبــل‬\n      ‫جنائيــا‬\n         ‫ً‬      ‫الشــركة‪ -3 .‬أن يكــون مســؤوال عــن الســيارة محــل اإليجــار‬\n      ‫ومروريـ ًا وأن ال يقــوم بإعــادة تأجيرهــا أو إعارتهــا ألي طــرف ثالــث دون‬\n      ‫خطيــا علــى ذلــك ‪ .‬كمــا يتحمــل ا ملســتأجر كافــة‬     ‫ً‬      ‫موافقــة املؤجــر‬\n      ‫األضــرار والغرامــات املســجلة علــى الســيارة عــن أيــة مخالفــات مروريــة‬\n      ‫ألنظمــة املــرور املعمــول بهــا يف اململكــة أو يف الــدول التــي يســمح لــه مــن‬\n      ‫املؤجــر بقيــادة الســيارة فيهــا‪ -4 .‬أن يقــوم مبتابعــة الصيانــة الدوريــة‬\n      ‫للســيارة وفــق برنامــج الصيانــة لــدى الشــركة واملوضــح بكتيــب‬\n      ‫اإلرشــادات مــن الشــركة الصانعــة املرفــق بالســيارة ويقــوم علــى حســابه‬\n      ‫اخلــاص بتحمــل جميــع مصاريــف الســيارة مــن بنزيــن وتغييــر الزيــوت‬\n\n\n‫‪235‬‬\n\f‫والتشــحيم ومالحظــة مســتوى املــاء وهــواء اإلطــارات بانتظــام ‪ .‬ويف حالــة‬\n‫قيامــة بالصيانــة خــارج املــدن التــي بهــا فــروع للمؤجــر يلتــزم بــأن تكــون‬\n‫الصيانــة لــدى إحــدى و كالء جنــرال موتــورز املتواجديــن يف تلــك‬\n‫املنطقــة دون حتديــد مــا إذا كانــت اإلصالحــات مشــمولة بالضمــان‬\n‫الفنــي ‪ .‬ويف حالــة القيــام بإصالحــات غيــر مشــمولة بالضمــان الفنــي‬\n‫فــإن ذلــك يكــون علــى حســاب املســتأجر‪ -5 .‬أن يشــعر املؤجــر بــأي‬\n‫تغييــر يطــرأ علــى عنــوان ســكنه أو عملــه املــدون يف هــذا العقــد‪)6 .‬‬\n‫يلتــزم املســتأجر مبراجعــة املؤجــر قبــل نهايــة مدة‪/‬صالحيــة االســتمارة‬\n‫لفحــص الســيارة يف الفحــص الــدوري وجتديــد االســتمارة‪ .‬وتعتبــر‬\n‫نفقــات الفحــص والتجديــد علــى حســاب املســتأجر باعتبــاره هــو‬\n‫املســتخدم للســيارة واملســتفيد مــن تلــك اخلدمــات ‪ .‬وإذا تأخــر املســتأجر‬\n‫يف هــذا االلتــزام فإنــه يتحمــل كذلــك أيــة غرامــات تأخيــر قــد تفــرض‬\n‫مــن اجلهــات املختصــة‪ .‬توقيــع املســتأجر توقيــع الكفيــل الغــارم أن يعيــد‬\n‫الســيارة إلــى املؤجــر يف نهايــة العقــد ســليمة وبحالــة جيــدة بعــد إصــاح‬\n‫كل مــا يطــرأ عليهــا مــن أضــرار وحــوادث إذا كان ذلــك نتيجــة إهمــال‬\n‫أو تعمــد أو تقصيــر ‪ .‬فــإذا انتهــت مــدة هــذا العقــد ولــم يرغــب املســتأجر‬\n‫يف اســتعمال خيــار الشــراء ونقــل ملكيــة الســيارة باســمه‪ ،‬ولــم يعــد‬\n‫الســيارة فإنــه يلتــزم بتعويــض املؤجــر عــن كل يــوم يتأخــر فيــه بعــد‬\n‫تاريــخ انتهــاء العقــد مببلــغ ‪ 100‬ريــال عــن كل يــوم تأخيــر‪ .‬ويجــب أن‬\n‫تكــون الســيارة عنــد اإلعــادة شــاملة علــى كل التغييــرات واإلضافــات‬\n‫امللحقــة بالســيارة املذكــورة بهــذا العقــد إن وجــدت‪ ،‬وإذا ظهــرت أيــة‬\n‫طبقــا لســعرها لــدى املؤجــر ‪.‬‬\n                              ‫نواقــص فعلــى املســتأجر ســداد قيمتهــا ً‬\n‫وتعتبــر أيــة إضافــات زائــدة وضعهــا املســتأجر يف الســيارة مــن حــق‬\n\n\n                                                                                      ‫‪236‬‬\n\f      ‫املؤجــر دون عــوض‪ .‬تاسـ ًـعا ‪ :‬موقــع اإليجــار ‪ 9-1 :‬يحــق للمســتأجر‬\n      ‫مبوجــب هــذا العقــد اســتخدام الســيارة داخــل حــدود اململكــة العربيــة‬\n      ‫تفويضــا محــد ًدا لذلــك‪ .‬علــى أن يكــون‬\n                                             ‫ً‬         ‫الســعودية ويقــوم املؤجــر مبنحــة‬\n      ‫للمؤجــر حــق تقديــر مــدة التفويــض وظــروف منحــه‪ -2 .‬إذا رغــب‬\n      ‫املســتأجر يف قيــادة الســيارة خــارج حــدود اململكــة لزيــارة دول اخلليــج‬\n      ‫العربــي أو بعــض الــدول األخــرى فــإن عليــه تقــدمي طلــب بذلــك قبــل وقــت‬\n      ‫كاف للمؤجــر‪ .‬وللمؤجــر احلــق بحجــب هــذا التفويــض ألي ســبب وفــق‬\n      ‫تقديــره اخلــاص‪ .‬وإذا مت منــح التفويــض للمســتأجر فــإن عليــه احتــرام‬\n      ‫أنظمــة املــرور يف البلــدان التــي يســافر إليــه‪ .‬ويتحمــل املســتأجر كل مــا‬\n      ‫يلحــق الســيارة مــن رســوم أخــرى أو غرامــات يف الدولــة التــي يســافر‬\n      ‫إليهــا ووفــق أنظمتــه ا‪ .‬ويف حالــة حــدوث أي حــادث يدخــل ضمــن التأمني‬\n      ‫فــإن أي تعويــض يســتحق للســيارة مــن جــراء ذلــك احلــادث فهــو للمؤجــر‬\n      ‫عاشـ ًـرا ‪ :‬التأمــن علــى الســيارة‪ :‬إن الســيارة املؤجــرة مؤمــن عليهــا مــن‬\n      ‫قبــل املؤجــر مبوجــب بوليصــة تأمــن طوال مدة هذا العقــد ضد(احلوادث‬\n      ‫املروريــة واحلريــق والســرقة (الغيــر متعمــدة مــن املســتأجر ومــن غيــر‬\n      ‫إهمــال منــه أو مخالفــة لألنظمــة)‪ .‬وعلــى املســتأجر تطبيــق تعليمــات‬\n      ‫التأمــن التاليــة يف حالــة حــدوث حــادث للســيارة‪( )1 :‬إلحضــار تقريــر‬\n      ‫مفصــل عــن احلــادث وورقة‪/‬تقريــر املوافقــة علــى اإلصــاح مــن املــرور‬\n      ‫خــال فتــرة ال تتجــاوز خمســة أيــام مــن تاريــخ وقــوع احلــادث ‪ .‬وإذا جتــاوز‬\n      ‫املســتأجر هــذه املــدة فإنــه يتحمــل لوحــده مصاريــف اإلصــاح بالكامــل‬\n      ‫دون الرجــوع علــى املؤجــر‪)2 .‬عــدم التنــازل للغيــر يف تقريــر املــرور عــن أي‬\n      ‫حقــوق مقــررة للســيارة محــل هــذا العقــد ‪ .‬ويف حالــة تنــازل املســتأجر عــن‬\n      ‫أي حــق للســيارة فإنــه يتحمــل لوحــده كامــل املســؤولية الناجتــة عــن‬\n\n\n‫‪237‬‬\n\f‫احلــادث وعلــى نفقتــه اخلاصــة‪)3 .‬تزويــد الشــركة بصــورة ســارية املفعــول‬\n‫مــن رخصــة القيــادة‪)4 .‬يتعهــد املســتأجر بعــدم إصــاح مــن تلقــاء نفســه‬\n‫بــل يعهــد بهــا إلــى املؤجــر‪)5 .‬ســداد مبلــغ ألف وخمســمائة ريــال (‪)1.500‬‬\n‫متوســط رســم أي حــادث يتــم إصالحــه بواســطة املؤجــر‪ .‬باإلضافــة إلــى‬\n‫االلتــزام بــأي شــروط أخــرى تتطلبهــا شــركة التأمــن‪ .‬حــادي عشــر ‪:‬‬\n‫بنــود ال يشــملها التأمــن اتفــق الطرفــان علــى أن املســتأجر يتحمــل جميــع‬\n‫املصاريــف والتلفيــات التــي ال يشــملها التأمــن ‪ .‬ويعتبــر تقريــر املــرور هــو‬\n‫الوثيقــة الوحيــدة التــي حتــدد مســؤوليات احلــادث‪ .‬واألمــور التــي ال‬\n‫يشــملها التأمــن هــي‪ )1 :‬ال يشــمل التأمــن املقــدم مــن املؤجــر التأمــن‬\n‫الشــامل علــى ســائق وركاب الســيارة املؤجــرة ويتحمــل املســتأجر أيــة‬\n‫مســؤولية تتعلــق بهــذا املوضــوع‪ .‬وتكــون حــدود مســؤولية التأمــن يف‬\n‫هــذه الناحيــة فقــط مصاريــف طبيــة بواقــع خمســة آالف (‪ )5.000‬ريــال‬\n‫للشــخص الواحــد املصــاب يف الســيارة بحــد أقصــى عشــرون ألــف‬\n‫(‪ )20.000‬ريــال للحــادث الواحــد‪ .‬باإلضافــة إلــى مصاريــف ســحب‬\n‫الســيارة بحــد أقصــى مبلــغ خمســمائة ريــال (‪ )500‬مــن داخــل اململكــة‬\n‫ومبلــغ ألــف وخمســمائة (‪ )1.500‬ريــال مــن خــارج اململكــة‪)2 .‬كذلــك‬\n‫ال يشــمل التأمــن ســرقة أي قطعــة أو جتهيــزات إضافيــة للســيارة مثــل‬\n‫الراديــو‪ ،‬املســجل‪ ،‬البطاريــة‪ ،‬أجهــزة النقــال‪ ،‬الفيديــو ‪ ،. . .‬أو ســرقة‬\n‫أو فقــدان النقــود واألمتعــة الشــخصية للمســتأجر‪)3 .‬كذلــك ال يشــمل‬\n‫التأمــن مصاريــف ســحب الســيارة املصدومــة إلــى مركــز اخلدمــة‪)4 .‬‬\n‫أيض ـ ًا ال يشــمل التأمــن األضــرار الناجتــة عــن العوامــل التــي ال ميكــن‬\n‫الســيطرة عليهــا مثــل الــزالزل واألمطــار واحلــروب وأعمــال الشــغب‬\n‫والكــوارث الطبيعيــة‪ )5 .‬ال يشــمل التأمــن احلــوادث واألضــرار‬\n\n\n                                                                                      ‫‪238‬‬\n\f      ‫والتلفيــات الناجتــة عــن القيــادة يف حالــة الســكر واإلهمــال املتعمــد‪)6 .‬‬\n      ‫ال يشــمل التأمــن الرخصــة غيــر الســارية املفعــول أو التراخيــص املروريــة‬\n      ‫بالنســبة ملــن هــم أقــل مــن ‪ 18‬ســنة ‪ ،‬وكذلــك ملــن هــم أكثــر مــن خمســة‬\n      ‫وســتون ســنة‪ .‬ال يشــمل التأمــن ســرقة الســيارة بواســطة املســتأجر مــن‬\n      ‫شــركة تأجيــر الســيارات‪ .‬توقيــع املســتأجر توقيــع الكفيــل ثانــي‬\n      ‫عشــر‪ :‬الصيانــة‪ :‬مــن املتفــق عليــه أن الضمــان الفنــي للســيارات املؤجــرة‬\n      ‫مــن الشــركة تكــون علــى النحــو التالــي‪( :‬علمــا بــان الضمــان ال يشــمل‬\n      ‫أي إضافــات أو تعديــات يقــوم بهــا املســتأجر علــى املركبــة محــل‬\n      ‫اإليجــار)‪ .‬ســيارات جــي ام ســي وشــيفرولية بأنواعهــا ‪ 60000‬كيلــو‬\n      ‫متــر أو ‪ 3‬ســنوات ايهمــا اســبق باالنتهــاء ســيارات الكاديــاك بأنواعهــا‬\n      ‫‪ 100000‬أو ‪ 3‬ســنوات ايهمــا اســبق باالنتهــاء بالنســبة للســيارات‬\n      ‫املســتعملة)األفضلية ( فــإن الضمــان يختلــف مــن ســيارة ألخــرى ويكــون‬\n      ‫حســب االتفــاق اخلطــي بــن الطرفــن كمــا اتفــق الطرفــان علــى أن‬\n      ‫املؤجــر ال يتحمــل أجــور الصيانــة واإلصــاح الناجتــة عــن االســتعمال‬\n      ‫العــادي للســيار ة مــن قبــل املســتأجر‪ ،‬كمــا ال يحــق للمســتأجر مطالبــة‬\n      ‫املؤجــر بتأمــن ســيارة بديلة أثناء إجــراء أعمال الصيانة أو اإلصالحات‪.‬‬\n      ‫ثالــث عشــر ‪ :‬انتهــاء العقــد‪ ،‬ينتهــي عقــد اإليجــار بــأي حــال مــن احلــاالت‬\n                 ‫التالية‪ .1 .:‬عند انتهاء مدته وإعادة تسليم السيارة إلى املؤجر‪.‬‬\n      ‫‪ .2‬إذا اســتخدم املســتأجر خيــار الشــراء املمنــوح لــه مبوجــب املــادة‬\n      ‫«ســابعاً» مــن هــذا العقــد ومتلــك الســيارة‪ .3 .‬كذلــك ينتهــي العقــد إذا‬\n      ‫تعرضــت الســيارة حلــادث نتــج عنــه اعتبــار الســيارة يف حالــة هــاك وتلــف‬\n      ‫كلــي‪ ،‬أو ســرقت بــدون إهمــال أو تقصيــر مــن املســتأجر‪ ،‬ووافقــت‬\n      ‫شــركة التأمــن يف هاتــن احلالتــن علــى تعويــض املؤجــر عــن الســيارة‬\n\n\n‫‪239‬‬\n\f‫املذكــورة‪ ،‬ويف هــذه احلالــة يتــم حســاب قيمــة الســيارة وفــق اجلــدول‬\n‫االســتهالكي املبــن يف هــذا العقــد أعــاه واســتقطاع مبلــغ التعويــض‬\n‫الــوارد مــن شــركة التأمــن وإلــزام املســتأجر بفــرق القيمــة‪ .4 .‬ينتهــي‬\n‫العقــد بوفــاة املســتأجر وعلــى ورثتــه إعــادة الســيارة وســداد باقــي‬\n‫مســتحقات األجــرة‪ .‬علــى أنــه يجــوز لورثــة املســتأجر احللول محــل مورثهم‬\n‫واالســتمرار يف العقــد إذا طلبــوا ذلــك خــال شــهر واحــد مــن تاريــخ‬\n‫الوفــاة كتابــة ووافــق املؤجــر علــى ذلــك‪ .‬ويف هــذه احلالــة يجــب أن يتــم‬\n‫إجــراء التعديــل املطلــوب علــى العقــد كتابــة واســتكمال النمــاذج‬\n‫واألوراق الالزمــة‪ .‬رابــع عشــر‪ :‬حــل املنازعــات يقــر كل مــن الطرفــن أنه‬\n‫قــد اطلــع علــى هــذا العقــد وفهــم مــا يحتويــه وأنــه يقبــل بــكل شــروطه‬\n‫وأحكامــه ‪ .‬ويف حالــة حــدوث أي خــاف بــن الطرفــن يتعــذر حلــه‬\n‫بينهمــا بالطــرق الوديــة فــإن اخلــاف يحــال إلــى اجلهــات القضائيــة‬\n‫املختصــة باململكــة العربيــة الســعودية‪ .‬خامــس عشــر‪ :‬التحويــل ال يحــق‬\n‫للمســتأجر حتويــل هــذا العقــد إلــى الغيــر‪ .‬ســادس عشــر‪ :‬اإلخطــارات‬\n‫‪:‬تتــم اإلخطــارات املوجهــة بــن الطرفــن باليــد أو بالبريــد املســجل علــى‬\n‫العنــوان املبــن لــكل طــرف أمــام اســمه يف هــذه العقــد‪ .‬ســابع عشــر‪:‬‬\n‫التعديــل‪ :‬ال يجــوز تعديــل هــذا العقــد أو تغييــره أو الزيادة فيه إال مبوجب‬\n‫تعديــل مكتــوب متفــق عليــه بــن الطرفــن‪ .‬ثامــن عشــر ‪ :‬نســخ العقــد‪:‬‬\n‫يتــم حتريــر هــذا العقــد مــن نســختني باللغــة العربيــة بيــد كل طــرف‬\n‫نســخة منــه للعمــل مبوجبهــا‪ .‬املؤجــر شــركة ‪ .....‬للســيارات توقيعــه‬\n‫املســتأجر اســمه توقيعــه ) أ ‪ .‬ه ـ وقــد تصــادق عليــه الطرفــان ولكــون‬\n‫املدعــي مــن ضمــن طلباتــه يدعــي أن الشــركة تســببت يف عجــزه عــن‬\n‫عــاج ابنــه حتــى تــويف لــذا قــررت الكتابة لســمو أميــر املنطقة بتكليف‬\n\n\n                                                                                   ‫‪240‬‬\n\f      ‫جلنــة مــن مســتوى عــالٍ مــن اخلبــرة مكونــه من املــرور وفــرع وزارة التجارة‬\n      ‫والدفــاع املدنــي والشــرطة ورئيــس هيئــة النظــر وذلــك للتحقيــق يف‬\n      ‫القضيــة مــن جميــع جوانبهــا وإصــدار تقريــر يبــن فيــه حتديــد مســئولية‬\n      ‫الشــركة املدعــى عليهــا مــن عدمــه يف املســئولية املدعــى بهــا وحتــى‬\n      ‫ورود اجلــواب رفعــت اجللســة ويف يــوم األحــد املوافــق ‪1433/10/22‬ه ـ‬\n      ‫افتتحــت اجللســة يف الســاعة ‪ 9 : 30‬وفيهــا حضــر الطرفــان وكنــت قــد‬\n      ‫تلقيــت املعاملــة مــن صاحــب الســمو امللكــي أميــر منطقــة حائــل برقــم‬\n      ‫‪ 14369‬يف ‪1433/7/30‬ه ـ مرفقـ ًا بهــا تقريــر اللجنــة التــي قامت باملهمة‬\n      ‫وفــق خطابنــا رقــم ‪ 32554360‬يف ‪1433/4/18‬ه ـ الــوارد رفــق خطــاب‬\n      ‫مديــر شــرطة منطقــة حائــل رقــم ‪ 3022‬يف ‪1433/7/1‬ه ـ ونصــه ( تقرير‬\n      ‫للجنــة بتاريــخ ‪1433/6/23-22‬ه ـ بنــاء علــى برقيــة صاحــب الســمو‬\n      ‫امللكــي أميــر منطقــة حائــل حفظــه اهلل رقــم ‪ 9220‬واملؤرخــة يف‬\n      ‫‪1433/5/17‬ه ـ واملوجــه أساســها لســعادة مديــر شــرطة منطقــة حائــل‬\n      ‫املبنيــة علــى خطــاب رئيــس احملكمــة العامــة بحائــل رقــم ‪3255436‬‬\n      ‫واملــؤرخ يف ‪1433/4/18‬ه ـ املتعلقــة بدعــوى ‪ ...‬ســجل مدنــي رقــم ‪ ...‬ضــد‬\n      ‫شــركة ‪ .....‬بحائــل حيــث أن فضيلــة القاضــي ‪ ...‬أشــار بــأن املدعــي‬\n      ‫يدعــي علــى شــركة ‪ ...‬بأنــه اشــترى ســيارة بالتأجيــر املنتهــي بالتمليــك‬\n      ‫قيمتهــا خمســة وخمســون ألــف ومائــة وخمســون ريــال مقســطه علــى‬\n      ‫عــدد ‪ 48‬قســط ًا تبــدأ مــن ‪2008/7/1‬م وتنتهــي يف ‪2012/6/1‬م وكان‬\n      ‫منتظمـ ًا باألقســاط حتــى حصــل عليــه حــادث مــروري نتــج عنــه تلفيــات‬\n      ‫بالســيارة ثــم ســلمها للشــركة إلجــراء مــا يوجبــه العقــد بينهمــا فباعتهــا‬\n      ‫الشــركة دون علمــه مبــا يقــل عــن ثلــث قيمتهــا وزورا عليــه ورقــة بالعلــم‬\n      ‫والقبــول بالبيــع والتعهــد بدفــع باقــي متأخــرات العقــد فأضــروا بــه‬\n\n\n‫‪241‬‬\n\f‫ضــرار ًا متعمــد ًا منهــم ويطلــب املدعــي الــزام الشــركة تطبيــق العقــد‬\n‫وتعويضــه عــن الســيارة وتســببهم يف عجــزه عــن عــاج ابنــه حتــى تــويف‬\n‫وحيــث يــرى فضيلــة ناظــر القضيــة تكليــف جلنــة علــى مســتوى عــال مــن‬\n‫اخلبــرة والدرايــة مكونــه مــن إدارة املــرور والشــرطة والدفــاع املدنــي‬\n‫ووزارة التجــارة وهيئــة اخلبــراء باحملكمــة للتحقيــق بهــذه القضيــة مــن‬\n‫جميــع جوانبهــا وإصــدار تقريــر بــن فيــه حتديــد مســئولية الشــركة‬\n‫املدعــى عليهــا مــن عدمــه يف املســئولية املدعــي بهــا بعــد دراســة القضيــة‬\n‫دراســة متأنيــة تبــرا بهــا الذمــة حيــث أيــد ســموه ذلــك وإكمــال الــازم‬\n‫مبوجبــه فقــد اجتمعــت اللجنــة املشــكلة يف يــوم الســبت واألحــد املوافــق‬\n‫‪1433/6/23-22‬ه ـ وحيــث مت دراســة القضيــة مــن جميــع جوانبهــا‬\n‫وســماع اقــوال كل مــن املدعــي واملواطــن ‪ ...‬ســجل مدنــي رقــم ‪...‬‬\n‫والوكيــل الشــرعي لشــركة ‪ ...‬املواطــن ‪ ...‬ســجل مدنــي رقــم ‪ ...‬ومــن‬\n‫خــال الدارســة واملناقشــة او ًال تبــن ان عقــد التأمــن موقــع مــا بــن‬\n‫شــركة ‪ ....‬وشــركة ‪ ...‬حيــث قامــت شــركة ‪ ...‬بقبــول التفويــض املقدم‬\n‫مــن قبــل املدعــي لصالــح املواطــن ‪ ...‬بقيــادة الســيارة مــن نــوع اوبتــرا رقــم‬\n‫اللوحــة ‪ ...‬داخــل اململكــة حتــت مســئوليته الكاملــة حســب شــروط‬\n‫العقــد معــه ومبــا يتمشــى مــع النظــام علم ـ ًا بــأن الســيارة مومــن عليهــا‬\n‫رغــم أن ســنه أقــل مــن الســن احملــدد بالعقــد املبــرم بــن شــركة ‪....‬‬\n‫وشــركة التأمــن وبعــد وقــوع احلــادث اتضــح رفــض شــركة التأمــن‬\n‫لقبــول األوراق وبذلــك شــركة ‪ .....‬تتحمــل مســئولية إصــاح ســيارة‬\n‫املدعــي او تعويضــه عــن قيمتهــا قبــل وقــوع احلــادث بســبب قبولهــا‬\n‫التفويــض بــدون أخــذ موافقــة مســبقة مــن شــركة التأمــن ملــن تقــل‬\n‫اعمارهــم عــن واحــد وعشــرون ســنه حســب العقــد املبــرم بخصــوص‬\n\n\n                                                                                         ‫‪242‬‬\n\f      ‫ذلــك وذلــك لألدلــة التاليــة ‪ -1‬مــا جــاء بأقــوال املدعــي ‪ -2‬ما جــاء بصورة‬\n      ‫التفويــض مــن الشــركة للمواطــن ‪ .....‬واملوضــح باللفــة رقــم ‪ 79‬املتضمــن‬\n      ‫التفويــض بقيــادة الســيارة أوبتــرا رقــم اللوحــة ‪ -4 . .....‬رفــض شــركة‬\n      ‫التأمــن لــأوراق اخلاصــة باحلــادث كــون املفــوض يقــل عمــره عــن ثمانيــة‬\n      ‫عشــر عامـ ًا ومخالــف لالتفــاق املبــرم بــن شــركة ‪ ....‬وشــركة التأمــن‬\n      ‫‪ -5‬مــا ورد بأقــوال الوكيــل الشــرعي لشــركة ‪ ....‬املتضمــن التفويــض‬\n      ‫مت قبولــه بعــد تاريــخ احلــادث ثانيـ ًا تــرى اللجنــة بخصــوص مــا يطالــب بــه‬\n      ‫املدعــي بشــأن وفــاة أبنــه لشــركة ‪ ....‬فــإن الشــركة ال تتحمــل ذلــك‬\n      ‫لكونــه أبــرم عقــد لعــدد ثــاث ســيارات مــن الشــركة تلــف منهــا اثنــان‬\n      ‫واألخــرى يقــوم باســتخدامها ثالث ـ ًا تــرى اللجنــة مبــا يتعلــق مبطالباتــه‬\n      ‫بالتعويــض مالي ـ ًا مــن جــراء مراجعاتــه بخصــوص الدعــوى ومــا حلــق بــه‬\n      ‫مــن اضــرار حســب ادعائــه فــإن اللجنــة تــرى نظــر ذلــك مــن قبــل فضيلــة‬\n      ‫ناظــر القضيــة هــذا مــا مت التوصــل أليــه مــن قبــل اعضــاء اللجنــة وبــاهلل‬\n      ‫التوفيــق منــدوب فــرع وزارة التجــارة ‪ ...‬توقيعــه منــدوب شــرطة منطقــة‬\n      ‫حائــل ‪ ...‬توقيعــه منــدوب منطقــة حائــل مقــدم ‪ ...‬توقيعــه منــدوب هيئــة‬\n      ‫اخلبــراء باحملكمــة العامــة ‪ ....‬توقيعــه منــدوب الدفــاع املدنــي مبنطقــة‬\n      ‫حائــل رائــد ‪ ...‬توقيعــه أ ‪.‬ه ـ وبعــرض تقريــر اللجنــة علــى الطرفــن قــررا‬\n      ‫رغبتهمــا يف تقــدمي ردود ًا علــى التقريــر وطلبــا موعــد جلســة ال يقــل عــن‬\n      ‫شــهر فأجبتهمــا لطلبهمــا ورفعــت اجللســة ويف يــوم االثنــن املوافــق‬\n      ‫‪1433/11/22‬ه ـ افتتحــت اجللســة يف الســاعة ‪ 9 : 46‬وفيهــا حضــر‬\n      ‫الطرفــان وقــدم املدعــي رد ًا هــذا نصــه (ال يوجــد لــدي رد لفضيلتكــم‬\n      ‫فالقضيــة واضحــه باألدلــة التــي أمامكــم ولكــن ارغب مــن فضيلتكم‬\n      ‫ســؤال الوكيــل الشــرعي ‪ .....‬هــل كان يعمــل يف فــرع شــركة ‪.....‬‬\n\n\n‫‪243‬‬\n\f‫بحائــل بتاريــخ ‪1430/4/30‬ه ـ علمـ ًا بأنــه كان ال يعمل بالفرع وســؤالي‬\n‫تأكيــد ًا ملعلومــة هــي باألســاس مؤكــده وهــي إيجــاد مخــرج للشــركة‬\n‫للخــروج بأقــل التكاليــف فكيــف يقــول الوكيــل الشــرعي بــأن‬\n‫التفويــض حــرر وقــت حــدوث احلــادث وهــو غيــر موجــود بالشــركة‬\n‫أساس ـ ًا والــذي حــرر التفويــض مشــرف التحصيــل الســابق ‪ ....‬والــذي‬\n‫كان أســاس املشــكلة وســفر خــروج نهائــي مباشــرة بعــد رفــع القضيــة‬\n‫للجهــات املختصــة وهــذا فقــط توضيــح لفضيلتكــم مبــا تقــوم بــه‬\n‫الشــركة مــن محــاوالت لتعطيــل القضيــة وعــدم إعطــاء احلــق ملــن‬\n‫يســتحقه ) أ ‪.‬ه ـ وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال ليــس لــي‬\n‫رد عليــه كمــا قــدم املدعــى عليــه وكالــة رد ًا هــذا نصــه ( ردا علــى مــا‬\n‫جــاء بقــرار اللجنــة التــي شــكلت وتلــي علينــا مــن فضيلتكــم والــذي‬\n‫رأت اللجنــة إلــزام الشــركة بنــاء علــى بنــود التأمــن ونــص تفويــض‬\n‫القيــادة دون النظــر يف تاريــخ وقــوع احلــادث وتاريــخ التفويــض حيــث أن‬\n‫التفويض بقيادة الســيارة للشــهر الذي وقع فيه احلادث شــهر ‪1430/4‬هـ‬\n‫بالتحديــد لــم يقدمــه املدعــي احلــادث وقــع بتاريــخ ‪1430/4/22‬ه ـ‬\n‫والتفويــض محــل الدعــوى منــح اعتبــارا مــن ‪1430/5/1‬ه ـ ملــدة شــهر‬\n‫واحــد فقــط بعــد احلــادث بثمانيــة ايــام تفاويــض القيــادة تختــم وتوقــع‬\n‫شــهريا حســب أنظمــة وسياســة الشــركة بعــد ســداد األجــرة للســيارات‬\n‫املســتأجرة ويتــم التأكــد مــن الســدد حســب إيصــال الســداد الســيارة مت‬\n‫اســتالم أوراق احلــادث للشــركة لتقديــر تكاليــف احلــادث بتاريــخ‬\n‫‪1430/6/16‬ه ـ عــن طريــق مكتــب ‪ ...‬لتأجيــر الســيارات حســب صــور‬\n‫أوراق الصيانــة بالشــركة املرفقــة ولــم تدخــل باســم املســتأجر نفســه‬\n‫مــع أن جميــع األوراق املطلوبــة مــن تســعيرات للحــادث بعــد املعــارض قــد‬\n\n\n                                                                                   ‫‪244‬‬\n\f      ‫مت إنهــاء اجراءاتهــا بتاريــخ ‪1430/4/25‬ه ـ ونرفــق لفضيلتكــم صــورة‬\n      ‫مــن ورقــة تعهــد موقعــة مــن العميــل عنــد توقيــع العقــد تنــص أن للشــركة‬\n      ‫احلــق يف ســحب الســيارة إذا تأخــر العميــل أســبوع واحــد تفويــض مطلــق‬\n      ‫وشــامل وغيــر قابــل لإللغــاء ومــع العلــم أن العميــل كان متأخــر بالســداد‬\n      ‫بتاريــخ الورقــة التــي يــدى بهــا التزويــر ألكثــر مــن شــهرين مــن تاريــخ‬\n      ‫‪1430/1/18‬ه ـ إلــى ‪1430/4/16‬ه ـ علــى مــا تقــدم نطلــب مــن‬\n      ‫فضيلتكــم إلزامــه بإحضــار ورقــة التفويــض التــي تســبق هــذه الورقــة‬\n      ‫لألشــهر مــا قبــل ‪1430/5/1‬ه ـ للتأكــد مــن كان املفــوض بقيــادة‬\n      ‫الســيارة وقــت احلــادث حتديــد ًا والســام عليكــم ) أ ‪ .‬ه ـ كمــا ارفــق مــع‬\n      ‫الــرد صــورة ســند علــى مطبوعــات شــركة ‪ .....‬رقــم بــدون وتاريــخ بــدون‬\n      ‫ونصــه ( توكيــل بعــدم التوقــف عــن الســداد أو أطلــب تأجيــل أو إعفائــي‬\n      ‫مــن تســديد أي قســط ألي ســبب كان علم ـ ًا بــأن رواتبــي الشــهرية‬\n      ‫تصــرف يف نهايــة كل شــهر هجــري والتــزم بســداد أ ول قســط بتاريــخ‬\n      ‫‪2008/7/1‬م مــن شــهر ‪ 7‬مــن عــام ‪2008‬م ومبوجــب هــذا التعهــد أفــوض‬\n      ‫شــركة ‪ .....‬للســيارات تفويــض مطلــق وشــامل غيــر قابــل لإللغــاء يف‬\n      ‫ســحب الســيارة منــي يف حالــة تأخــري ملــدة أســبوع عــن ســداد أي قســط‬\n      ‫يف أي وقــت ويف أي مــكان دون إشــعار أو إنــذار ســابق لــي كمــا التــزم‬\n      ‫بعــدم وضــع أيــة أشــياء أو ممتلــكات داخــل الســيارة مــن قبلــي أو مــن‬\n      ‫قبــل اآلخريــن ملعرفتــي التامــة واملســبقة بــأن شــركة ‪ .....‬ســوف تقــوم‬\n      ‫باســترجاع الســيارة يف حالــة تأخــري عــن ســداد أي قســط ) أ ‪ .‬ه ـ‬\n      ‫وبعــرض ذلــك علــى املدعــي قــال إن ردي علــى هــذا الدفــع هــو أن اإلقــرار‬\n      ‫املنســوب لــي بتوكيــل ‪ .....‬املرصــود مــزور علــي وأنكــر صحتــه كمــا‬\n      ‫أنكــر صحــة توقيعــي عليــه هكــذا قــرر ثــم قــرر الطرفــان أن ليــس ألي‬\n\n\n‫‪245‬‬\n\f‫منهمــا رد اضــايف لــذا فقــد قــررت رفــع اجللســة لتأمــل مــا أســتجد مــن‬\n‫ضبــط ودفــوع ورفعــت اجللســة ويف يــوم االربعاء املوافــق ‪1433/12/29‬هـ‬\n‫افتتحــت اجللســة يف الســاعة ‪ 9 : 17‬وفيهــا حضــر الطرفــان وجــرى ســؤال‬\n‫طــريف القضيــة عــن تاريــخ اســتالم الســيارة مبوجــب محضــر التســليم‬\n‫واملبالــغ التــي وصلــت مــن قيمــة الســيارة واملبالــغ املتبقيــة وتاريــخ حصــول‬\n‫احلــادث واملبلــغ املســتحق فيمــا لــو مت تســديد قيمــة الســيارة يف تاريــخ‬\n‫حصــول احلــادث وتقديــر الســيارة قبــل احلــادث وبعدهــا واملبلــغ املســتحق‬\n‫مــن التأمــن فيمــا لــو كانــت شــروط التأمــن منطبقــة فطلــب الطرفــان‬\n‫مهلــة للــرد عليهــا ورفعــت اجللســة ويف يــوم االثنــن املوافــق ‪1434/2/4‬ه ـ‬\n‫افتتحــت اجللســة يف الســاعة ‪ 11 : 56‬وحضــر الطرفــان وقــرر املدعــى‬\n‫عليــه وكالــة أن تاريــخ اســتالم املدعــي للســيارة يف ‪1429/7/11‬ه ـ وأن‬\n‫قيمــة أيجــار الســيارة اجمــا ًال مبلغ ـ ًا قــدره خمســة وخمســون الف ـ ًا ومئــة‬\n‫وخمســون ريــا ًال وقــد ســدد املدعــى عليــه منهــا مبلغـ ًا قــدره عشــرة االف‬\n‫واربعمائــة وخمســون ريــا ًال وبقــي يف ذمتــه مبلغ ـ ًا قــدره اربعــة واربعــون‬\n‫الف ـ ًا وســبعمائة ريــال كمــا أن تاريــخ احلــادث كان يف ‪1430/4/22‬ه ـ‬\n‫كمــا أن الســيارة لــو كانــت ســليمة يف وقــت احلــادث وأراد املدعــي‬\n‫تســليم املبلــغ املتبقــي فإنــه مبوجــب نظــام الشــركة مبــا يســمى تصفيــة‬\n‫تعجيــل الدفــع يكــون املتبقــي يف ذمــة املدعــي مبلغـ ًا قــدره اربعــة وثالثون‬\n‫الف ـ ًا وثالثمائــة وتســعة عشــر ريــا ًال كمــا أن املبلــغ املفتــرض للتعويــض‬\n‫عــن احلــادث فيمــا لــو مت قبــول احلــادث مــن قبــل شــركة التأمــن مقارنــة‬\n‫بســيارة ســبقتها بأحــد عشــر يوم ـ ًا فقــط وبنفــس املواصفــات التابعــة‬\n‫للمدعــي مبلغ ـ ًا قــدره اثنــان وثالثــون ألف ـ ًا وأربعمائــة وواحــد وخمســون‬\n‫ريــا ًال كمــا أن الســيارة مت بيعهــا مــن قبــل الشــركة وقيمــة الســيارة قبــل‬\n\n\n                                                                                       ‫‪246‬‬\n\f      ‫احلــادث وبعــده مــن ثالثــة معــارض عــن طريــق املــرور معــرض ‪...‬قبــل‬\n      ‫احلــادث مبلغــا قــدره ثالثــون الــف ريــال ومعــرض ‪ ....‬مبلغ ـ ًا قــدره ثمانيــة‬\n      ‫وعشــرون الــف ريــال ومعــرض ‪ ....‬مبلغــا قــدره ســبعة وعشــرون الــف ريــال‬\n      ‫وبعــد احلــادث قــدرة املعــارض الثالثــة الســيارة مبلغ ـ ًا قــدره عشــرة االف‬\n      ‫ريــال وبعــرض ذلــك علــى املدعــي ‪ .....‬علــى جميــع مــا قــرره املدعــى عليــه‬\n      ‫وكالــة جملــة وتفصيــا ثــم حــدد موعــدا للنطــق باحلكــم يــوم األحــد‬\n      ‫املوافــق ‪1434/02/10‬ه ـ الســاعة ‪ 08 : 30‬ورفعــت اجللســة ويف يــوم‬\n      ‫االحــد املوافــق ‪1434/2/10‬ه ـ افتتحــت اجللســة يف الســاعة ‪9 : 00‬‬\n      ‫وحضــر الطرفــان وقــرر املدعــي أن الســيارة عندمــا كانــت باســتالمه‬\n      ‫فــإن احلــادث قــد حصــل مــع طــرف آخــر وقــرر املــرور أن نســبة اخلطــأ‬\n      ‫عليــه أي علــى املدعــي بنســبة ‪ %100‬وأنــه قنــع بهذه النســبة كما تصادق‬\n      ‫الطرفــان أن الســيارة مت اســتالمها مــن قبــل الشــركة بعــد احلــادث يف‬\n      ‫‪1430/6/16‬ه ـ ومت بيعهــا يف ‪1430/7/1‬ه ـ وكنــت قــد تأملت القضية‬\n      ‫ودرســتها وحيــث أن املدعــي يطالــب شــركة ‪ .....‬بتعويضــه بســيارة‬\n      ‫مماثلــة وحتميلهــم أضــرار بيــع الســيارة دون قيمتهــا وأجــرة الســيارة التــي‬\n      ‫حتملهــا بســببهم طيلــة القضيــة وتســببهم يف عجــزه عــن عــاج ابنــه حتــى‬\n      ‫تــويف وأن وكيــل الشــركة املدعــى عليهــا قــدم رده املكتــوب مضمونــه‬\n      ‫أن الشــركة ملتزمــة مبــا جــاء يف العقــد وأن الشــركة غيــر مســئولة‬\n      ‫عمــا جــاء يف دعــوى املدعــي وحيــث مت تكليــف جلنــة حســب مــا هــو‬\n      ‫ا وتوصلــت اللجنــة إلــى حتميــل شــركة ‪.....‬‬      ‫مــدون يف ضبطــه تفصي ـ ً‬\n      ‫مســئولية إصــاح ســيارة املدعــي أو تعويضــه عــن قيمتهــا حيــث قبلــت‬\n      ‫الشــركة التعويــض أمــام شــركة التأمــن كمــا خلصــت اللجنــة إلــى‬\n      ‫أن الشــركة املدعــى عليهــا ال تتحمــل مــا يتعلــق مبــا ذكــره مــن تســببهم‬\n\n\n‫‪247‬‬\n\f‫يف وفــاة أبنــه وأن باقــي طلبــه حقوقــه من األضرار راجــع للنظر القضائي‬\n‫وقــد ظهــر لــي مــا يلــي أو ًال فــإن العقــد بــن الطرفــن إيجــار مــع وعــد‬\n‫بالبيــع وهــو املســمى باإليجــار املنتهــي بالتمليــك ومبــا أن حقيقــة هــذا‬\n‫العقــد شــرع ًا فيمــا ظهــر لــي بيــع برهــن والثمــن مؤجــل يســدد علــى‬\n‫أقســاط لــذا فــإن الــذي يجــري عليــه أحــكام البيــع برهــن مــن ذلــك حــق‬\n‫املدعــى عليــه يف متلــك الســيارة وحــق املدعــي يف توثيــق الديــن بالعــن‬\n‫وحقــه يف الثمــن علــى املدعــي ألن العبــرة يف العقــود باملقاصــد واملعانــي‬\n‫ال باأللفــاظ كمــا أن يف تكييــف هــذا التعامــل اإليجــار املنتهــي‬\n‫بالتمليــك بأنــه بيــع يف رهــن ضمــان حلقــوق املتعاملــن مــن التالعــب فــا‬\n‫يغــرر بشــخص بالدخــول يف عقــد تأجيــر مــع وعــد بيــع ثــم يحــرم منــه‬\n‫وقــد ســدد الثمــن أو أكثــره بحجــة أنــه إيجــار ال بيــع وســد الذرائــع‬\n‫املؤديــة للفســاد وأكل احلقــوق مقصــد معتبــر يف الشــرع وال مينــع مــن‬\n‫كــون ذلــك بيــع برهــن بقــاء العــن يف يــد املشــتري وعــدم قبــض الرهــن‬\n‫وهــو قــول مالــك وروايــة عــن أحمــد وهــو املذهــب عنــد أبــن عقيــل وغيــره‬\n‫قــال القاضــي هــذا قــول أصحابنــا وقــال الفخــر بــن تيميــة هــذا أشــهر‬\n‫الروايتــن وأفتــى بــه الشــيخ عبدالرحمــن البابطــن يف العقــار ونحــوه‬\n‫وأفتــى بــه الشــيخ حســن بــن حســن وأختــاره الشــيخ أبــن ســعدي يف الــدرر‬\n‫الســنية م ‪4 /‬ج ‪ 5‬صفحــة ‪ 127‬و ‪ 129‬واملختــارات اجلليــة صفحــة ‪ 187‬و‬\n‫‪ 181‬و ‪ 180‬والفتــاوى صفحــة ‪256‬وكالهمــا ألبــن ســعدي وحيــث‬\n‫تصــادق الطرفــان علــى أن األقســاط املتبقيــة للشــركة املدعــى عليهــا‬\n‫مبلغـ ًا قــدره أربعــة وأربعــون ألفـ ًا وســبعمائة ريــال وأن األقســاط املتبقيــة‬\n‫مبلغ ـ ًا قــدره أربعــة وثالثــون ألف ـ ًا وثالثمائــة وتســعة عشــر ريــا ًال وهــو‬\n‫تصفيــة تعجيــل الدفــع وأن املبلــغ املتوقــع للتعويــض عــن احلــادث مــن‬\n\n\n                                                                                        ‫‪248‬‬\n\f      ‫شــركة التأمــن فيمــا لــو مت قبولهــا مبلغ ـ ًا قــدره أثنــان وثالثــون الف ـ ًا‬\n      ‫وأربعمائــة وواحــد وخمســون ريــا ًال وإن الســيارة قــدرت بعــد احلــادث مــن‬\n      ‫ثالثــة معــارض هــم ‪ ..... ..... .....‬بعشــرة آالف ريــال وحيــث أن الشــركة‬\n      ‫تصرفــت يف الســيارة وباعتهــا لــذا فتكــون ضامنــة لهــا كمــا أنهــا‬\n      ‫تســببت يف تفويــت التعويــض املســتحق للمدعــي وحيــث تقــرر أن العقــد‬\n      ‫بيــع وأن الســيارة يف احلقيقــة ملــك ًا للمدعــي وحيــث أن التأجيــل يف‬\n      ‫األقســاط أمنــا هــو ألجــل تســديد األقســاط حســب املــدة املتفــق عليهــا‬\n      ‫وحيــث أن الشــركة حقهــا يف األقســاط حتــى نهايتهــا إمنــا هــو يف‬\n      ‫اكتمــال املــدة وقــد تبــن أن الشــركة قــد اســتلمت الســيارة بعــد احلادث‬\n      ‫وأبقــت الســيارة لديهــا مــن أجــل مــا يقتضيــه العقــد ثــم باعــت الســيارة‬\n      ‫دون الرجــوع إلــى املدعــي وقــد تقــرر أن العقــد بيع برهــن فيطبق أحكام‬\n      ‫املغصــوب علــى الســيارة وأن املســتحق لهــم حســب إقرارهــم ومصادقــة‬\n      ‫املدعــي علــى ذلــك مبلغ ـ ُا قــدره اربعــة وثالثــون الف ـ ًا وثالثمائــة وتســعة‬\n      ‫عشــر ريــا ًال فيكــون املســتحق للمدعــي قيمــة الســيارة بعــد احلــادث‬\n      ‫مبلغـ ًا قــدره عشــرة االف ريــال زائــد ًا مبلــغ التعويــض املتوقــع وقــدره اثنــان‬\n      ‫وثالثــون الــف وثالثمائــة وتســعة عشــر ريــا ًال ويخصــم منــه األقســاط‬\n      ‫املســتحقة للشــركة مبلغ ـ ًا قــدره أربعــة وثالثــون الف ـ ًا وثالثمائــة وتســعة‬\n      ‫عشــر ريــا ًال ويكــون النــاجت مبلغ ـ ًا قــدره ثمانيــة آالف ومائــة واثنــان‬\n      ‫وثالثــون ريــا ًال هــي املســتحقة للمدعــي وأمــا مطالبتــه بأضــرار ببيــع‬\n      ‫الســيارة دون قيمتهــا وأجــرة الســيارة التــي حتملهــا بســبب الشــركة‬\n      ‫طيلــة القضيــة وتســببهم يف عجــزه عــن عــاج ابنــه حتــى تــويف فلــم يظهــر‬\n      ‫لنــا توجههــا ألن حقــه يف رفــع الضــرر وقــد مت رفعــه بإعطائــه مــا يســتحق‬\n      ‫ولهــذا نظائــر عنــد العلمــاء حيــث نــص ســماحة املفتــي الســابق الشــيخ‬\n\n\n‫‪249‬‬\n\f‫محمــد بــن إبراهيــم‪ :‬ال يتحمــل مــا ينفقــه املصــاب املتســبب علــى املجنــي‬\n‫عليــه مــدة مرضــه فتــاوى الشــيخ محمــد بــن إبراهيــم ‪ 341‬و ‪ 342‬اجلــزء‬\n‫(‪ )11‬واملدعــي قــد ســلم الســيارة للشــركة بســبب احلــادث وتصرفــت‬\n‫الشــركة بهــا ومت احلكــم لــه بقيمــة الســيارة بعــد احلــادث مــع الضمــان‬\n‫املســتحق لــه الــذي تســببت الشــركة يف تفويتــه وحيــث أن منافــع‬\n‫املغصــوب مضمونــه والغاصــب يضمــن أجــرة املغصــوب الــذي جــرت‬\n‫العــادة بتأجيلــه إلــى حــن رده أو تلفــه شــرح املنتهــى ‪ 403/2‬و ‪421‬‬\n‫والكشــاف ‪ 187/4‬ولذلــك كلــه فقــد قــررت أو ًال ألــزام الشــركة‬\n‫املدعــى عليهــا بتســليم املدعــي مبلغ ـ ًا قــدره ثمانيــة األف ومئــة وأثنــان‬\n‫وثالثــون ريــا ًال ثاني ـ ًا صرفــت النظــر عــن باقــي مــا يطالــب بــه املدعــي‬\n‫وبــكل مــا تقــدم حكمــت وأفهمــت املدعــي بــأن لــه مطالبــة الشــركة‬\n‫بأجــرة الســيارة مــدة بقائهــا عنــد الشــركة مــن اســتالمها بتاريــخ‬\n‫‪1430/6/16‬ه ـ وحتــى بيعهــا يف ‪1430/7/1‬ه ـ وبإعــان احلكــم قــرر‬\n‫الطرفــان عــدم القناعــة واســتعدا بتقــدمي الئحــة فأفهمــا بــأن مــدة‬\n‫االعتــراض قدرهــا ثالثــون يوم ـ ًا تبــدأ بعــد مهلــة اســتالم الصــك وأن‬\n‫عليهمــا املراجعــة يف يــوم الســبت املوافــق ‪1434/2/16‬ه ـ الســاعة‬\n‫الواحــدة ظهــر ًا الســتالم صــورة الصــك وإذا مضــت املــدة ولــم يقدمــا‬\n‫اعتراضهمــا خاللهــا فــإن احلكــم يكتســب القطعيــة ويكــون بات ـ ًا‬\n‫واجــب النفــاذ ففهمــا ذلــك ورفعــت اجللســة يف الســاعة ‪ 9 : 21‬وعليــه‬\n‫حصــل التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وآلــه وصحبــه‬\n                                             ‫اجمعني حرر يف ‪1434/2/10‬هـ ‪.‬‬\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 3460333‬وتاريــخ‬\n                                                          ‫‪1434/3/11‬هــ‪.‬‬\n\n\n                                                                                      ‫‪250‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":218,"source_page_end":250,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cd1627afb1b2cffa933719ebca63ee280020e5003ba7e13ec6ec1852dd6521e5","normalized_text_hash":"b7a1221bf6bae1e47c17729af6074cd26b618e25f0b699a4cb6e0637a2150ac0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p218-3438433"},{"id":"e4823d3e-ae53-51c1-ada2-0eda4a5d6bd3","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -عقار -شراء قطعة أرض من مورث القاصر حال حياته - إقرار ولي القاصر بصحه الدعوى -قبول شهادة املدعى عليه يف حق القاصر -القضاء بالشاهد واليمن -ثبوت شراء املدعي للعقار","document_number":"3451723","case_number":"3499120","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/1","year":"1434","subject":"بيع -عقار -شراء قطعة أرض من مورث القاصر حال حياته - إقرار ولي القاصر بصحه الدعوى -قبول شهادة املدعى عليه يف حق القاصر -القضاء بالشاهد واليمن -ثبوت شراء املدعي للعقار","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/3/1 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3451723 :‬‬\n                          ‫َر ْق ُم الدعوى‪3499120 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34955041‬تاريخه‪1434/5/14 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬عقــار‪ -‬شــراء قطعــة أرض مــن مــورث القاصــر حــال حياتــه ‪-‬‬\n      ‫إقــرار ولــي القاصــر بصحــه الدعــوى ‪ -‬قبــول شــهادة املدعــى عليــه يف‬\n      ‫حــق القاصــر‪ -‬القضــاء بالشــاهد واليمــن ‪ -‬ثبــوت شــراء املدعــي للعقــار‬\n                                                                ‫موضــع الدعــوى ‪.‬‬\n\n\n\n\n      ‫مــا رواه مســلم يف صحيحــه أن النبــي صلــى اهلل عليــه وســلم قضــى‬\n                                                         ‫بشــاهد وميــن ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بأنــه اشــترى مــن مــورث املدعــى عليهــم قطعــه أرض‬\n      ‫(ذكــر وصفهــا) حــال حياتــه وأنــه ســلمه جــزء مــن قيمــة األرض واجلــزء‬\n      ‫املتبقــي ســلمه لوكيــل الورثــة بعــد مــوت املــورث ‪ ،‬طلــب املدعــى احلكــم‬\n      ‫بنقــل ملكيــه العقــار املذكــور لــه ‪ ،‬أقــر املدعــى عليــه أصالــة ووكالــة‬\n      ‫مبــا جــاء يف دعــوى املدعــى ‪ ،‬شــهد املدعــى عليــه أصالــة ووكالــة بصحة‬\n      ‫الدعــوى ‪ ،‬جــرى تعديــل املدعــى عليــه ‪ ،‬حلــف املدعــي اليمــن تكملــة‬\n      ‫لبينتــه ‪ ،‬صــدر احلكــم بثبــوت شــراء املدعــي للعقــار موضــع الدعــوى‬\n      ‫مــن مــورث املدعــى عليهــم وتســليم ثمنــه ‪ ،‬والتهميــش علــى صــك امللــك‬\n      ‫بذلــك بعــد اكتســاب احلكــم القطعيــة ‪ ،‬رفعــت املعاملــة حملكمــة‬\n\n‫‪251‬‬\n\f‫االســتئناف حيــث إن مــن ضمــن املدعــى عليهــم قاصــرة ‪ ،‬صــدق احلكــم‬\n                                             ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا د‪ )....( .‬القاضــي باحملكمــة العامــة‬\n‫بالريــاض بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض املســاعد برقــم ‪ 3499120‬يف ‪1434/2/30‬ه ـ‬\n‫املقيــدة برقــم ‪ 34514642‬يف ‪1434/2/30‬ه ـ يف يــوم األحــد املوافــق‬\n‫‪1434/3/1‬ه ـ افتتحــت اجللســة الســاعة ‪ 10.15‬وفيهــا حضــر املدعــي‬\n‫‪ ...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪...‬وادعــى علــى احلاضــر معــه‬\n‫‪ ...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪...‬أصالــة عــن نفســه وبصفتــه‬\n‫ا عــن ‪ ...‬أصالــة عــن نفســها وبصفتهــا وليــة علــى ابنتهــا ‪...‬‬    ‫وكي ـ ً‬\n‫مبوجــب صــك الواليــة الصــادر مــن هــذه احملكمــة برقــم ‪ 28/19‬يف‬\n‫‪1429/9/1‬ه ـ وذلــك مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل‬\n‫الثانيــة بجنــوب الريــاض رقــم ‪ 72645‬يف ‪1429/9/1‬ه ـ والتــي تخولــه‬\n‫يف املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإقامــة الدعــوى ولــه حــق‬\n‫البيــع والشــراء واإلفــراغ وقبولــه ‪ ،‬قائــا يف دعــواه عليــه ‪ :‬لقــد اشــتريت‬\n‫ا عنهــم قطعــة األرض رقــم‬     ‫مــن مــورث املدعــى عليــه ومــن هــو وكي ـ ً‬\n‫‪ 1208‬مــن املخطــط ‪ 3200‬الواقعــة يف حــي املصفــاة بالريــاض وحدودهــا‬\n‫وأطوالهــا شــما ًال ‪ :‬قطعــة األرض رقــم ‪ 1209‬بطــول خمســة وثالثــن متــرا‬\n‫‪ ،‬وجنوبــا قطعــة رقــم ‪ 1207‬بطــول خمســة وثالثــن متر ًا ‪ ،‬وشــرق ًا قطعة‬\n‫رقــم ‪ 1203‬بطــول ســبعة عشــر متــر ًا وأربعــة عشــر ســنتيمتر ًا ‪ ،‬وغرب ـ ًا‬\n‫شــارع عــرض ‪15‬م بطــول ســبعة عشــر متــر ًا وأربعــة عشــر ســنتيمتر ًا ‪،‬‬\n\n                                                                                    ‫‪252‬‬\n\f      ‫ومجمــوع مســاحتها خمســمائة وتســعة وتســعني متــر ًا مربع ـ ًا وتســعني‬\n      ‫ســنتيمتر ًا ‪ ،‬واململوكــة لــه مبوجــب الصــك الصــادر مــن كتابــة العــدل‬\n      ‫األولــى بالريــاض برقــم ‪ 13/71216‬يف ‪1424/11/7‬ه ـ وذلــك يف عــام‬\n      ‫‪1428‬ه ـ وذلــك بقيمــة إجماليــة قدرهــا ثالثــون ألــف ريــال دفعــت منهــا‬\n      ‫أربعــة وعشــرين ألــف ريــال نقــد ًا ملــورث املدعــى عليهــم ‪ ...‬حــال حياتــه‬\n      ‫‪ ،‬والباقــي وقــدره ســتة آالف ريــال ســلمتها نقــد ًا للمدعــى عليــه احلاضــر‬\n      ‫بعــد وفــاة مورثهــم ‪ ،‬أطلــب احلكــم بنقــل ملكيــة العقــار املذكــور لــي‬\n      ‫ا ‪ :‬إن مــا ذكــره‬  ‫‪ ،‬هكــذا ادعــى‪ ،‬وبســؤال املدعــى عليــه أجــاب قائ ـ ً‬\n      ‫ا ‪ ،‬وقــد أبلغنــي والــدي قبــل وفاتــه‬ ‫املدعــي كلــه صحيــح جملــة وتفصيـ ً‬\n      ‫بذلــك وأشــهد بذلــك ‪ ،‬وال مانــع لــدى الورثــة مــن نقــل ملكيــة العقــار‬\n      ‫للمدعــي متــى مــا صــدر حكــم بذلــك بــراءة لذمــة مورثنــا ‪ ،‬حيــث أن‬\n      ‫أحــد الورثــة قاصــرة وهــي ‪ ،...‬كمــا أبــرز صــك حصــر ورثــة ‪ ...‬الصــادر‬\n      ‫مــن هــذه احملكمــة برقــم ‪ 30/100/385‬يف ‪1429/8/29‬ه ـ املجلــد‬\n      ‫رقــم ‪ 30/7‬املتضمــن وفاتــه يف ‪1429/8/22‬ه ـ وانحصــار ورثتــه يف‬\n      ‫زوجتــه ‪...‬ويف ابنــه ‪...‬وابنتــه ‪...‬املولــودة يف ‪1427/2/23‬ه ـ ‪ ،‬كمــا أبــرز‬\n      ‫صــك الواليــة علــى ‪...‬الصــادر مــن هــذه احملكمــة برقــم ‪ 18/19‬يف‬\n      ‫‪1429/9/1‬ه ـ املتضمــن إقامــة والدتهــا ‪...‬وليــة عليهــا ‪ ،‬وباالطــاع عليها‬\n      ‫وجدتهــا مطابقــة ملــا ذكــره ‪ ،‬وبطلــب البينــة مــن املدعــي قــال ‪ :‬بينتــي‬\n      ‫هــي إقــرار املدعــى عليــه احلاضــر وشــهادته بــأن والــده قــد أبلغــه ببيــع‬\n      ‫األرض املذكــورة لــي حــال حياتــه وأنــه اســتلم مــن القيمــة مبلــغ وقــدره‬\n      ‫أربعــة وعشــرون ألــف ريــال نقــد ًا ‪ ،‬وكذلــك إقــراره باســتالمه للباقــي‬\n      ‫وقــدره ســتة آالف ريــال نقــد ًا منــي بعــد وفــاة مورثــه ‪ ،‬هكــذا أجــاب ‪،‬‬\n      ‫وبســؤاله هــل لديــه زيــادة بينــة قــال ‪ :‬ليــس لــدي زيــادة بينــة ‪ ،‬فطلبــت منــه‬\n\n\n‫‪253‬‬\n\f‫تعديــل املدعــى عليــه فأحضــر كال مــن ‪... :‬ســعودي مبوجــب الســجل‬\n‫املدنــي رقــم ‪...‬و ‪...‬ســعودي مبوجــب الســجل املدنــي رقــم ‪...‬فشــهدا بعدالــة‬\n‫وثقــة املدعــى عليــه ‪ ،‬وبعــرض ميــن االســتظهار علــى املدعــي تقويــة للبينة‬\n‫ا ‪ :‬واهلل العظيــم إنني‬            ‫قــال‪ :‬ال مانــع لــدي مــن أداء اليمــن ‪ ،‬ثــم حلــف قائـ ً‬\n‫قــد اشــتريت األرض املذكــورة يف الدعــوى مــن مــورث املدعــى عليهــم‬\n‫‪...‬حــال حياتــه مببلــغ وقــدره ثالثــون ألــف ريــال ســلمت منهــا لــه نقــد ًا‬\n‫أربعــة وعشــرون ألــف ريــال ‪ ،‬والباقــي وقــدره ســتة آالف ريــال ســلمتها‬\n‫نقــد ًا للمدعــى عليــه احلاضــر بعــد وفــاة مورثهــم ‪ ،‬هكــذا حلــف ‪ ،‬كمــا‬\n‫جــرى االطــاع علــى صــك العقــار املذكــور فوجــدت يف أعــاه أنــه‬\n‫ســاري املفعــول يف ‪1434/02/17‬ه ـ ‪ ،‬فبنــاء علــى مــا تقــدم مــن الدعــوى‬\n‫واإلجابــة وحيــث صــادق املدعــى عليــه علــى دعــوى املدعــي وشــهد بهــا‬\n  ‫ا ‪َ ،‬وقَ ــدْ ثَبـ َـت ( َأ َّن ال َّن ِبــي ‪َ -‬ص َّلــى َّ ُ‬\n‫الل‬                                                            ‫وأنــه اســتلم مبلــغ الشــراء كام ـ ً‬\n                   ‫َّ‬                         ‫َ‬\n‫ن ) ‪َ .‬ر َو ُاه ُمسـل ٌِم ‪ ،‬وألن املدعــي حلــف‬               ‫َع َليـ ِه َو َسـل ََّم ‪ -‬قَ َضــى ِب َشــاهِ دٍ َو َ ِيـ ٍ‬\n‫ميــن االســتظهار فقــد ثبــت لــدي شــراء املدعــي العقــار املذكــور أعــاه‬\n‫مــن مــورث املدعــى عليهــم وتســليمه أربعــة وعشــرين ألــف ريــال نقــد ًا‬\n‫ملورثهــم وســتة آالف ريــال نقــد ًا للمدعــى عليــه ‪ ،‬وأمــرت برفــع كامــل‬\n‫املعاملــة حملكمــة االســتئناف وبعــد تصديقــه ســيتم التهميــش مبوجبــه‬\n‫علــى صــك العقــار وســجله ‪ ،‬ورفعــت اجللســة الســاعة ‪ ، 10.45‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                                                   ‫حــرر يف ‪1434/3/1‬ه ـ‬\n‫ويف يــوم األحــد املوافق‪1434/05/19‬ه ـ افتتحــت اجللســة الســاعة‬\n‫‪ 10.15‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف بالريــاض‬\n‫برقــم ‪ 34955041‬يف ‪1434/5/14‬ه ـ مرفــق بهــا قــرار الدائــرة الثانيــة‬\n\n\n                                                                                                                            ‫‪254‬‬\n\f      ‫لألحــوال الشــخصية واإلنهــاءات رقــم ‪ 34196714‬يف ‪1434/4/24‬ه ـ‬\n      ‫املتضمــن ‪ :‬املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬قاضــي اســتئناف‬\n      ‫‪ ...‬ختمــه وتوقيعــه قاضــي اســتئناف ‪...‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n      ‫‪...‬ختمــه وتوقيعــه أ‪.‬ه ـ وحتــى ال يخفــى جــرى حتريــره ‪ ،‬وبــاهلل التوفيــق‪،‬‬\n      ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪ 1434/05/19‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض املســاعد برقــم ‪ 34514642‬وتاريــخ ‪1434/4/9‬ه ـ املرفــق بهــا‬\n      ‫الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ... /‬املســجل‬\n      ‫برقــم ‪ 3451723‬وتاريــخ ‪1434/3/1‬ه ـ اخلــاص بدعــوى‪... /‬ضــد‪... /‬‬\n      ‫بشــأن إفــراغ العقــار املوضــح بالصــك ‪ ،‬وقــد تضمــن الصــك حكــم‬\n      ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى احلكــم ‪ ،‬واهلل املوفــق‬\n                       ‫وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪255‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":251,"source_page_end":255,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b4445be13956ae82de773c00a335257da4bd0b7a0242ab0e873f713b8f03f708","normalized_text_hash":"8bb6a94de6c5a19682ec27098dd0d8029ba3e6d5ac70d6139ef432d751842ae5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p251-3451723"},{"id":"98f26839-ab21-5f43-95a1-c57a70653b25","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع أغنام -املطالبة بقيمة املبيع حللول موعد السداد -إثبات احلق بالقرائن واليمن املكملة -احلكم بسداد ثمن املبيع .","document_number":"34200343","case_number":"3458017","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالطائف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/29","year":"1434","subject":"بيع أغنام -املطالبة بقيمة املبيع حللول موعد السداد -إثبات احلق بالقرائن واليمن املكملة -احلكم بسداد ثمن املبيع .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/29 :‬هـ‬\n                ‫ُ‬                 ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34200343 :‬‬\n                    ‫َر ْق ُم الدعوى‪3458017 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34284082‬تاريخه‪1434/8/1 :‬هـ‬\n\n\n‫بيــع أغنــام ‪ -‬املطالبــة بقيمــة املبيــع حللــول موعــد الســداد ‪ -‬إثبــات‬\n    ‫احلــق بالقرائــن واليمــن املكملــة ‪ -‬احلكــم بســداد ثمــن املبيــع ‪.‬‬\n\n\n\n\n‫‪ -1‬ذكــر ابــن قدامــة رحمــه اهلل يف الــكايف (‪ )128/6‬مــا نصــه‪« :‬فــإن‬\n‫امتنــع اخلصــم مــن احلضــور عنــد احلاكــم حكــم عليــه ألنــه لــو لــم‬\n‫يحكــم عليــه جلعــل االمتنــاع واالســتتار طريق ـ ًا لتضييــع احلقــوق»‪.‬‬\n‫‪ -2‬ذكــر أبــو إســحاق إبراهيــم بــن حســن يف كتابــه معــن احلــكام علــى‬\n‫القضايــا واألحــكام مــا نصــه « مســألة قــال املــاوردي يف تفســير قولــه‬\n‫تعالــى «وإذا دعــوا إلــى اهلل ورســوله ليحكــم بينهــم» اآليــة دليــل علــى‬\n‫أنــه مــن دعــي إلــى حاكــم مــن حــكام املســلمني فعليــه اإلجابــة ويحــرج‬\n                                                                   ‫إن تأخــر)‪.‬‬\n‫‪ -3‬مــا ورد عــن احلســن بــن علــي رضــي اهلل عنهمــا أن النبــي صلــى اهلل‬\n‫عليــه وســلم قــال (مــن دعــي إلــى حاكــم مــن حــكام املســلمني ولــم يجــب‬\n                                                    ‫فهــو ظالــم ال حــق لــه)‪.‬‬\n        ‫‪ -4‬املادة (‪ )55‬من نظام املرافعات الشرعية والئحته التنفيذية ‪.‬‬\n\n\n\n‫ادعــى املدعــي بــأن املدعــى عليــه اشــترى منــه عــدد ًا مــن األغنــام ولــم‬\n‫يســدد لــه أي شــيء مــن ثمنهــا بعــد حلــول موعــد أدائــه‪ ،‬لــذا طلــب إلــزام‬\n                                                                                     ‫‪256‬‬\n\f      ‫املدعــى عليــه بســداد ثمنهــا حــاالً‪ ،‬املدعــى عليــه لــم يحضــر رغــم تبلغــه‬\n      ‫باحلضــور لــذا فقــد طلبــت احملكمــة بينــة املدعــي فأبــرز كمبيالــة مــن‬\n      ‫املدعــى عليــه تتضمــن التزامــه باملبلــغ املدعــى بــه للمدعــي كمــا طلبــت‬\n      ‫احملكمــة منــه اليمــن علــى صحــة دعــواه فأداهــا طبــق مــا طلــب منــه‪،‬‬\n      ‫املدعــى عليــه لــم يحضــر رغــم تبلغــه باحلضــور ولــم يقــدم عــذرا لعــدم‬\n      ‫احلضــور كمــا لــم يقــدم دفاعــه علــى هــذه الدعــوى واملدعــي تقــوى‬\n      ‫جانبــه مبــا قدمــه مــن بينــة كمــا أنــه حلــف اليمــن التــي طلبــت منــه ‪،‬‬\n      ‫قضــت احملكمــة بإلــزام املدعــى عليــه أن يدفــع للمدعــي املبلــغ املدعــى‬\n                     ‫بــه ‪ ،‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة العامــة‬\n      ‫بالطائــف وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة املســاعد بالطائــف برقــم ‪ 3458017‬وتاريــخ ‪1434/02/04‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34289712‬وتاريــخ ‪1434/02/04‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافق‪1434/03/07‬ه ـ افتتحــت اجللســة الســاعة ‪11: 00‬‬\n      ‫وفيهــا حضــر املدعــي (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫ا عنــه ولــم يقــدم عــذر ًا‬\n                                  ‫رقــم (‪ )........‬ولــم يحضــر املدعــى عليــه وال وكيـ ً‬\n      ‫عــن عــدم حضــوره ولــم يردنــا مــن قســم احملضريــن مــا يفيــد تبلغــه‬\n      ‫مبوعــد اجللســة لــذا قــررت رفــع اجللســة وإعــادة تبليــغ املدعــى عليــه ويف‬\n      ‫جلســة أخــرى حضــر املدعــي (‪ )........‬ســعودي اجلنســية مبوجــب الهويــة‬\n      ‫الوطنيــة رقــم (‪ )........‬الصــادرة مــن أحــوال الطائــف ولــم يحضــر املدعــى‬\n      ‫عليــه وال مــن ينــوب عنــه ولــم يقــدم عــذرا عــن عــدم حضــوره ولــم يردنــا‬\n\n‫‪257‬‬\n\f‫خطــاب قســم محضــري اخلصــوم باإلفــادة هــل املدعــى عليــه تبلــغ أم ال‬\n‫؟ وقــد وردنــا مــا يفيــد تبليــغ املدعــى عليــه لشــخصه مبوعــد اجللســة‬\n‫املاضيــة بخطــاب مديــر عــام التربيــة والتعليــم مبحافظــة الطائــف رقــم‬\n‫‪ 34311725‬يف ‪1434 /2/10‬هــ‪ ،‬واســتناد ًا للمــادة اخلامســة واخلمســن‬\n‫مــن نظــام املرافعــات الشــرعية رفعــت اجللســة ويف جلســة أخــرى أفتحــت‬\n‫اجللســة يف متــام الســاعة التاســعة والنصــف صباحـ ًا وفيهــا حضــر املدعــي‬\n‫(‪ )........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم (‪ )........‬ولــم‬\n‫ا عنــه وال مــن ينــوب عنــه ولــم يقــدم‬     ‫يحضــر املدعــى عليــه وال وكي ـ ً‬\n‫عــذر ًا عــن عــدم احلضــور وقــد وردنــا خطــاب مديــر عــام التربيــة والتعليــم‬\n‫بالطائــف رقــم ‪ 34579937‬يف‪1434/3/8‬ه ـ واملتضمــن‪( :‬تبليــغ املدعــى‬\n‫عليــه مبوعــد اجللســة املاضيــة لشــخصه) ‪ ،‬ثــم طلبــت مــن املدعــي حتريــر‬\n‫دعــواه فادعــى قائ ـاً‪ :‬إننــي أدعــي علــى الغائــب عــن مجلــس احلكــم‬\n‫الشــرعي املدعــو (‪ )........‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة‬\n‫رقــم (‪ )........‬حيــث إنــه يف شــهر ‪ 9‬مــن عــام ‪1433‬ه ـ تقريبـ ًا اشــترى منــي‬\n‫عــدد ســتة عشــر رأس ـ ًا مــن الغنــم مــن نــوع طليــان حريــة بثمــن الــرأس‬\n‫الواحــد ألــف وخمســمائة ريــال واملجمــوع مبلــغ قــدره أربعــة وعشــرون‬\n‫ألــف ريــال علــى أن يســددني كامــل الثمــن بتاريــخ ‪1434/1/30‬ه ـ إال‬\n‫أن املدعــى عليــه لــم يســدد حتــى اآلن أي شــيء مــن هــذا املبلــغ وهــي حالــة‬\n‫األداء لــذا أطلــب إلــزام املدعــى عليــه بســداد هــذا املبلــغ لــي حــا ًال هــذه‬\n‫دعــواي‪ ،‬وبطلــب البينــة مــن املدعــي أبــرز لنــا كمبيالــة برقــم ‪10628‬‬\n‫بتاريــخ ‪1433/9/17‬ه ـ صــادرة مــن معــرض (‪. )........‬ت‪4323087/1‬‬\n‫باســم املديــن مبلــغ الكمبيالــة أربعــة وعشــرون ألــف ريــال ال غيــر تاريــخ‬\n‫االســتحقاق يف ‪1434/1/30‬ه ـ ثــم طلبــت مــن املدعــي اليمــن علــى‬\n\n\n                                                                                         ‫‪258‬‬\n\f      ‫ا (واهلل العظيــم الــذي ال إلــه‬   ‫صحــة دعــواه فاســتعد بهــا وحلــف قائ ـ ً‬\n      ‫إال هــو الــذي يعلــم اجلهــر ومــا يخفــى ويعلــم خائنــة األعــن ومــا تخفــي‬\n      ‫الصــدور إن اشــترى منــي عــدد ســتة عشــر رأس مــن الغنــم ثمنهــا أربعــة‬\n      ‫وعشــرون ألــف ريــال واتفقــت معــه علــى أن يكــون الســداد يف تاريــخ‬\n      ‫‪1434/1/30‬ه ـ وهــي حالــة األداء اآلن ولــم يصلنــي منهــا شــيء ولــم‬\n      ‫أبرئــه منهــا أي شــيء واهلل واهلل واهلل‪ ).‬هكــذا حلــف فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واســتنادا علــى املــادة اخلامســة واخلمســن مــن نظــام‬\n      ‫املرافعــات الشــرعية ولوائحهــا التنفيذيــة ومبــا أن املدعــى عليــه لــم‬\n      ‫يحضــر ولــم يقــدم عــذرا عــن ســبب عــدم احلضــور ولــم يقــدم دفاعــه علــى‬\n      ‫هــذه الدعــوى مــع أنــه تبلــغ بهــا حســب التعليمــات ‪ ،‬ومبــا أن املدعــي‬\n      ‫أبــرز الكمبيالــة وحلــف اليمــن التــي طلبــت منــه ‪ ،‬وعــدم حضــور‬\n      ‫املدعــى عليــه وهــذه قرائــن تقــوي جانــب املدعــي وقــد ذكــر ابــن قدامــه‬\n      ‫رحمــه اهلل تعالــى يف كتابــه الــكايف ‪ 128/6‬مــا نصــه (فــإن امتنــع‬\n      ‫اخلصــم مــن احلضــور عنــد احلاكــم حكــم عليــه ألنــه لــو لــم يحكــم‬\n      ‫عليــه جلعــل االمتنــاع واالســتتار طريقــا لتضييــع احلقــوق ) اهــ‪ .‬وقــد ذكــر‬\n      ‫أبــو إســحاق إبراهيــم بــن حســن يف كتابــه معــن احلــكام علــى القضايــا‬\n      ‫واألحــكام مــا نصــه (مســالة قــال املــاوردي يف تفســير قولــه تعالــى (وإذا‬\n      ‫دعــوا إلــى اهلل ورســوله ليحكــم بينهــم )اآليــة دليــل علــى أنــه مــن دعــي‬\n      ‫إلــى حاكــم مــن حــكام املســلمني فعليــه اإلجابــة ويحــرج إن تأخــر وقــد‬\n      ‫ورد عــن احلســن بــن علــي رضــي اهلل عنهمــا أن النبــي صلــى اهلل عليــه قــال‬\n      ‫(مــن دعــي إلــى حاكــم مــن حــكام املســلمني ولــم يجــب فهــو ظالــم ال‬\n      ‫حــق لــه ) اهــ‪ ،‬لذلــك كلــه فقــد حكمــت بإلــزام املدعــى عليــه الغائــب‬\n      ‫عــن مجلــس احلكــم الشــرعي أن يدفــع للمدعــي مبلــغ أربعــة وعشــرين‬\n\n\n‫‪259‬‬\n\f‫ألــف ريــال حــاال هــذا مــا ظهــر لــي وبــه حكمــت ‪ ،‬وقــررت بعــث نســخة‬\n‫مــن صــك احلكــم للمدعــى عليــه ليقــدم اعتراضــه خــال ثالثــن يوم ـ ًا‬\n‫مــن تاريــخ التبليــغ باحلكــم وإذا لــم يقــدم اعتراضــه خاللهــا فيســقط‬\n‫حقــه يف االعتــراض ويكتســب احلكــم القطعيــة‪ ،‬وكان اختتــام‬\n‫هــذه اجللســة يف متــام الســاعة العاشــرة صباح ـاً‪ ،‬وبــاهلل التوفيــق وصلــى‬\n‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪ ،‬حــرر يف‬\n                                                            ‫‪1434/4/27‬هــ‪.‬‬\n‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد ‪:‬‬\n‫ثــم عــادت املعاملــة مــن محكمــة االســتئناف مبكــة املكرمــة مصادقـ ًا‬\n‫عليهــا بالقــرار رقــم ‪34284082‬يف ‪1434/8/1‬ه ـ ونصــه احلمــد هلل‬\n‫والصــاة والســام علــى رســول اهلل وبعــد فقــد جــرى اطالعنــا نحــن‬\n‫رئيــس عضــوي الدائــرة احلقوقيــة الرابعــة يف محكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة علــى الصك الصادر من فضيلة الشــيخ (‪)........‬‬\n‫القاضــي باحملكمــة العامــة بالطائــف واملســجل بعــدد ‪34200343‬‬\n‫وتاريــخ ‪1434/4/29‬ه ـ املتضمــن دعــوى ضــد(‪ )........‬واحملكــوم فيــه‬\n‫مبــا دون باطنــه وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫تقــرر املوافقــة علــى احلكــم وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم قاضــي اســتئناف ختــم وتوقيــع‪ .‬قاضــي اســتئناف (‪)........‬‬\n‫ختــم وتوقيــع‪ .‬رئيــس الدائــرة موقــع يف االصــل وموافــق علــى احلكــم‬\n‫ومجــاز ‪ .‬وصلــى اهلل وســلم علــى نبينــا محمــد ‪.‬حــرر يف ‪1434/8/14‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪260‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":256,"source_page_end":260,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"13521853caf09c9cc1fbfcf836cab199baf8bc86288e8b10b8fc4fa8f027a591","normalized_text_hash":"92a73cb710b5ab7ee70ff0bb1f8d68f25e4265ca4e17a21c4ee8e910d34cf344","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p256-34200343"},{"id":"133222ef-9cc2-5691-9a0b-b176e17f760e","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -بيع إبل بثمن آجل -سماع الدعوى غيابيا لعدم حضور املدعى عليه -شهادة الشاهد العدل شرع ا وحلف اليمن -اإللزام بدفع باقي مبلغ املبايعة -الغائب على حجته متى حضر .","document_number":"34272302","case_number":"3469186","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملويه","circuit":"الدائرة احلقوقية اخلامسة رقم 34339440وتاريخ 1434/10/25ه","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/18","year":"1434","subject":"بيع -بيع إبل بثمن آجل -سماع الدعوى غيابيا لعدم حضور املدعى عليه -شهادة الشاهد العدل شرع ا وحلف اليمن -اإللزام بدفع باقي مبلغ املبايعة -الغائب على حجته متى حضر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/18 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34272302 :‬‬\n                          ‫َر ْق ُم الدعوى‪3469186 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34377010‬تاريخه‪1434/12/3 :‬هـ‬\n\n\n      ‫بيــع ‪ -‬بيــع إبــل بثمــن آجــل ‪ -‬ســماع الدعــوى غيابيــا لعــدم حضــور‬\n      ‫املدعــى عليــه ‪ -‬شــهادة الشــاهد العــدل شــرع ًا وحلــف اليمــن ‪ -‬اإللــزام‬\n             ‫بدفــع باقــي مبلــغ املبايعــة‪ -‬الغائــب علــى حجتــه متــى حضــر ‪.‬‬\n\n\n\n\n      ‫‪ -‬حديــث ابــن عبــاس رضــي اهلل عنهمــا إن النبــي صلــى اهلل عليــه وســلم‬\n                                                ‫قضــى بيمــن وشــاهد رواه مســلم‪.‬‬\n                             ‫‪ -‬املادة ‪ 5/176‬و ‪178‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n      ‫ادعــى املدعــي أنــه بــاع للمدعــى عليــه عــدد ثمــان مــن اإلبــل ذكــر‬\n      ‫قيمتهــا ‪ ،‬علــى أن تســدد بعــد شــهرين ‪ ،‬حــل األجــل ولــم يســدد املدعــى‬\n      ‫عليــه ســوى جــزء مــن املبلــغ ‪ ،‬طلــب املدعــى إلــزام املدعــى عليــه بدفــع‬\n      ‫املبلــغ املتبقــي ‪ ،‬تخلــف املدعــى عليــه عــن احلضــور ‪ ،‬احضــر املدعــي‬\n      ‫شــاهد ًا جــرى تعديلــه وحلــف املدعــي اليمــن تكملــة لبينتــه ‪ ،‬بنــاء علــى‬\n      ‫مــا ســبق مــن الدعــوى ولشــهادة الشــاهد املعــدل شــرعا وحللــف املدعــي‬\n      ‫اليمــن تكملــة لبينتــه وملــا رواه ابــن عبــاس رضــي اهلل عنهمــا أن النبــي‬\n      ‫صلــى اهلل عليــه وســلم قضــى بيمــن وشــاهد رواه مســلم ‪ ،‬صــدر احلكــم‬\n      ‫بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه ‪ ،‬الغائــب علــى حجتــه متــى‬\n                              ‫حضــر ‪ -‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n‫‪261‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬رئيــس احملكمــة العامــة‬\n‫باملويــه وبنــاء علــى املعاملــة الــواردة لنــا مــن قســم االحــاالت باحملكمــة‬\n‫برقــم ‪ 3469186‬وتاريــخ ‪1434/02/11‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 34348035‬وتاريــخ ‪1434/02/11‬ه ـ ففــي يــوم الثالثــاء‬\n‫املوافــق‪ 1434/02/26‬ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬وفيهــا‬\n‫حضــر ‪ ..........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪..........‬‬\n‫ولــم يحضــر املدعــى عليــه ‪ .............‬ولــم تردنــا افــادة مــن مديــر مركــز‬\n‫شــرطة رضــوان علــى خطابنــا رقــم ‪ 34/64‬يف ‪1434 /1/21‬ه ـ بشــأن‬\n‫تبلــغ املدعــى عليــه مــن عدمــه لــذا قــررت تأجيــل اجللســة إلبــاغ املدعــى‬\n‫عليــه باحلضــور ويف جلســة اخــرى حضــر املدعــي ولــم يحضــر املدعــى‬\n‫عليــه وقــد وردنــا صــورة خطــاب مديــر مركــز شــرطة ‪ ......‬رقــم ‪412‬ع‬\n‫يف‪ 1434/3/10‬ه ـ املوجــه الــى ســعادة مديــر مــرور محافظــة جــدة‬\n‫املتضمــن طلــب ابــاغ منســوبهم املدعــى عليــه حلضــور هــذه اجللســة انتهــى‬\n‫ولــم يردنــا شــيء بخصــوص هــذا اخلطــاب كمــا اطلعــت علــى االقــرار‬\n‫املرفــق بصــورة اخلطــاب املرفــق بعاليــه والصــادر مــن عمــدة مركــز ‪......‬‬\n‫بتاريــخ ‪1434/3/4‬ه ـ املتضمــن ان املدعــى عليــه يعمــل مبــرور محافظــة‬\n‫جــدة انتهــى وبســؤال املدعــي عــن مــا ورد يف اقــرار العمــدة اجــاب انــه‬\n‫غيــر صحيــح وان املدعــى عليــه ليــس موظفـ ًا مدنيـ ًا وال عســكري ًا وانــه‬\n‫يســكن يف رضــوان هكــذا اجــاب ومبــا ان العمــدة مخــول نظامـ ًا مبثــل‬\n‫هــذه االفــادات فقــد قــررت انتظــار جــواب مديــر مــرور جــدة للتحقــق مــن‬\n‫ذلــك وقــررت رفــع اجللســة إلبــاغ املدعــى عليــه للمــرة الثالثــة ويف جلســة‬\n\n                                                                                      ‫‪262‬‬\n\f      ‫اخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه ولــم يردنــا شــيء علــى‬\n      ‫خطابنــا املوجــه ملديــر مــرور محافظــة جــدة لتبليــغ املدعــى عليــه مبوعــد‬\n      ‫هــذه اجللســة ‪ .............‬وقــد قــرر املدعــي بقولــه ان االســم الصحيــح‬\n      ‫للمدعــى عليــه هــو ‪ .............‬ويســكن يف مركــز ‪ ......‬وليــس موظفــا‬\n      ‫مدنيــا وال عســكريا هكــذا قــرر فبنــاء عليــه قــررت الكتابــة لشــرطة‬\n      ‫رضــوان إلبــاغ املدعــى عليــه بعدمــا صحــح املدعــي اســمه ويف جلســة‬\n      ‫اخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه ولــم يردنــا مــا يفيــد‬\n      ‫تبلغــه مــن عدمــه علــى خطابنــا املوجــه الــى شــرطة ‪ ......‬برقــم ‪34 /153‬‬\n      ‫يف ‪1434/5/7‬ه ـ لــذا قــررت رفــع اجللســة ال بــاغ املدعــى عليــه مــرة‬\n      ‫اخــرى ويف جلســة اخــرى حضــر املدعــي ولــم يحضــر املدعــى عليــه وقــد‬\n      ‫وردنــا خطــاب مديــر مركــز شــرطة ‪ ......‬رقــم ‪ 895‬يف ‪1434/6/26‬ه ـ‬\n      ‫بخصــوص تبليــغ املدعــى عليــه حلضــور هذه اجللســة واملتضمــن (نفيدكم‬\n      ‫انــه جــرى البحــث والتحــري طــوال هــذه املــدة مبنطقــة ‪ ......‬ولــم يتــم‬\n      ‫العثــور عليــه كمــا يتضــح مــن احملاضــر املرفقــة) انتهــى وقــد جــرى‬\n      ‫اطالعــي عليهــا فوجدتهــا ســبعة محاضــر كل محضــر يف يــوم مســتقل‬\n      ‫وتوافــق مــا جــاء يف خطــاب مديــر الشــرطة ثــم قــرر املدعــي بقولــه ان‬\n      ‫املدعــى عليــه لديــه علــم بالدعــوى هكــذا قــرر ومبــا أن الفقهــاء نصــوا‬\n      ‫علــى أن الدعــوى تســمع علــى الغائــب واملســتتر مــن بــاب أولــى لــذا قــررت‬\n      ‫ا لقــد‬\n            ‫ســماع الدعــوى غيابيــا يف حــق املدعــى عليــه ثــم ادعــى املدعــي قائـ ً‬\n      ‫بعــت املدعــى عليــه الغائــب عــن مجلــس احلكــم ‪ .......‬يف شــهر ذي القعــدة‬\n      ‫لعام‪1433‬ه ـ ال اذكــر اليــوم بالتحديــد عــدد ثمــان مــن اإلبــل ســبع منهــا‬\n      ‫نيــاق وفحــل واحــد وأوصــاف النيــاق ثــاث منهــا ألوانهــا عفــر واحــدة‬\n      ‫عمرهــا حوالــي ثــاث ســنني وواحــدة فاطــر وواحــدة عمرهــا حوالــي أربع‬\n\n\n‫‪263‬‬\n\f‫ســنني وعليهــا وســمنا نحــن ‪ .............‬وهــو مغــزل علــى الرقبــة مــن اجلهــة‬\n‫اليمنــى ومطرقــن علــى اخلــد األميــن واثنتــان الوانهــن مجاهيــم وعمرهمــا‬\n‫حوالــي ثــاث ســنني وواحــدة لونهــا صفــراء وعمرهــا حوالــي ثــاث ســنني‬\n‫وواحــدة لونهــا ملحــاء وهــي فاطــر وعليهــا وســم مشــعاب يف الرقبــة مــن‬\n‫اجلهــة اليمنــى والبعيــر لونــه عفــر هــذا الــذي اذكــره مــن أوســامهن‬\n‫وأوصافهــن وأنواعهــا كلهــا عربيــة وثمــن الناقــة الواحــدة عشــرة آالف‬\n‫ريــال‪ 10000‬وثمــن البعيــر احــد عشــر ألــف ريــال‪ 11000‬ومجمــوع املبلــغ‬\n‫واحــد وثمانــون ألــف ريــال ‪ 81000‬علــى أن يســددنيها بعــد شــهرين مــن‬\n‫املبايعــة وقــد وصلنــي منــه مبلغــا وقــدره ثالثــة آالف ريــال‪ 3000‬وتبقــى‬\n‫لــي بذمتــه ثمانيــة وســبعون ألــف ريــال‪ 78000‬اطلــب إلزامــه واحلكــم‬\n‫عليــه بتســليمي املبلــغ املتبقــي وقــدره ثمانيــة وســبعون ألــف ريــال‪78000‬‬\n‫وبســؤاله ألديــك بينــة علــى دعــواك فقــال نعــم لدي شــاهدان األول يدعى‬\n‫‪ ............‬والثانــي ‪ .............‬اطلــب إمهالــي إلحضارهمــا وعليــه قــررت رفــع‬\n‫اجللســة إلحضــار املدعــي بينتــه ويف جلســة اخــرى حضــر املدعــي ولــم‬\n‫يحضــر املدعــى عليــه وقــد وردنــا خطــاب مديــر مركــز شــرطة ‪ ......‬رقــم‬\n‫‪ 895‬يف ‪1434/6/26‬ه ـ بخصــوص تبليــغ املدعــى عليــه حلضــور هــذه‬\n‫اجللســة واملتضمــن (نفيدكــم انــه جــرى البحــث والتحــري طــوال هــذه‬\n‫املــدة مبنطقــة رضــوان ولــم يتــم العثــور عليــه كمــا يتضــح مــن احملاضــر‬\n‫املرفقــة) انتهــى وقــد جــرى اطالعــي عليهــا فوجدتهــا ســبعة محاضــر‬\n‫كل محضــر يف يــوم مســتقل وتوافــق مــا جــاء يف خطــاب مديــر الشــرطة‬\n‫ثــم قــرر املدعــي بقولــه ان املدعــى عليــه لديــه علــم بالدعــوى هكــذا قــرر‬\n‫ومبــا أن الفقهــاء نصــوا علــى أن الدعــوى تســمع علــى الغائــب واملســتتر‬\n‫مــن بــاب أولــى لــذا قــررت ســماع الدعــوى غيابيــا يف حــق املدعــى عليــه‬\n\n\n                                                                                        ‫‪264‬‬\n\f      ‫ا لقــد بعــت املدعــى عليــه الغائــب عــن مجلــس‬       ‫ثــم ادعــى املدعــي قائ ـ ً‬\n      ‫احلكــم ‪ ..............‬يف شــهر ذي القعــدة لعام‪1433‬ه ـ ال اذكــر اليــوم‬\n      ‫بالتحديــد عــدد ثمــان مــن اإلبــل ســبع منهــا نيــاق وفحــل واحــد وأوصــاف‬\n      ‫النيــاق ثــاث منهــا ألوانهــا عفــر واحــدة عمرهــا حوالــي ثــاث ســنني‬\n      ‫وواحــدة فاطــر وواحــدة عمرهــا حوالــي أربــع ســنني وعليهــا وســمنا نحــن‬\n      ‫‪ ..........‬وهــو مغــزل علــى الرقبــة مــن اجلهــة اليمنــى ومطرقــن علــى اخلــد‬\n      ‫األميــن واثنتــان الوانهــن مجاهيــم وعمرهمــا حوالــي ثــاث ســنني وواحــدة‬\n      ‫لونهــا صفــراء وعمرهــا حوالــي ثــاث ســنني وواحــدة لونهــا ملحــاء وهــي‬\n      ‫فاطــر وعليهــا وســم مشــعاب يف الرقبــة مــن اجلهــة اليمنــى والبعيــر لونــه‬\n      ‫عفــر هــذا الــذي اذكــره مــن أوســامهن وأوصافهــن وأنواعهــا كلهــا‬\n      ‫عربيــة وثمــن الناقــة الواحــدة عشــرة آالف ريــال‪ 10000‬وثمــن البعيــر‬\n      ‫أحــد عشــر ألــف ريــال‪ 11000‬ومجمــوع املبلــغ واحــد وثمانــون ألــف ريــال‬\n      ‫‪ 81000‬علــى أن يســددنيها بعــد شــهرين مــن املبايعــة وقــد وصلنــي منــه‬\n      ‫مبلغــا وقــدره ثالثــة آالف ريــال‪ 3000‬وتبقــى لــي بذمتــه ثمانيــة وســبعون‬\n      ‫ألــف ريــال‪ 78000‬اطلــب إلزامــه واحلكــم عليــه بتســليمي املبلــغ املتبقــي‬\n      ‫وقــدره ثمانيــة وســبعون ألــف ريــال‪ 78000‬وبســؤاله ألديــك بينــة علــى‬\n      ‫دعــواك فقــال نعــم لــدي شــاهدان األول يدعــى ‪ ...........‬والثانــي‪..............‬‬\n      ‫اطلــب إمهالــي إلحضارهمــا وعليــه قــررت رفــع اجللســة إلحضــار املدعــي‬\n      ‫بينتــه ويف جلســة اخــرى وحضــر املدعــي ولــم يحضــر املدعــى عليــه ولــم‬\n      ‫تردنــا إفــادة علــى تبلغــه مــن عدمــه مــن شــرطة رضــوان وبســؤال املدعــي‬\n      ‫هــل أحضــرت شــهودك فقــال نعــم أحضــرت ‪......‬وأمــا ‪ ......‬فليــس معــه مــا‬\n      ‫يثبــت هويتــه وبالفعــل احضــر‪ .............‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ............‬وبســؤاله عمــا لديــه مــن شــهادة قــال اشــهد هلل‬\n\n\n‫‪265‬‬\n\f‫انــه يف شــهر ذي القعــدة لعــام ‪1433‬ه ـ حضــرت املدعــي وقــد بــاع ســبع‬\n‫نيــاق اثنتــان منهــا الوانهــا مجاهيــم وواحــدة لونهــا صفــراء وفحــل لونــه‬\n‫عفــر والباقــي ال اذكــر ألوانهــن باعهــن علــى ‪ ...............‬مببلــغ وقــدره‬\n‫واحــد وثمانــون ألــف ريــال‪ 81000‬ثمــن الواحــدة مــن النيــاق عشــرة آالف‬\n‫ريــال‪ 10000‬وثمــن البعيــر احــد عشــر ألــف ريال‪11000‬علــى أن يســدده‬\n‫املبلــغ بعــد مــدة قريبــة ال اذكرهــا وبعــد شــهرين مــن املبايعــة ذهبــت مــع‬\n‫املدعــي للمدعــى عليــه لطلــب املبلــغ املتبقــي وقــدره ثمانيــة وســبعني ألــف‬\n‫ريــال‪ 78000‬فوعــد بتســديدها للمدعــي هكــذا شــهد وبطلــب املدعــي‬\n‫تزكيــة شــاهدها حضــر كال مــن ‪ ............‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...........‬و‪ ............‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم‪ .............‬وشــهد كل واحــد مبفــردة قائــا أن الشــاهد عقــاب‬\n‫عــدل ثقــة هكــذا شــهدا فســألت املدعــي هــل أنــت مســتعد باحللــف علــى‬\n‫دعــواك مــع شــاهدك فقــال نعــم بعــد حتذيــري لــه مــن خطــر اليمــن إن‬\n‫كانــت كاذبــة فأصــر فأذنــت لــه فحلــف قائــا واهلل العظيــم لقــد بعــت‬\n‫املدعــى عليــه الغائــب عــن مجلــس احلكــم ‪ .............‬يف شــهر ذي القعــدة‬\n‫لعام‪1433‬ه ـ ال اذكــر اليــوم بالتحديــد عــدد ثمــان مــن اإلبــل ســبع منهــا‬\n‫نيــاق وفحــل واحــد وأوصــاف النيــاق ثــاث منهــا ألوانهــا عفــر واحــدة‬\n‫عمرهــا حوالــي ثــاث ســنني وواحــدة فاطــر وواحــدة عمرهــا حوالــي‬\n‫أربــع ســنني وعليهــا وســمنا نحــن ‪ ..........‬وهــو مغــزل علــى الرقبــة مــن‬\n‫اجلهــة اليمنــى ومطرقــن علــى اخلــد األميــن واثنتــان ألوانهــن مجاهيــم‬\n‫وعمرهمــا حوالــي ثــاث ســنني وواحــدة لونهــا صفــراء وعمرهــا حوالــي‬\n‫ثــاث ســنني وواحــدة لونهــا ملحــاء وهــي فاطــر وعليهــا وســم مشــعاب‬\n‫يف الرقبــة مــن اجلهــة اليمنــى والبعيــر لونــه عفــر وأنواعهــا كلهــا‬\n\n\n                                                                                      ‫‪266‬‬\n\f      ‫عربيــة وثمــن الناقــة الواحــدة عشــرة آالف ريــال‪ 10000‬وثمــن البعيــر‬\n      ‫احــد عشــر ألــف ريــال‪ 11000‬ومجمــوع املبلــغ واحــد وثمانــون ألــف ريــال‬\n      ‫‪ 81000‬علــى أن يســددنيها بعــد شــهرين مــن املبايعــة وقــد وصلنــي منــه‬\n      ‫مبلغــا وقــدره ثالثــة آالف ريــال‪ 3000‬وتبقــى لــي بذمتــه ثمانيــة وســبعون‬\n      ‫ألــف ريــال‪ 78000‬لــم يســددنيها وال شــيء منهــا واهلل العظيــم فبنــاء علــى‬\n      ‫مــا ســبق مــن الدعــوى ولشــهادة الشــاهد املعــدل شــرعا وحللــف املدعــي‬\n      ‫اليمــن تكملــة لبينتــه بعــد إذنــي حتذيــري لــه مــن خطرهــا إن كانــت‬\n      ‫كاذبــة وملــا رواه ابــن عبــاس رضــي اهلل عنهمــا إن النبــي صلــى اهلل عليــه‬\n      ‫وســلم قضــى بيمــن وشــاهد رواه مســلم لذلــك كلــه فقــد حكمــت‬\n      ‫علــى املدعــى عليــه بــأن يســلم للمدعــي املبلــغ املتبقــي مــن املبايعــة وقــدره‬\n      ‫ثمانيــة وســبعون الــف ريــال‪ 78000‬وان الغائــب علــى حجتــه متــى حضــر‬\n      ‫وقــررت تســليم املدعــى عليــه صــورة مــن احلكــم لتقــدمي مــا لديــه مــن‬\n      ‫اعتــراض وان لــه مهلــة ثالثــون يومـ ًا مــن تاريــخ اســتالمه لصــورة احلكــم‬\n      ‫واذا انتهــت هــذه املهلــة ولــم يتقــدم بشــي فيســقط حقــه يف طلــب التمييــز‬\n      ‫ـاء علــى املادتــن السادســة والســبعني‬       ‫ويكتســب احلكــم القطعيــة بنـ ً‬\n      ‫بعــد املائــة والثامنــة والســبعني بعــد املائــة مــن نظــام املرافعــات الشــرعية‬\n      ‫ولوائحــه التنفيذيــة وأغلقــت اجللســة الســاعة التاســعة وصلــى اهلل علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/07/18‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء ‪1434 /10 /7‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة التاســعة والنصــف وقــد وردنــا خطــاب مديــر مركــز‬\n      ‫شــرطة ‪ .........‬رقم ‪ 1239‬يف ‪1434 /9 /1‬هـ ونص احلاجة منه نفيدكم‬\n      ‫بأنــه مت البحــث عــن املذكــور يف قريــة ‪ .........‬ولــم يتــم العثــور عليــه‬\n      ‫وذلــك كمــا يتضــح لكــم مــن صــور احملاضــر املرفقــة وكذلــك صــور‬\n\n\n‫‪267‬‬\n\f‫محضــر عمــدة مركــز رضــوان املرفــق هــذا واليــزال البحــث جــاري عــن‬\n‫املذكــور ويف حــال العثــور عليــه ســوف يتــم تســليمه صــورة مــن احلكــم‬\n‫الصــادر ضــده انتهــى ولتعــذر تبليغــه قــررت بعــث كامــل أوراق املعاملــة‬\n‫حملكمــة االســتئناف مبنطقــة مكــة املكرمــة بــدون الئحــة اعتراضيــة‬\n‫بنــاء علــى الفقــرة اخلامســة مــن املــادة السادســة والســبعني بعــد املائــة مــن‬\n‫نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة وعليــه أغلقــت اجللســة‬\n‫الســاعة العاشــرة وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                  ‫وســلم حــرر ‪1434 /10 /7‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الثالثــاء ‪1434/11/11‬ه ـ افتتحــت‬\n‫اجللســة الســاعة التاســعة وقد عادت املعاملة من فضيلة رئيس محكمة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة املكلــف برقــم ‪342284783‬‬\n‫وتاريــخ ‪1434/10/22‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة قضــاة‬\n‫الدائــرة احلقوقيــة اخلامســة رقــم ‪ 34339440‬وتاريــخ ‪1434/10/25‬ه ـ‬\n‫ونــص احلاجــة منــه (وبدراســة احلكــم وصــورة ضبطــه تقــرر إعادتهــا‬\n‫لفضيلــة حاكمهــا حيــث ثبــت مــن أوراق املعاملــة أن املدعــى عليــه يعمــل‬\n‫يف مــرور جــده ومــا أجــراه فضيلــة حاكمهــا بخطابــه رقــم ‪34811797‬‬\n‫يف ‪1434/4/2‬ه ـ بعــد إقــرار عمــدة رضــوان بــأن املدعــى عليــه يعمــل‬\n‫يف جــده يف غيــر محلــه ألنــه ال واليــة لــه يف جــده وعليــه إفهــام املدعــي‬\n‫بإقامــة دعــواه يف مقــر عمــل املدعــى عليــه بجــده) انتهــى وعليــه أجيــب‬\n‫أصحــاب الفضيلــة وفقهــم اهلل بــأن األمــر ليــس كمــا ورد يف املالحظــة‬\n‫بــل إن نظــر الدعــوى داخــل يف واليتــي وذلــك ظاهــر مــن ضبــط جلســة‬\n‫يــوم االثنــن ‪1434/5/6‬ه ـ والــذي يتضــح مــن خاللهــا أن اســم املدعــى‬\n‫عليــه املنظــورة ضــده الدعــوى هــو ‪ .............‬ويســكن يف رضــوان‬\n\n\n                                                                                         ‫‪268‬‬\n\f      ‫وليــس موظفــا مدنيــا وال عســكريا وأمــا إفــادة عمــدة مركــز رضــوان‬\n      ‫فكانــت بنــاء علــى أن اســم جــد املدعــى عليــه هــو ‪ .........‬والصحيــح هــو‬\n      ‫‪ ..........‬فوقــع اخللــط بينهمــا يف اســم اجلــد لعــدم بيانــه مــن قبــل املدعــي يف‬\n      ‫صحيفــة دعــواه إال بعــد وقــوع اخللــط يف األســماء وألجــل ذا مضيــت يف‬\n      ‫نظــر الدعــوى وقــررت رفــع املعاملــة حملكمــة االســتئناف وعليــه أغلقــت‬\n      ‫اجللســة الســاعة التاســعة والنصــف وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/11/11‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ............‬رئيــس احملكمــة العامــة باملويه‬\n      ‫ففــي يــوم اخلميــس املوافــق‪ 1435/01/04‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫التاســعة والنصــف وقــد عــادت املعاملــة بخطــاب رئيــس محكمــة‬\n      ‫االســتئناف مبنطقــة مكــة املكرمــة املســاعد برقــم ‪ 342583084‬يف‬\n      ‫‪1434/12/29‬ه ـ وبرفقهــا قــرار قضــاة الدائــرة احلقوقيــة اخلامســة رقــم‬\n      ‫‪ 34377010‬يف ‪1434/12/3‬ه ـ املتضمــن وبدراســة احلكــم وصــورة‬\n      ‫ضبطــه تقــرر املوافقــة علــى احلكــم بعــد اإليضــاح األخيــر والغائــب علــى‬\n      ‫حجتــه إذا حضــر انتهــى وقــررت التهميــش بذلــك علــى ســجله وعليــه‬\n      ‫أغلقــت اجللســة الســاعة العاشــرة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n      ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1435/01/04‬ه ـ ‪.‬‬\n\n\n\n\n‫‪269‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":261,"source_page_end":269,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"4fdd708ce27ed31256fc5ccaaf259e1e13f81d435cd42330c987c783591b3e56","normalized_text_hash":"b24ce9f39224ace63240371c5a120883fba72310b4c1f77be6fdc6c250e0f79c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p261-34272302"},{"id":"1bcb2883-2d56-5236-b688-be68bf66b46e","document_type":"judgment","category":"judicial","subcategory":"general","title":"بيع -املبايعة على أرض ليس عليها صك شرعي -احلكم ببطان البيع وإرجاع ثمن األرض لعدم تنفيذ الشروط -احلكم ال يفيد التملك وال يغني عن حجة االستحكام .","document_number":"34213467","case_number":"3474551","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/14","year":"1434","subject":"بيع -املبايعة على أرض ليس عليها صك شرعي -احلكم ببطان البيع وإرجاع ثمن األرض لعدم تنفيذ الشروط -احلكم ال يفيد التملك وال يغني عن حجة االستحكام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/14 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34213467 :‬‬\n                    ‫َر ْق ُم الدعوى‪3474551 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34244884‬تاريخه‪1434/6/19 :‬هـ‬\n\n\n‫بيــع ‪ -‬املبايعــة علــى أرض ليــس عليهــا صــك شــرعي ‪ -‬احلكــم ببطــان‬\n‫البيــع وإرجــاع ثمــن األرض لعــدم تنفيــذ الشــروط ‪ -‬احلكــم ال يفيــد‬\n                          ‫التملــك وال يغنــي عــن حجــة االســتحكام ‪.‬‬\n\n\n\n\n‫قولــه صلــى اهلل عليــه وســلم (املســلمون علــى شــروطهم) رواه أحمــد‬\n                                                           ‫وأبــو داوود ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي ضــد املدعــى عليــه مبطالبتــه بإبطــال عقــد البيــع وإلزامــه‬\n‫بإعــادة مــا اســتلمه مــن املدعــي وقــدره ســبعة وثالثــون ألف ـ ًا وخمســمائة‬\n‫ريــال لكونــه لــم ينفــذ الشــرط وبــاع مــا ال ميلــك ‪ ،‬حيــث اشــترى‬\n‫املدعــي مــن املدعــى عليــه قطعــة أرض بيضــاء معقمــة ليــس عليهــا صــك‬\n‫شــرعي واشــترط عليــه بــأن يتعهــد بحمايتــه مــن أي منازعــات مــن قبــل‬\n‫املواطنــن‪ ،‬التــزم املدعــى عليــه بهــذا الشــرط لكنــه لــم ينفــذه حيــث‬\n‫قــام أحــد املواطنــن بشــكاية املدعــي واعتراضــه علــى التملــك ولــم يقــم‬\n‫املدعــى عليــه بحمايتــه ‪ ،‬صــادق املدعــى عليــه علــى البيــع وعلــى الشــرط‬\n‫وعلــى عــدم وجــود صــك شــرعي عليهــا وعلــى اعتــراض أحــد املواطنــن‬\n‫للمدعــي وأنــه ليــس داخــل يف الشــرط ألن اعتراضــه للمصلحــة العامــة‬\n\n                                                                                    ‫‪270‬‬\n\f      ‫وليــس للتملــك ‪ ،‬أبــرز املدعــي عقــد املبايعــة وقــد نــص علــى تعهــد املدعى‬\n      ‫عليــه علــى حمايتــه مــن أي منازعات وعلى أن للمدعي التصرف بكامل‬\n      ‫األرض املباعــة ‪ ،‬صــادق املدعــى عليــه علــى العقــد ‪ ،‬وحيــث نــص عقــد‬\n      ‫املبايعــة أعــاه علــى تعهــد الطــرف األول بحمايــة الطــرف الثانــي مــن‬\n      ‫أي منازعــات مــن قبــل املواطنــن وحيــث اعتــرف املدعــى عليــه بأنــه لــم‬\n      ‫يســتطع حمايــة املدعــي مــن منازعــة أحــد املواطنــن وهــو مــن ســكان‬\n      ‫نفــس القريــة حســب جــواب املدعــى عليــه وحيــث إن عقــد املبايعــة لــم‬\n      ‫يرصــد فيــه ذكــر لطريــق يشــق األرض املباعــة نصفــن بــل نــص العقــد‬\n      ‫علــى أن للمشــتري التصــرف الكامــل بــاألرض املباعــة باإلحيــاء دون‬\n      ‫أي شــروط أو قيــود مــن ســكان القريــة ا‪.‬ه ـ ولقولــه صلــى اهلل عليــه‬\n      ‫وســلم (املســلمون علــى شــروطهم) وحيــث لــم يلتــزم املدعــى عليــه بتنفيــذ‬\n      ‫هــذا الشــرط ‪ ،‬احلكــم ببطــان عقــد البيــع أعــاه وإلــزام املدعــى عليــه‬\n      ‫بإرجــاع ثمــن األرض إلــى املدعــي حــا ًال ‪ ،‬قنــع املدعــي باحلكــم واعتــرض‬\n      ‫املدعــى عليــه بالئحــة ‪ ،‬جــرى إفهــام الطرفــن بــأن هــذا احلكــم ال يفيــد‬\n      ‫التملــك وال يغنــي عــن حجــة االســتحكام ‪ ،‬صــدق احلكــم مــن الدائــرة‬\n          ‫احلقوقيــة الســابعة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )....‬القاضــي يف احملكمــة العامــة‬\n      ‫باملدينة املنورة وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n      ‫العامــة باملدينــة املنــورة برقــم ‪ 3474551‬وتاريــخ ‪1434/02/13‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 34374318‬وتاريــخ ‪ 1434/02/13‬ه ـ ففــي‬\n      ‫يــوم الثالثــاء املوافــق‪ 1434/05/14‬ه ـ افتتحــت اجللســة الســاعة ‪08 : 15‬‬\n\n‫‪271‬‬\n\f‫وفيهــا حضــر ‪ ........‬ســعودي بالســجل املدنــي ‪ ........‬وادعــى علــى احلاضــر‬\n‫ا يف دعــواه ‪ :‬إنــه بتاريــخ‬\n                            ‫معــه ‪ ........‬ســعودي بالســجل املدنــي ‪ ........‬قائـ ً‬\n‫‪1433/1/26‬ه ـ اشــتريت قطعــة أرض بيضــاء معقمــة وليــس عليهــا صــك‬\n‫شــرعي مــن املدعــى عليــه هــذا احلاضــر‪ ........‬وتقــع يف قريــة ‪ ........‬حــي‬\n‫‪ ........‬ويحدهــا شــما ًال طريــق ‪ ........‬ثــم مســجد ‪ ...‬واســتراحة ‪........‬‬\n‫وروضــة ‪ ........‬وجنوبـ ًا طريــق ‪ ........‬وأرض ‪ ........‬وشــرق ًا مجــرى الســيل‬\n‫‪ ........‬وأرض ‪ ........‬وغربـ ًا الطريــق الواصــل بــن طريقــي ‪ ........‬ثــم أرض‬\n‫أبنــاء ‪ .....‬مببلــغ مقــداره ســبعة وثالثــون ألف ـ ًا وخمســمائة( ‪)37500‬‬\n‫ريــال اســتلمها املدعــى عليــه عــد ًا ونقــد ًا واشــترطت عليــه أن يتعهــد‬\n‫بحمايتــي مــن أي منازعــات مــن قبــل املواطنــن والتــزم لــي بهــذا الشــرط‬\n‫ولكنــه لــم ينفــذه حيــث تقــدم املواطــن ‪ ........‬بشــكايتي واعتراضــي‬\n‫علــى متلكــي لهــذه األرض وأزيلــت حدودهــا ومعاملهــا وعقومهــا مــن قبــل‬\n‫ـاء علــى شــكوى املواطــن املذكــور ولــم يقــم املدعــى‬   ‫مركــز إمــارة ‪ ....‬بنـ ً‬\n‫عليــه بحمايتــي مــن املواطــن املذكــور بــل ملــا طلبــت منــه املســاعدة قــال‬\n‫لــي ‪:‬تســتاهل وهــو قــد تعهــد لــي بحمايتــي مــن أي منازعــات مــن قبــل‬\n‫املواطنــن وأطلــب إلزامــه باســترجاع مادفعتــه إليــه وهــو مبلــغ مقــداره‬\n‫ســبعة وثالثــون ألف ـ ًا وخمســمائة (‪ )37500‬ريــال وإبطــال عقــد املبايعــة‬\n‫هــذا لكونــه لــم ينفــذ الشــرط ولكونــه بــاع مــا ال ميلــك حيــث ملــا أبــرزت‬\n‫عقــد املبايعــة أمــام رئيــس مركــز ‪ ....‬أجابنــي بــأن عقــد املبايعــة هــذا‬\n‫ال يفيــد التملــك وال ينفعــك بشــيء هــذه دعــواي‪ .‬وبســؤال املدعــى عليــه‬\n‫ا ‪ :‬ماذكــره املدعــي يف دعــواه غيــر صحيــح والصحيــح أنــه‬           ‫أجــاب قائـ ً‬\n‫بتاريــخ ‪1433/1/26‬ه ـ بعــت علــى املدعــي أرض معقمــة وليــس عليهــا‬\n‫صــك شــرعي وتقــع يف قريــة ‪ ........‬حــي ‪ ........‬طريــق ‪ .......‬حســب‬\n\n\n                                                                                        ‫‪272‬‬\n\f      ‫حدودهــا التــي ذكرهــا املدعــي مببلــغ ســبعة وثالثــون ألفـ ًا وخمســمائة‬\n      ‫(‪ )37500‬ريــال اســتلمتها كاملــة وتعهــدت لــه بحمايتــه مــن أي‬\n      ‫منازعــات مــن املواطنــن الطماعــن ولكــن املواطــن ‪ ........‬لــم يدعــي‬\n      ‫متلكهــا ولكنــه تقــدم لالعتــراض للمصلحــة العامــة وهــذا غيــر داخــل‬\n      ‫يف الشــرط حيــث أن الشــرط ينــص علــى املواطنــن الطامعــن فقــط‬\n      ‫دون املعترضــن للمصلحــة العامــة ثــم أبــرز املدعــي عقــد مبايعــة األرض‬\n      ‫وهــذا نصــه (احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد لقــد‬\n      ‫مت االتفــاق بــن كل مــن ‪( ........ :‬طــرف أول) ‪( ........‬طــرف ثانــي)‬\n      ‫حيــث قــام الطــرف األول ببيــع األرض الواقعــة يف قريــة ‪ ........‬حــي ‪.....‬‬\n      ‫والتــي يحدهــا مــن جهــة الشــمال ‪ ........‬واســتراحة ‪ ........‬وروضــة ‪........‬‬\n      ‫ا بــن األرض املباعــة وحدودهــا مــن‬     ‫حيــث يقــع طريــق ‪ ........‬حــد ًا فاصـ ً‬\n      ‫الشــمال ومــن جهــة الشــرق يحدهــا مجــرى الســيل ‪ ........‬وأرض ‪........‬‬\n      ‫ومــن جهــة اجلنــوب يحدهــا طريــق الرحبــة وأرض ‪ ........‬ويحدهــا مــن‬\n      ‫جهــة الغــرب أرض أبنــاء ‪ ........‬حيــث يفصــل بينهمــا الطريــق الواصــل‬\n      ‫بــن طريقــي ‪ ........‬و‪ ........‬مببلــغ قــدره ‪( 37500‬ســبعة وثالثــون ألف ـ ًا‬\n      ‫وخمــس مئــة ريــال ســعودي) وتعهــد الطــرف األول بحماية الطــرف الثاني‬\n      ‫مــن أي منازعــات مــن قبــل املواطنــن كمــا أن الطــرف الثانــي لــه احلق يف‬\n      ‫التصــرف الكامــل بــاألرض املباعــة بالبيــع أو اإلحياء دون أي شــروط أو‬\n      ‫قيــود مــن ســكان القريــة ‪ .‬واهلل املوفــق ‪ ) ...‬انتهــى وبعرضــه على املدعى‬\n      ‫ا ‪ :‬لــم أســتطع‬  ‫عليــه صــادق عليــه حرفـ ًا بحــرف وقــرر املدعــى عليــه قائـ ً‬\n      ‫مســاعدة وحمايــة املدعــي مــن منازعــة املواطــن ‪ ........‬وهــو مــن ســكان‬\n      ‫نفــس القريــة لكــون منازعــة املواطــن املذكــور وشــكواه للمصلحــة‬\n      ‫العامــة وليســت للمصلحــة اخلاصــة حيــث أن املواطــن‪ ........‬يطالــب بفتــح‬\n\n\n‫‪273‬‬\n\f‫الطريــق الــذي يشــق األرض املباعــة نصفــن حيــث قــام املدعــي بإغالقــه‬\n‫هــذا جوابــي وبعرضــه علــى املدعــي أجــاب قائـاً‪ :‬األرض التــي اشــتريتها‬\n‫ال يشــقها أي طريــق وهــذا مــا نــص عليــه عقــد املبايعــة هــذا جوابــي ثــم‬\n‫باطالعــي أنــا حاكــم القضيــة علــى عقــد املبايعــة املذكــور تبــن أنــه‬\n‫لــم يرصــد فيــه ذكــر لطريــق يشــق األرض املباعــة نصفــن انتهــى ثــم‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬‫إنــه وبعــد التأمــل يف القضيــة وبنـ ً‬\n‫وحيــث نــص عقــد املبايعــة أعــاه علــى تعهــد الطــرف األول بحمايــة‬\n‫الطــرف الثانــي مــن أي منازعــات مــن قبــل املواطنــن وحيــث اعتــرف‬\n‫املدعــى عليــه بأنــه لــم يســتطع حمايــة املدعــي مــن منازعــة املواطــن ‪........‬‬\n‫وهــو مــن ســكان نفــس القريــة حســب جــواب املدعــى عليــه وحيــث أن‬\n‫عقــد املبايعــة لــم يرصــد فيــه ذكــر لطريــق يشــق األرض املباعــة نصفــن‬\n‫بــل نــص العقــد علــى أن للمشــتري التصــرف الكامــل بــاألرض املباعــة‬\n‫باإلحيــاء دون أي شــروط أو قيــود مــن ســكان القريــة اه ـ ولقولــه صلــى‬\n‫اهلل عليــه وســلم (املســلمون علــى شــروطهم) رواه اإلمــام أحمــد وأبــو‬\n‫داود وحيــث لــم يلتــزم املدعــى عليــه بتنفيــذ هــذا الشــرط لذلــك فقــد‬\n‫حكمــت ببطــان عقــد البيــع أعــاه وألزمــت املدعــى عليــه بإرجــاع ثمــن‬\n‫األرض وذلــك بتســليم ســبعة وثالثــن ألف ـ ًا وخمســمائة (‪)37500‬ريــال‬\n‫إلــى املدعــي حــا ًال وقنــع املدعــي باحلكــم ولــم يقنــع املدعــى عليــه وطلــب‬\n‫محكمــة االســتئناف مبوجــب الئحــة اعتراضيــة وأجيــب لطلبــه وأفهــم‬\n‫بــأن لــه مهلــة ثالثــن يومـ ًا لتقــدمي الالئحــة االعتراضيــة ففهــم ذلــك كمــا‬\n‫افهمــت الطرفــن بــأن هــذا احلكــم اليفيــد التملــك واليصلــح لالحتجــاج‬\n‫بــه يف هــذا واليغنــي عــن حجــة االســتحكام وإمنــا هــو لرفــع النــزاع ففهما‬\n     ‫ذلــك وصلــى اهلل وســلم علــى نبينــا محمــد حــرر يف ‪1434/5/14‬هــ‪.‬‬\n\n\n                                                                                         ‫‪274‬‬\n\f      ‫احلمــد هلل وحــده‪ ،‬والصــاة والســام علــى مــن ال نبــي بعــده‪ ،‬وبعــد‪ :‬فقــد‬\n      ‫جــرى منــا نحــن قضــا َة الدائــرة احلقوقيــة الســابعة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باملدينــة املنــورة املســاعد برقــم ‪34/374318‬‬\n      ‫وتاريــخ ‪1434/06/10‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫‪ ........‬باحملكمــة العامــة باملدينــة املنــورة املســجل برقــم ‪ ........‬وتاريــخ‬\n      ‫‪1434/05/14‬ه ـ املتضمــن دعــوى ‪ ........‬ضــد ‪ ........‬وبدراســة الصــك‬\n      ‫وص ــورة ضبط ــه والئحتــه اإلعتراضيــة تق ــررت املوافق ــة عل ــى احلكــم‬\n             ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪275‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"17250706-b6cd-5618-b1f0-019e3dec82ff","source_page_start":270,"source_page_end":275,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f9c92817cb56b5d18f7090929e99d8b0bba4a7b09d1b03794d65b0a2eb82daf3","normalized_text_hash":"f504da947b3d9a5106e83c3a45d166a28e6b444ded5c3d8b12ce4eb549e2873d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v1-p270-34213467"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
